window.QUIZ_DATA = {"eras":["선사·고조선","삼국·가야","남북국","고려","조선 전기","조선 후기","개항기","일제강점기","현대","통합·기타"],"questions":[{"id":"60-1","r":"60","n":1,"era":"선사·고조선","topic":"신석기 시대 생활","exp":"정착 생활과 농경이 시작되었다는 설명과 빗살무늬 토기, 움집 그림은 신석기 시대를 가리킨다. 신석기 시대 사람들은 가락바퀴로 실을 뽑아 옷이나 그물을 만들었다. 철제 농기구 사용은 철기 시대, 청동 방울 같은 의례 도구는 청동기 시대의 모습이므로 구분해야 한다.","ans":1,"pts":2},{"id":"60-2","r":"60","n":2,"era":"선사·고조선","topic":"삼한의 사회","exp":"천군이 소도에서 제사를 주관하였다는 사료는 제사와 정치가 분리되어 있던 삼한에 대한 설명이다. 삼한에는 신지, 읍차 등으로 불리는 지배자가 있었다. 영고는 부여, 민며느리제는 옥저, 책화는 동예의 풍습이므로 헷갈리지 않아야 한다.","ans":2,"pts":3},{"id":"60-3","r":"60","n":3,"era":"삼국·가야","topic":"고구려 진대법","exp":"고국천왕이라는 도장과 관청의 곡식을 형편에 따라 빌려주고 나중에 갚게 한다는 내용은 고구려의 빈민 구제 제도인 진대법을 가리킨다. 진대법은 봄에 곡식을 빌려주고 추수 뒤에 갚게 하여 가난한 백성을 도운 제도이다. 흑창과 제위보는 고려의 구휼 제도이므로 시대가 다르다.","ans":3,"pts":2},{"id":"60-4","r":"60","n":4,"era":"통합·기타","topic":"독도의 역사","exp":"가지도라는 별칭, 대한 제국 칙령 제41호의 석도, 울도 군수 심흥택의 보고서라는 단서는 모두 독도를 가리킨다. 조선 숙종 때 안용복은 일본으로 건너가 울릉도와 독도가 우리 영토임을 주장하였다. 영국이 불법 점령한 섬은 거문도이므로 혼동하지 않아야 한다.","ans":4,"pts":1},{"id":"60-5","r":"60","n":5,"era":"삼국·가야","topic":"백제의 문화유산","exp":"공주와 부여에 도읍했던 나라는 백제이며, 정림사지 오층 석탑과 무령왕릉 석수도 백제 유산이다. 익산 미륵사지 석탑은 백제 무왕 때 세워진 현존 최대의 석탑이므로 (가)에 들어갈 수 있다. 첨성대와 성덕 대왕 신종은 신라, 무용총 수렵도는 고구려의 문화유산이다.","ans":2,"pts":2},{"id":"60-6","r":"60","n":6,"era":"삼국·가야","topic":"금관가야","exp":"김해 구지봉, 대성동 고분군, 수로왕릉 등 김해 지역의 유적이 단서로, '이 나라'는 금관가야이다. 금관가야는 김수로왕이 세운 나라로 전기 가야 연맹을 주도하였다. 국학 설치는 통일신라 신문왕, 22담로는 백제 무령왕의 정책이므로 혼동하지 않도록 한다.","ans":1,"pts":2},{"id":"60-7","r":"60","n":7,"era":"삼국·가야","topic":"신라 지증왕","exp":"순장을 금지하고 '신라국왕'이라는 호칭을 사용하기 시작했다는 삼국사기 내용이 단서로, 밑줄 그은 왕은 신라 지증왕이다. 지증왕은 소를 이용한 밭갈이인 우경을 장려하여 농업 생산력을 높였다. 율령 반포는 법흥왕, 독서삼품과 실시는 통일신라 원성왕의 업적이다.","ans":1,"pts":2},{"id":"60-8","r":"60","n":8,"era":"통합·기타","topic":"세시풍속 한식","exp":"동지로부터 105일째 되는 날로 불을 쓰지 않고 찬 음식을 먹는다는 설명은 세시풍속 한식에 해당한다. 한식에는 조상의 묘를 찾아 돌보고 성묘하는 풍습이 있었다. 단오는 음력 5월 5일에 그네뛰기와 씨름 등을 즐기던 명절이므로 구분해야 한다.","ans":3,"pts":1},{"id":"60-9","r":"60","n":9,"era":"삼국·가야","topic":"삼국 통일 과정","exp":"황산벌 전투(660)는 백제 멸망 직전의 싸움이고, 기벌포 전투(676)는 신라가 당군을 몰아낸 싸움이다. 두 사건 사이인 663년에 백제 부흥군과 왜의 연합군이 나당 연합군과 싸운 백강 전투가 일어났다. 살수 대첩(612)은 고구려가 수의 침입을 물리친 것으로 시기가 앞선다.","ans":1,"pts":3},{"id":"60-10","r":"60","n":10,"era":"남북국","topic":"신라 하대의 동요","exp":"혜공왕 이후 왕위 쟁탈전과 원종·애노의 봉기 등은 신라 하대의 혼란한 상황을 보여준다. 이 시기인 822년에 웅주 도독 김헌창이 아버지가 왕이 되지 못한 데 불만을 품고 난을 일으켰다. 이자겸의 난과 망이·망소이의 난은 고려 시대의 사건이다.","ans":1,"pts":2},{"id":"60-11","r":"60","n":11,"era":"남북국","topic":"발해 무왕","exp":"발해 타임라인에서 (가)는 무왕 대무예의 업적을 묻고 있다. 무왕은 장문휴를 보내 당의 산둥반도 등주를 공격하는 등 당과 대립하였다. 4군 6진 개척과 대마도 정벌은 조선 세종, 동북 9성 축조는 고려 윤관의 일이다.","ans":4,"pts":2},{"id":"60-12","r":"60","n":12,"era":"고려","topic":"후고구려 궁예","exp":"태봉의 도성 터와 철원으로 도읍을 옮겼다는 설명은 후고구려를 세운 궁예를 가리킨다. 궁예는 송악에서 후고구려를 세운 뒤 철원으로 천도하고 국호를 마진, 태봉으로 바꾸었다. 견훤은 완산주에서 후백제를 세운 인물이므로 구분해야 한다.","ans":2,"pts":2},{"id":"60-13","r":"60","n":13,"era":"고려","topic":"일연의 삼국유사","exp":"승려 일연이 저술하였고 단군의 고조선 건국 이야기가 실려 있다는 단서는 삼국유사를 가리킨다. 삼국유사는 고려 충렬왕 때 편찬되어 불교사와 설화, 향가 등을 풍부하게 담고 있다. 제왕운기도 단군 이야기를 담았으나 이승휴가 지은 책이므로 저자가 다르다.","ans":3,"pts":1},{"id":"60-14","r":"60","n":14,"era":"고려","topic":"경천사지 십층 석탑","exp":"고려 시대에 원의 영향을 받아 대리석으로 만들어졌다는 설명은 개성 경천사지 십층 석탑에 해당한다. 이 탑은 목조 건축을 연상시키는 화려한 조각이 특징이며 뒤에 조선의 원각사지 십층 석탑에 영향을 주었다. 영광탑은 발해의 벽돌 탑이므로 혼동하지 않아야 한다.","ans":4,"pts":2},{"id":"60-15","r":"60","n":15,"era":"고려","topic":"거란의 침입 격퇴","exp":"고려를 침입한 거란과의 항쟁 순서를 묻는 문항이다. 1차 침입 때 서희의 외교 담판(993)으로 강동 6주를 얻었고, 2차 침입 때 양규가 활약(1010)하였으며, 3차 침입 때 강감찬이 귀주 대첩(1019)으로 거란군을 크게 물리쳤다. 따라서 (가)-(나)-(다) 순서가 맞다.","ans":1,"pts":3},{"id":"60-16","r":"60","n":16,"era":"고려","topic":"무신 정권 교정도감","exp":"고려 무신 정권기 최고 권력 기구이며 최충헌이 설치하였다는 힌트는 교정도감을 가리킨다. 교정도감은 임시 기구로 출발하였으나 국정을 총괄하는 기구가 되었다. 중방은 무신 정변 직후 권력의 중심이 된 회의 기구이므로 구분해야 한다.","ans":2,"pts":2},{"id":"60-17","r":"60","n":17,"era":"고려","topic":"보조국사 지눌","exp":"발문에서 직접 지눌 스님의 활동을 묻고 있다. 지눌은 불교 개혁을 위해 수선사 결사를 제창하고 정혜쌍수와 돈오점수를 주장하였다. 무애가는 원효, 천태종 개창은 의천, 왕오천축국전 저술은 혜초의 활동이다.","ans":3,"pts":3},{"id":"60-18","r":"60","n":18,"era":"고려","topic":"고려 충신 정몽주","exp":"고려 시대 학자로 조선 건국 세력에 맞서 고려 왕조를 지키려 했고 문집으로 포은집이 있다는 단서는 정몽주를 가리킨다. 정몽주는 성리학에 밝은 고려 말 충신으로 이방원 세력에게 죽임을 당하였다. 정도전은 반대로 조선 건국을 주도한 인물이므로 구분해야 한다.","ans":3,"pts":1},{"id":"60-19","r":"60","n":19,"era":"조선 전기","topic":"조선 전기 과학 기술","exp":"15세기 조선의 과학 기술 발전에 기여한 인물 중 장영실의 업적을 묻고 있다. 장영실은 물시계인 자격루를 비롯해 여러 과학 기구를 제작하였다. 거중기는 조선 후기 정약용, 대동여지도는 김정호, 동의보감은 허준의 업적이다.","ans":2,"pts":2},{"id":"60-20","r":"60","n":20,"era":"고려","topic":"원 간섭기 생활","exp":"원 간섭기에는 몽골 문화의 영향으로 변발과 철릭이 유행하고 증류 방식의 소주가 만들어졌다. 그러나 고추는 임진왜란 무렵 일본을 통해 전래되었으므로 고추를 넣어 김치를 담그는 모습은 이 시기에 볼 수 없다. 따라서 ③이 옳지 않은 답변이다.","ans":3,"pts":2},{"id":"60-21","r":"60","n":21,"era":"조선 전기","topic":"감찰 기구 사헌부","exp":"관리의 비리를 감찰하고 수장이 대사헌이라는 단서는 사헌부를 가리킨다. 사헌부는 사간원, 홍문관과 함께 삼사로 불리며 언론 기능을 담당하였다. 왕명 출납은 승정원, 수도의 행정과 치안은 한성부의 역할이므로 구분해야 한다.","ans":4,"pts":2},{"id":"60-22","r":"60","n":22,"era":"조선 전기","topic":"통치 이념 성리학","exp":"신진사대부, 주자, 이황, 이이, 서원, 사림 등의 단어는 모두 성리학과 관련이 깊다. 성리학은 고려 말 안향이 들여온 뒤 조선의 통치 이념이 된 유학의 한 갈래이다. 양명학은 성리학을 비판하며 지행합일을 강조한 학문이므로 구분해야 한다.","ans":2,"pts":1},{"id":"60-23","r":"60","n":23,"era":"조선 전기","topic":"병자호란의 전개","exp":"인조가 남한산성으로 피신하였다는 단서는 1636년 청이 침입한 병자호란을 가리킨다. 전쟁에서 패한 조선은 삼전도에서 항복하고 청과 군신 관계를 맺었다. 김시민 장군의 활약과 명의 이여송 파병은 임진왜란 때의 일이므로 혼동하지 않아야 한다.","ans":3,"pts":2},{"id":"60-24","r":"60","n":24,"era":"조선 후기","topic":"예송과 환국","exp":"(가)는 효종 사후의 예송(1659년 기해예송), (나)는 영조가 세운 탕평비(1742)이다. 두 시기 사이인 1680년 숙종 때 경신환국이 일어나 서인이 집권하였다. 훈련도감 설치는 임진왜란 중, 무오사화는 연산군 때로 모두 (가) 이전의 일이다.","ans":3,"pts":3},{"id":"60-25","r":"60","n":25,"era":"조선 후기","topic":"홍경래의 난","exp":"1811년 서북(평안도) 지역민에 대한 차별에 반발해 일어났다는 설명은 홍경래의 난을 가리킨다. 몰락 양반 홍경래는 상인, 광산 노동자 등과 함께 봉기하여 정주성 등지에서 싸웠다. 백낙신의 횡포가 계기가 된 것은 1862년 임술 농민 봉기이므로 구분해야 한다.","ans":1,"pts":2},{"id":"60-26","r":"60","n":26,"era":"조선 후기","topic":"조선 후기 서민 문화","exp":"세책점에서 한글 소설 춘향전을 빌려 보고 상평통보를 쓰는 모습은 조선 후기의 상황이다. 이 시기에는 민화, 탈춤, 판소리 같은 서민 문화가 발달하였다. 팔관회는 고려 시대의 행사이므로 외국 사신이 팔관회에 참가하는 모습은 볼 수 없다.","ans":4,"pts":2},{"id":"60-27","r":"60","n":27,"era":"조선 후기","topic":"대동법의 시행","exp":"방납의 폐단을 배경으로 실시되었고 선혜청이 담당했으며 토지 결수를 기준으로 쌀, 옷감, 동전을 거두었다는 내용은 대동법이다. 대동법 시행으로 공인이 등장하고 상품 화폐 경제가 발달하였다. 균역법은 군포 부담을 줄여준 제도이므로 구분해야 한다.","ans":3,"pts":1},{"id":"60-28","r":"60","n":28,"era":"조선 후기","topic":"정조의 정책","exp":"혜경궁 홍씨의 회갑을 기념한 을묘년 화성 원행과 융릉이라는 단서는 정조를 가리킨다. 정조는 왕권 강화를 위해 친위 부대인 장용영을 설치하였다. 경국대전 완성은 성종, 경복궁 중건은 흥선대원군 집권기의 일이다.","ans":1,"pts":2},{"id":"60-29","r":"60","n":29,"era":"조선 후기","topic":"실학자 유형원","exp":"전북 부안의 반계 서당에 머물며 균전론 등을 담은 반계수록을 저술하였다는 단서는 유형원을 가리킨다. 유형원은 신분에 따라 토지를 차등 분배하자는 균전론을 주장한 중농학파 실학자이다. 이익은 성호사설, 홍대용은 지전설로 유명하므로 구분해야 한다.","ans":3,"pts":2},{"id":"60-30","r":"60","n":30,"era":"개항기","topic":"대한 제국 시기","exp":"고종이 환구단에서 황제 즉위식을 거행하고 새 국호를 선포했다는 내용은 1897년 수립된 대한 제국을 가리킨다. 대한 제국 시기인 1899년에는 황제권 중심의 대한국 국제가 제정되었다. 당백전 발행(흥선대원군)과 영선사 파견(1881), 육영 공원 설립(1886)은 모두 그 이전의 일이다.","ans":4,"pts":2},{"id":"60-31","r":"60","n":31,"era":"개항기","topic":"갑신정변의 전개","exp":"우정총국 개국 축하연을 기회로 일어났고 3일 천하로 끝났다는 단서는 1884년 갑신정변이다. 김옥균 등 급진 개화파는 정변을 일으켜 개혁 정강을 발표했으나 청군의 개입으로 3일 만에 실패하였다. 갑오개혁은 1894년 군국기무처를 중심으로 추진된 개혁이므로 구분해야 한다.","ans":2,"pts":1},{"id":"60-32","r":"60","n":32,"era":"개항기","topic":"을미의병의 봉기","exp":"국모 시해(을미사변)와 단발령에 반발해 일어났다는 내용은 1895년의 을미의병이며, 단발을 편한 대로 하게 했다는 말은 고종의 해산 조칙과 관련된다. 이는 청일 전쟁 발발(1894)과 국권 피탈(1910) 사이의 일이므로 연표에서 (라) 시기에 해당한다.","ans":4,"pts":3},{"id":"60-33","r":"60","n":33,"era":"개항기","topic":"신미양요와 척화비","exp":"미국 군대의 침입에 맞서 어재연 장군이 광성보에서 싸운 사건은 1871년 신미양요이다. 신미양요 직후 흥선대원군은 통상 수교 거부 의지를 밝히는 척화비를 전국에 세웠다. 병인박해, 제너럴 셔먼호 사건, 오페르트 도굴 사건은 모두 신미양요 이전의 일이다.","ans":2,"pts":3},{"id":"60-34","r":"60","n":34,"era":"개항기","topic":"헤이그 특사 이준","exp":"이상설, 이위종과 함께 헤이그 만국 평화 회의에 특사로 파견되었다는 단서는 이준을 가리킨다. 이준은 1907년 을사늑약의 부당함을 세계에 알리려 헤이그에 파견되었다가 현지에서 순국하였다. 손병희는 3·1 운동 민족 대표, 여운형은 광복 전후 건국 준비 활동으로 유명하다.","ans":1,"pts":2},{"id":"60-35","r":"60","n":35,"era":"개항기","topic":"국채 보상 운동","exp":"국채 보상 기성회에서 모금하고 비녀를 팔거나 담배를 끊어 성금을 냈다는 내용은 1907년 국채 보상 운동이다. 이 운동은 대구에서 시작되어 대한매일신보 등 언론의 지원을 받아 전국으로 퍼졌다. 조선 사람 조선 것이라는 구호는 1920년대 물산 장려 운동의 것이므로 구분해야 한다.","ans":2,"pts":2},{"id":"60-36","r":"60","n":36,"era":"일제강점기","topic":"3·1 운동의 영향","exp":"1919년에 일어난 만세 시위 운동은 3·1 운동이다. 3·1 운동을 계기로 독립운동을 체계적으로 이끌 지도부의 필요성이 커져 대한민국 임시 정부가 수립되었다. 독립문 건립은 독립 협회, 홍범 14조 반포는 제2차 갑오개혁 때의 일로 모두 그 이전이다.","ans":4,"pts":2},{"id":"60-37","r":"60","n":37,"era":"일제강점기","topic":"박상진과 대한 광복회","exp":"박상진이 이끈 1910년대 국내 비밀 결사로 군자금 모집과 친일 부호 처단 활동을 했다는 단서는 대한 광복회(1915)이다. 대한 광복회는 공화정 수립을 목표로 활동한 대표적 비밀 결사였다. 권업회는 연해주에서 조직된 단체이므로 활동 무대가 다르다.","ans":4,"pts":2},{"id":"60-38","r":"60","n":38,"era":"일제강점기","topic":"우당 이회영","exp":"우당이라는 호와 형제들이 전 재산을 처분해 만주로 망명하였고 신흥 강습소를 세워 독립군을 길렀다는 내용은 이회영을 가리킨다. 이회영 일가는 명문가의 재산을 독립운동에 바쳐 노블레스 오블리주의 상징이 되었다. 신채호는 조선상고사를 쓴 역사학자이므로 구분해야 한다.","ans":3,"pts":1},{"id":"60-39","r":"60","n":39,"era":"일제강점기","topic":"민족 말살 통치","exp":"중일 전쟁(1937) 이후 궁성요배를 강요했다는 설명은 민족 말살 통치 시기를 가리킨다. 이 시기 일제는 황국 신민 서사 암송, 신사 참배, 창씨개명 등을 강요하였다. 태형을 집행하는 헌병 경찰과 회사령은 1910년대 무단 통치기의 모습이므로 구분해야 한다.","ans":3,"pts":2},{"id":"60-40","r":"60","n":40,"era":"일제강점기","topic":"광주 학생 항일 운동","exp":"1929년 나주역에서의 한일 학생 충돌에서 비롯되어 전국으로 확산되었다는 내용은 광주 학생 항일 운동이다. 당시 신간회는 진상 조사단을 파견하여 이 운동을 지원하였다. 순종의 인산일에 일어난 것은 1926년 6·10 만세 운동이므로 혼동하지 않아야 한다.","ans":4,"pts":2},{"id":"60-41","r":"60","n":41,"era":"일제강점기","topic":"한국 광복군","exp":"총사령관 지청천, 영국군과 함께한 미얀마 전선 활동, 국내 진공 작전 준비라는 단서는 대한민국 임시 정부의 한국 광복군(1940)을 가리킨다. 한국 광복군은 미국 전략 정보국(OSS)과 함께 국내 진공 작전을 준비하였다. 조선 의용대는 김원봉이 조직한 부대이므로 구분해야 한다.","ans":4,"pts":1},{"id":"60-42","r":"60","n":42,"era":"현대","topic":"김구와 남북 협상","exp":"김구의 삼천만 동포에게 읍고함(1948년 2월)은 남한만의 단독 정부 수립에 반대한 성명이다. 이후 1948년 4월 김구와 김규식은 평양에서 열린 남북 협상에 참여하였다. 제1차 미소 공동 위원회(1946)와 모스크바 3국 외상 회의(1945)는 성명 발표 이전의 일이다.","ans":3,"pts":2},{"id":"60-43","r":"60","n":43,"era":"현대","topic":"제주 4·3 사건","exp":"남한만의 단독 선거에 반대하는 세력을 토벌대가 진압하는 과정에서 무고한 주민들이 희생되었고, 너븐숭이와 섯알오름이라는 제주 지명이 나오므로 제주 4·3 사건이다. 이 사건의 진상 규명을 위해 특별법이 제정되기도 하였다. 제암리 사건은 3·1 운동 때 일제가 저지른 학살이므로 구분해야 한다.","ans":4,"pts":2},{"id":"60-44","r":"60","n":44,"era":"현대","topic":"6·25 전쟁","exp":"에티오피아군이 유엔군의 일원으로 참전한 전쟁은 6·25 전쟁(1950~1953)이다. 전쟁 중이던 1950년 9월 국군과 유엔군은 인천 상륙 작전으로 전세를 뒤집고 서울을 되찾았다. 조선 건국 준비 위원회 결성은 1945년 광복 직후, 쌍성보 전투는 1932년의 일이다.","ans":1,"pts":2},{"id":"60-45","r":"60","n":45,"era":"현대","topic":"6월 민주 항쟁","exp":"1987년에 일어났고 호헌 철폐와 독재 타도를 외쳤다는 단서는 6월 민주 항쟁이다. 이 항쟁의 결과 6·29 민주화 선언이 발표되어 5년 단임의 대통령 직선제 개헌이 이루어졌다. 3·15 부정 선거에 항의한 것은 4·19 혁명, 신군부의 비상계엄 확대에 맞선 것은 5·18 민주화 운동이다.","ans":1,"pts":2},{"id":"60-46","r":"60","n":46,"era":"통합·기타","topic":"시대별 대외 무역","exp":"당항성과 울산항에서 교류한 (가)는 통일신라, 벽란도가 국제 무역항으로 번성한 (다)는 고려, 만상과 송상이 청과 무역한 (나)는 조선 후기이다. 따라서 (가)-(다)-(나) 순서가 옳다. 벽란도가 고려의 무역항임을 알면 쉽게 순서를 정할 수 있다.","ans":2,"pts":3},{"id":"60-47","r":"60","n":47,"era":"현대","topic":"김영삼 정부","exp":"옛 조선 총독부 건물 철거와 경제 협력 개발 기구(OECD) 가입은 김영삼 정부 시기의 일이다. 김영삼 정부는 1993년 투명한 금융 거래를 위해 금융 실명제를 실시하였다. 경부 고속 도로 준공과 제1차 경제 개발 5개년 계획은 박정희 정부, 한미 FTA 체결은 노무현 정부 때의 일이다.","ans":1,"pts":2},{"id":"60-48","r":"60","n":48,"era":"통합·기타","topic":"강화도의 역사","exp":"부근리 지석묘(고인돌), 대몽 항쟁기 왕의 무덤인 홍릉, 병인양요의 격전지 정족산성, 조일 수호 조규(강화도 조약)가 체결된 연무당은 모두 강화도에 있다. 강화도는 고려의 대몽 항쟁 수도이자 개항기 열강 침입의 현장이었다. 울릉도나 진도와 혼동하지 않아야 한다.","ans":3,"pts":1},{"id":"60-49","r":"60","n":49,"era":"통합·기타","topic":"사회 개혁 인물","exp":"시대별 개혁 인물의 활동을 묻는 통합 문항이다. 최치원은 진성 여왕에게 시무 10여 조를 올렸을 뿐이며, 훈요 10조는 고려 태조 왕건이 후대 왕들에게 남긴 것이므로 ①이 적절하지 않다. 신돈의 전민변정도감 건의, 조광조의 현량과 주장, 전봉준의 동학 농민 운동은 모두 옳은 설명이다.","ans":1,"pts":3},{"id":"60-50","r":"60","n":50,"era":"현대","topic":"노태우 정부 통일 정책","exp":"남북한 유엔 동시 가입(1991)과 한중 수교(1992)는 북방 외교를 펼친 노태우 정부 시기의 일이다. 노태우 정부는 1991년 남북 사이의 화해와 불가침 등을 담은 남북 기본 합의서를 채택하였다. 7·4 남북 공동 성명은 박정희 정부, 6·15 남북 공동 선언은 김대중 정부의 일이다.","ans":1,"pts":3},{"id":"61-1","r":"61","n":1,"era":"선사·고조선","topic":"청동기 시대 생활","exp":"부여 송국리 유적과 비파형 동검 그림을 통해 청동기 시대의 생활 모습을 묻는 문항이다. 청동기 시대에는 민무늬 토기를 만들어 곡식을 저장하였으므로 민무늬 토기 만들기가 알맞은 체험 활동이다. 막집과 주먹도끼는 구석기 시대, 철제 갑옷은 철기 시대 이후의 유물이므로 시대가 맞지 않는다.","ans":2,"pts":1},{"id":"61-2","r":"61","n":2,"era":"삼국·가야","topic":"광개토 대왕","exp":"고구려 제19대 왕이며 영락이라는 연호를 사용했다는 단서에서 광개토 대왕임을 알 수 있다. 광개토 대왕은 신라 내물왕의 요청을 받아 군대를 보내 신라에 침입한 왜를 격퇴하였다. 태학 설립은 소수림왕, 평양 천도는 장수왕의 업적이므로 구분해야 한다.","ans":4,"pts":2},{"id":"61-3","r":"61","n":3,"era":"선사·고조선","topic":"부여","exp":"만주 쑹화강 유역에서 성장하였고 12월에 영고라는 제천 행사를 열었으며 여러 가(加)들이 사출도를 다스렸다는 힌트는 모두 부여에 해당한다. 부여는 왕 아래 마가·우가·저가·구가 등이 각자의 영역을 다스리는 연맹 왕국이었다. 동예는 무천, 옥저는 민며느리제로 기억하면 헷갈리지 않는다.","ans":3,"pts":2},{"id":"61-4","r":"61","n":4,"era":"삼국·가야","topic":"삼국 문화유산","exp":"금관총 금관, 서산 용현리 마애 여래 삼존상과 함께 삼국 시대 문화유산에 들어갈 수 없는 것을 고르는 문항이다. 논산 관촉사 석조 미륵보살 입상은 고려 시대에 만들어진 대형 불상이므로 삼국 시대 보고서에 들어갈 수 없다. 금동 연가 7년명 여래 입상(고구려), 천마도(신라), 장군총(고구려)은 모두 삼국 시대 유산이다.","ans":2,"pts":2},{"id":"61-5","r":"61","n":5,"era":"삼국·가야","topic":"백제","exp":"한성을 빼앗긴 뒤 웅진과 사비에서 국력을 회복하였다는 설명과 금동 대향로 그림에서 (가) 국가가 백제임을 알 수 있다. 백제 무령왕은 지방에 22담로를 두고 왕족을 파견하여 지방을 통제하였다. 주몽 건국은 고구려, 8조법은 고조선, 골품제는 신라에 해당한다.","ans":2,"pts":2},{"id":"61-6","r":"61","n":6,"era":"삼국·가야","topic":"살수 대첩","exp":"을지문덕이 이끄는 고구려군이 수의 30만 대군을 살수에서 크게 무찌른 사건은 612년 살수 대첩이다. 이는 신라의 관산성 전투(554)와 안시성 전투(645) 사이 시기이므로 연표의 (다)에 해당한다. 안시성 전투는 수가 아니라 당 태종의 침입을 막아낸 싸움이라는 점도 함께 기억해 두면 좋다.","ans":3,"pts":3},{"id":"61-7","r":"61","n":7,"era":"삼국·가야","topic":"삼국 통일 과정","exp":"삼국 통일 과정의 순서를 묻는 문항이다. 고구려가 김춘추의 군사 지원 요청을 거절한 것(642)이 가장 먼저이고, 계백의 결사대가 황산벌에서 싸운 것(660), 신라군이 매소성에서 당군을 격퇴한 것(675)이 뒤를 잇는다. 따라서 (가)-(나)-(다) 순서가 맞으며, 나당 전쟁은 백제·고구려 멸망 이후에 일어났다는 흐름을 기억해야 한다.","ans":1,"pts":3},{"id":"61-8","r":"61","n":8,"era":"남북국","topic":"불국사","exp":"경주 토함산에 있고 8세기 중엽 김대성이 조성했다고 전해지며 청운교와 백운교가 있다는 단서에서 이 절이 불국사임을 알 수 있다. 불국사에는 불국사 삼층 석탑(석가탑)과 다보탑이 있으므로 정답은 불국사 삼층 석탑이다. 성덕 대왕 신종은 경주 박물관에 있는 통일 신라 종으로 불국사의 유산이 아니다.","ans":1,"pts":1},{"id":"61-9","r":"61","n":9,"era":"남북국","topic":"발해","exp":"고구려를 계승하였고 당으로부터 해동성국이라 불렸다는 설명에서 (가) 국가가 발해임을 알 수 있다. 발해는 당의 제도를 받아들여 중앙 정치 조직을 3성 6부로 정비하되 독자적으로 운영하였다. 정사암 회의는 백제, 화랑도는 신라의 제도이므로 혼동하지 않아야 한다.","ans":2,"pts":2},{"id":"61-10","r":"61","n":10,"era":"고려","topic":"고려 수도 개경","exp":"고려의 수도였으며 만월대, 선죽교, 공민왕릉 등이 있는 (가) 지역은 개성(개경)이다. 개경에서는 최충헌의 사노비 만적이 신분 해방을 도모하며 봉기를 계획하였다. 묘청의 난은 서경(평양), 삼별초의 최후 항쟁은 진도와 제주도에서 전개되었으므로 지역을 구분해야 한다.","ans":3,"pts":2},{"id":"61-11","r":"61","n":11,"era":"고려","topic":"고려 태조 왕건","exp":"희랑 대사의 제자로 후삼국을 통일한 왕은 고려 태조 왕건이다. 태조는 지방 호족을 통제하기 위해 호족 출신 공신을 출신 지역의 사심관으로 삼는 사심관 제도를 실시하였다. 노비안검법은 광종, 12목 설치는 성종, 은병(활구) 제작은 숙종 때의 일이다.","ans":3,"pts":2},{"id":"61-12","r":"61","n":12,"era":"고려","topic":"최충","exp":"고려의 문신으로 지공거가 되어 과거를 주관하였고 노동 서원에서 기려지는 인물은 최충이다. 최충은 관직에서 물러난 뒤 9재 학당(문헌공도)을 열어 유학 교육에 힘써 해동공자라 불렸다. 삼국유사는 일연, 제왕운기는 이승휴, 시무 28조는 최승로의 활동이다.","ans":1,"pts":3},{"id":"61-13","r":"61","n":13,"era":"고려","topic":"고려 경제","exp":"숙종 때 해동통보라는 화폐를 주조하였다는 단서에서 (가) 국가가 고려임을 알 수 있다. 고려 시대에는 예성강 하구의 벽란도가 국제 무역항으로 번성하여 송·아라비아 상인까지 드나들었다. 모내기법의 전국 확산은 조선 후기, 청해진 무역은 통일 신라 장보고에 해당한다.","ans":2,"pts":2},{"id":"61-14","r":"61","n":14,"era":"고려","topic":"고려 대외 관계","exp":"(가)는 강감찬이 귀주에서 거란군을 무찌른 귀주 대첩(1019), (나)는 김윤후가 충주성에서 몽골군에 맞서 싸운 전투(1253)이다. 두 사건 사이인 1107년에 윤관이 별무반을 이끌고 여진을 정벌하여 동북 9성을 쌓았다. 서희의 강동 6주 획득은 귀주 대첩 이전, 박위의 쓰시마 토벌과 최무선의 진포 대첩은 고려 말의 일이다.","ans":2,"pts":3},{"id":"61-15","r":"61","n":15,"era":"고려","topic":"팔만대장경","exp":"몽골군의 침략으로 부인사에 보관된 대장경판이 불타자 다시 만들기로 다짐하는 내용으로, '그 일'은 팔만대장경(재조대장경) 제작이다. 고려는 부처의 힘으로 몽골의 침입을 물리치고자 강화도에서 대장도감을 설치하고 16년에 걸쳐 팔만대장경을 완성하였다. 직지심체요절은 금속 활자본, 무구정광대다라니경은 통일 신라의 목판 인쇄물로 구분된다.","ans":2,"pts":2},{"id":"61-16","r":"61","n":16,"era":"고려","topic":"무신 정변","exp":"문신 한뢰가 무신 이소응의 뺨을 때린 사건을 계기로 무신들이 정변을 일으켜 권력을 잡았다는 내용은 1170년 무신 정변이다. 무신 집권기에는 지배층의 수탈에 저항하여 망이·망소이가 공주 명학소에서 봉기하는 등 하층민의 봉기가 잇따랐다. 김헌창의 난과 장문휴의 등주 공격, 최치원의 시무 10여 조는 모두 무신 정변 이전 남북국 시대의 일이다.","ans":4,"pts":2},{"id":"61-17","r":"61","n":17,"era":"고려","topic":"도병마사","exp":"고려의 독자적인 정치 기구로 중서문하성과 중추원의 고위 관료가 모여 국방과 군사 문제를 논의하였다는 설명은 도병마사에 해당한다. 도병마사는 충렬왕 때 도평의사사로 이름이 바뀌며 국정 전반을 담당하는 기구로 확대되었다. 어사대는 관리 감찰 기구이고 의금부는 조선의 사법 기구이므로 혼동하지 않아야 한다.","ans":4,"pts":2},{"id":"61-18","r":"61","n":18,"era":"고려","topic":"최영","exp":"고려 말 홍산에서 왜구를 격퇴하였고 우왕 때 요동 정벌을 추진했으나 이성계의 위화도 회군으로 뜻을 이루지 못한 인물은 최영이다. 최영은 '황금 보기를 돌같이 하라'는 일화로도 유명한 고려 말의 명장이다. 이종무는 조선 세종 때 쓰시마섬을 정벌한 인물이므로 구분해야 한다.","ans":2,"pts":2},{"id":"61-19","r":"61","n":19,"era":"조선 전기","topic":"경복궁","exp":"정도전이 태조에게 한양의 새 궁궐 이름을 임금이 큰 복을 받으라는 뜻으로 짓기를 청하고 정전을 근정전이라 하였다는 대화에서 (가)는 경복궁임을 알 수 있다. 경복궁은 조선의 법궁으로 임진왜란 때 불탔다가 흥선 대원군 때 중건되었다. 경운궁(덕수궁)은 고종이 아관 파천 이후 머문 궁궐이다.","ans":1,"pts":1},{"id":"61-20","r":"61","n":20,"era":"조선 전기","topic":"조선 세조","exp":"계유정난으로 권력을 잡고 집현전을 폐지하였으며 직전법을 실시한 (가) 왕은 세조이다. 세조는 왕권 강화를 위해 6조가 의정부를 거치지 않고 왕에게 직접 보고하는 6조 직계제를 시행하였다. 계미자 주조는 태종, 균역법은 영조, 기묘사화는 중종 때의 일이다.","ans":4,"pts":2},{"id":"61-21","r":"61","n":21,"era":"조선 전기","topic":"임진왜란","exp":"오희문의 쇄미록에 왜군의 침입과 곽재우·김덕령 등 의병장의 활동이 기록되었다는 데서 '이 전쟁'은 임진왜란임을 알 수 있다. 임진왜란 중 조선 정부는 포수·사수·살수의 삼수병으로 구성된 훈련도감을 설치하여 군사력을 강화하였다. 별기군 창설은 개항기, 나선 정벌은 효종 때의 일이다.","ans":3,"pts":3},{"id":"61-22","r":"61","n":22,"era":"조선 전기","topic":"홍문관","exp":"옥당이라는 현판이 걸렸고 사헌부·사간원과 함께 3사로 불렸다는 설명은 홍문관에 해당한다. 홍문관은 궁궐의 서적을 관리하며 왕의 정책 자문과 경연을 담당하였다. 한양의 치안과 행정은 한성부, 재정의 출납과 회계는 호조가 맡았으므로 구분해야 한다.","ans":4,"pts":2},{"id":"61-23","r":"61","n":23,"era":"조선 전기","topic":"인조반정","exp":"1623년 능양군이 김류, 이귀 등과 함께 광해군을 몰아내고 왕위에 오른 사건은 인조반정이다. 서인 세력은 광해군의 중립 외교와 인목 대비 유폐 등을 명분으로 반정을 일으켰고, 이후 논공행상에 불만을 품은 이괄이 난을 일으켰다. 무오사화는 연산군 때 사림이 화를 입은 사건으로 시기가 다르다.","ans":4,"pts":1},{"id":"61-24","r":"61","n":24,"era":"조선 후기","topic":"조선 후기 경제","exp":"공명첩을 사서 신분을 올리고 담배 농사로 돈을 모았다는 대화에서 조선 후기의 모습임을 알 수 있다. 조선 후기에는 고구마 재배, 공인의 활동, 만상의 대청 무역 등이 나타났다. 녹읍을 지급받는 귀족은 신라 시대의 모습이므로 이 시기에 볼 수 없는 장면이다.","ans":1,"pts":2},{"id":"61-25","r":"61","n":25,"era":"조선 후기","topic":"박지원","exp":"조선 후기 실학자로 연행사를 따라 청에 다녀왔고 양반전과 열하일기를 지은 (가) 인물은 박지원이다. 박지원은 수레와 선박의 이용 등 청의 선진 문물 도입을 주장한 북학파 실학자이다. 김정희는 추사체와 금석학, 송시열은 북벌론으로 유명한 인물이므로 구분해야 한다.","ans":3,"pts":1},{"id":"61-26","r":"61","n":26,"era":"조선 후기","topic":"삼정의 문란","exp":"죽은 시아버지와 갓난아기까지 군적에 올라 세금을 뜯기는 정약용의 시는 군정의 문란을 고발한 것이다. 이는 전정·군정·환곡이 무너진 세도 정치 시기 삼정의 문란을 보여 주므로 이에 대해 찾아보는 것이 적절한 탐구 활동이다. 과전법은 고려 말, 전민변정도감은 고려 공민왕 때의 일이므로 시기가 맞지 않는다.","ans":4,"pts":2},{"id":"61-27","r":"61","n":27,"era":"개항기","topic":"이화 학당","exp":"1886년 선교사 스크랜턴이 여성 교육을 위해 세웠고 박에스더, 유관순이 공부한 학교는 이화 학당이다. 이화 학당은 우리나라 최초의 여성 교육 기관으로 근대 여성 교육의 출발점이 되었다. 배재 학당은 아펜젤러가 세운 남학생 학교, 육영 공원은 정부가 세운 관립 학교이다.","ans":4,"pts":2},{"id":"61-28","r":"61","n":28,"era":"개항기","topic":"병인양요","exp":"프랑스군이 외규장각 의궤를 약탈해 간 (가) 사건은 1866년 병인양요이다. 병인박해를 구실로 강화도에 침입한 프랑스군에 맞서 양헌수 부대가 정족산성에서 활약하여 이들을 물리쳤다. 제너럴 셔먼호 사건을 배경으로 일어난 것은 미국이 침입한 신미양요이므로 혼동하지 않아야 한다.","ans":3,"pts":2},{"id":"61-29","r":"61","n":29,"era":"개항기","topic":"임오군란","exp":"통리기무아문 설치(1880)와 갑신정변 주모자 처벌 요구(1884) 사이의 (가) 시기를 묻는 문항이다. 1882년 신식 군대 별기군과의 차별 대우에 불만을 품은 구식 군인들이 임오군란을 일으켰다. 탕평비 건립은 영조, 북벌 추진은 효종 때의 일로 시기가 크게 다르다.","ans":3,"pts":3},{"id":"61-30","r":"61","n":30,"era":"개항기","topic":"수신사","exp":"1880년 김홍집을 대표로 일본에 다녀왔고 귀국하며 조선책략을 왕에게 올린 사절단은 제2차 수신사이다. 수신사는 강화도 조약 이후 일본에 파견된 외교 사절단으로, 조선책략의 유포는 이후 위정척사 운동에 큰 영향을 주었다. 보빙사는 미국, 영선사는 청에 파견된 사절단이므로 구분해야 한다.","ans":3,"pts":2},{"id":"61-31","r":"61","n":31,"era":"개항기","topic":"동학 농민 운동","exp":"사발통문, 황룡촌 전투에서 쓴 장태, 공주 우금치 전적 등은 모두 동학 농민 운동(1894)과 관련된 자료이다. 동학 농민군은 전주 화약 이후 전라도 각지에 집강소를 설치하여 폐정 개혁을 추진하였다. 한성 조약은 갑신정변의 결과이고, 평안도 지역 차별에 반발한 것은 홍경래의 난이다.","ans":2,"pts":2},{"id":"61-32","r":"61","n":32,"era":"통합·기타","topic":"관리 등용 제도","exp":"독서삼품과(신라), 과거제(고려 광종), 현량과(조선 중종), 갑오개혁기 선거조례로 이어지는 관리 등용 제도의 역사를 묻는 통합 문항이다. (다)의 현량과는 조광조 등 사림 세력이 추천으로 인재를 등용하자며 실시를 주장한 제도이므로 ③이 옳다. (라)의 군국기무처는 광무개혁이 아니라 제1차 갑오개혁을 주도한 기구라는 점에 주의해야 한다.","ans":3,"pts":3},{"id":"61-33","r":"61","n":33,"era":"개항기","topic":"독립 협회","exp":"서재필, 윤치호가 활동하고 독립신문 발행과 수백 명이 모인 토론회 장면이 나온다는 데서 (가) 단체는 독립 협회임을 알 수 있다. 독립 협회는 독립문을 세우고 만민 공동회를 열어 민중 계몽과 자주 국권 운동에 앞장섰다. 신민회는 비밀 결사로 105인 사건으로 해체된 단체이므로 구분해야 한다.","ans":2,"pts":1},{"id":"61-34","r":"61","n":34,"era":"개항기","topic":"을사늑약","exp":"대한 제국의 외교권을 박탈하여 이준, 이상설, 이위종이 헤이그 만국 평화 회의에 특사로 파견되는 계기가 된 '이 조약'은 1905년 을사늑약이다. 을사늑약으로 통감부가 설치되고 이토 히로부미가 초대 통감으로 부임하였다. 운요호 사건을 계기로 체결된 것은 1876년 강화도 조약이다.","ans":4,"pts":2},{"id":"61-35","r":"61","n":35,"era":"개항기","topic":"광무개혁","exp":"고종이 황제에 오르고 대한 제국 수립을 선포한 (가) 시기의 정책을 묻는 문항이다. 대한 제국은 광무개혁을 추진하며 양전 사업을 실시하고 토지 소유 증명서인 지계를 발급하였다. 척화비 건립은 흥선 대원군 집권기, 홍범 14조 반포는 제2차 갑오개혁 때의 일이다.","ans":1,"pts":2},{"id":"61-36","r":"61","n":36,"era":"개항기","topic":"13도 창의군","exp":"고종의 강제 퇴위와 군대 해산에 반발하여 13도의 의병이 모여 조직되었고 이인영이 총대장을 맡은 '이 부대'는 13도 창의군이다. 13도 창의군은 1908년 서울 진공 작전을 전개하여 동대문 밖까지 진격하였으나 실패하였다. 자유시로 이동한 것은 1920년대 독립군, 광성보의 어재연은 신미양요 때의 인물이다.","ans":1,"pts":2},{"id":"61-37","r":"61","n":37,"era":"일제강점기","topic":"청산리 전투","exp":"1920년 10월 김좌진의 북로 군정서군 등 독립군 연합 부대가 백운평, 어랑촌 일대에서 일본군에 크게 승리한 전투는 청산리 전투(청산리 대첩)이다. 청산리 전투는 독립군이 거둔 가장 큰 승리로 평가받는다. 같은 해 6월 홍범도의 대한 독립군이 활약한 봉오동 전투와 구분해서 기억해야 한다.","ans":3,"pts":1},{"id":"61-38","r":"61","n":38,"era":"일제강점기","topic":"이육사","exp":"시 '광야'를 지었고 조선은행 대구 지점 폭파 사건으로 수감되었을 때의 수인 번호 264를 따서 호를 지은 저항 시인은 이육사이다. 이육사는 '청포도' 등의 작품으로 일제에 저항하는 민족의식을 노래하였다. 윤동주는 '서시', 한용운은 '님의 침묵'으로 유명한 시인이므로 구분해야 한다.","ans":3,"pts":2},{"id":"61-39","r":"61","n":39,"era":"일제강점기","topic":"산미 증식 계획","exp":"일제가 1920년부터 실시하여 쌀 생산량은 늘었지만 그보다 많은 쌀을 일본으로 가져가 식량 사정이 나빠졌다는 '이 정책'은 산미 증식 계획이다. 일제는 자국의 식량 부족을 해결하기 위해 한국에서 쌀 증산을 강요하고 수탈해 갔다. 토지 조사 사업은 1910년대에 토지 소유권 조사를 명분으로 실시된 정책이므로 구분해야 한다.","ans":3,"pts":2},{"id":"61-40","r":"61","n":40,"era":"일제강점기","topic":"민족 말살 통치","exp":"태평양 전쟁 시기 일제의 인적·물적 수탈을 다룬 다큐멘터리이므로 1930년대 후반 이후 민족 말살 통치기의 장면이 나와야 한다. 징병제, 일본군 위안부, 공출, 황국 신민 서사 암송은 모두 이 시기의 모습이다. 태형을 집행하는 헌병 경찰은 1910년대 무단 통치기의 모습이므로 적절하지 않다.","ans":1,"pts":3},{"id":"61-41","r":"61","n":41,"era":"통합·기타","topic":"단오","exp":"음력 5월 5일에 수리취떡을 먹고 창포물에 머리를 감으며 씨름을 즐긴다는 데서 '이날'은 단오임을 알 수 있다. 단오는 그네뛰기 등 다양한 풍속이 전해지는 전통 명절이다. 동지는 팥죽, 추석은 송편, 한식은 찬 음식을 먹는 날로 각각의 풍속을 구분해야 한다.","ans":1,"pts":1},{"id":"61-42","r":"61","n":42,"era":"일제강점기","topic":"윤봉길","exp":"한인 애국단 소속으로 상하이 훙커우 공원에서 의거를 일으켰고 매헌 기념관에서 기려지는 인물은 윤봉길이다. 윤봉길은 1932년 일왕 생일 기념식장에 폭탄을 던져 일본군 장성 등을 처단하였고, 이 의거는 중국 국민당 정부가 대한민국 임시 정부를 지원하는 계기가 되었다. 이봉창은 도쿄에서 일왕에게 폭탄을 던진 같은 한인 애국단원이므로 혼동하지 않아야 한다.","ans":2,"pts":1},{"id":"61-43","r":"61","n":43,"era":"일제강점기","topic":"한국 광복군","exp":"대한민국 임시 정부 소속으로 미국 전략 정보국(OSS)과 함께 국내 진공 작전(독수리 작전)을 준비한 (가) 군대는 한국 광복군이다. 한국 광복군은 1940년 충칭에서 지청천을 총사령관으로 하여 창설되었다. 조선 혁명 선언을 지침으로 삼은 것은 의열단, 영릉가 전투는 양세봉의 조선 혁명군의 활동이다.","ans":3,"pts":2},{"id":"61-44","r":"61","n":44,"era":"현대","topic":"정부 수립 과정","exp":"광복 이후 대한민국 정부 수립까지의 과정을 다룬 사진전이므로 1945~1948년 사이의 장면이 어울린다. 5·10 총선거, 좌우 합작 위원회, 제1차 미소 공동 위원회는 모두 이 시기의 사건이다. 6·10 만세 운동은 1926년 순종의 장례일에 일어난 일제강점기의 독립운동이므로 전시될 수 없다.","ans":2,"pts":2},{"id":"61-45","r":"61","n":45,"era":"현대","topic":"5·18 민주화 운동","exp":"신군부에 맞서 민주주의를 외쳤고 계엄군의 진압으로 광주 시민들이 희생되었다는 추모 내용에서 (가)는 5·18 민주화 운동(1980)임을 알 수 있다. 5·18 민주화 운동 기록물은 유네스코 세계 기록 유산으로 등재되었다. 6월 민주 항쟁은 1987년 대통령 직선제 개헌을 이끌어 낸 운동이므로 구분해야 한다.","ans":4,"pts":1},{"id":"61-46","r":"61","n":46,"era":"현대","topic":"노태우 정부 통일 노력","exp":"북방 외교로 소련과 국교를 수립하고 남북 기본 합의서와 한반도 비핵화 공동 선언을 채택한 정부는 노태우 정부이다. 노태우 정부 시기인 1991년 남북한이 유엔에 동시 가입하였다. 7·4 남북 공동 성명은 박정희 정부, 6·15 남북 공동 선언은 김대중 정부 시기의 일이다.","ans":1,"pts":3},{"id":"61-47","r":"61","n":47,"era":"현대","topic":"김영삼 정부","exp":"광복 50주년(1995)을 맞아 국민학교 명칭을 초등학교로 바꾼 '정부'는 김영삼 정부이다. 김영삼 정부는 역사 바로 세우기의 일환으로 옛 조선 총독부 건물을 철거하였다. 삼청 교육대는 전두환 신군부 시기, 반민족 행위 처벌법은 이승만 정부 초기, G20 정상 회의는 이명박 정부 시기의 일이다.","ans":2,"pts":3},{"id":"61-48","r":"61","n":48,"era":"현대","topic":"김대중 정부 경제","exp":"2002년 한일 월드컵 개막식 뉴스이므로 김대중 정부 시기의 경제 상황을 묻는 문항이다. 김대중 정부는 금 모으기 운동 등 외환 위기 극복 노력으로 국제 통화 기금(IMF)의 구제 금융을 예정보다 앞당겨 상환하였다. 경부 고속 도로 준공과 제1차 경제 개발 5개년 계획은 박정희 정부, WTO 가입은 김영삼 정부 시기의 일이다.","ans":4,"pts":2},{"id":"61-49","r":"61","n":49,"era":"통합·기타","topic":"구휼 제도","exp":"고구려의 진대법, 조선의 환곡제와 함께 고려 시대의 백성 구휼 제도를 묻는 시대 통합 문항이다. 고려는 성종 때 흑창을 확대한 의창을 두어 봄에 곡식을 빌려주고 가을에 갚게 하였다. 신문고는 백성의 억울함을 알리는 제도이고 제중원은 개항기의 서양식 병원이므로 구휼 제도와는 거리가 있다.","ans":1,"pts":2},{"id":"61-50","r":"61","n":50,"era":"통합·기타","topic":"대구 지역사","exp":"신문왕이 천도하려 했던 달구벌, 고려와 후백제의 공산 전투, 김광제 등이 시작한 국채 보상 운동, 2·28 민주 운동이 모두 일어난 (가) 지역은 대구이다. 대구는 1907년 국채 보상 운동의 발상지이자 1960년 학생 중심의 2·28 민주 운동이 일어난 곳이다. 안동은 도산 서원, 울산은 반구대 암각화 등으로 출제되는 지역이므로 구분해야 한다.","ans":1,"pts":2},{"id":"63-1","r":"63","n":1,"era":"선사·고조선","topic":"신석기 시대 생활","exp":"간석기를 손질하고 가락바퀴로 실을 뽑는 모습이 담긴 일과표로 신석기 시대의 생활을 묻고 있다. 신석기 시대에는 빗살무늬 토기를 만들어 식량을 조리하고 저장하였다. 비파형 동검은 청동기 시대, 철제 농기구는 철기 시대의 유물이므로 시대가 맞지 않다.","ans":3,"pts":1},{"id":"63-2","r":"63","n":2,"era":"선사·고조선","topic":"고조선","exp":"단군의 건국 이야기와 왕검성 함락, 한의 공격으로 멸망하였다는 내용에서 (가)가 고조선임을 알 수 있다. 고조선에는 사회 질서를 유지하기 위한 범금 8조가 있어 살인·상해·절도 등을 처벌하였다. 책화는 동예, 제가 회의는 고구려의 풍습·제도이므로 구분해야 한다.","ans":1,"pts":2},{"id":"63-3","r":"63","n":3,"era":"삼국·가야","topic":"연개소문","exp":"대막리지에 올랐고 천리장성 축조를 감독하였으며 김춘추의 군사 지원 요청을 받았다는 내용이 결정적 단서이다. 연개소문은 정변으로 권력을 잡아 대막리지가 되어 고구려의 정치와 군사를 장악하고 당에 강경한 태도를 보였다. 장보고는 통일신라 때 청해진을 세운 인물로 시대가 다르다.","ans":3,"pts":2},{"id":"63-4","r":"63","n":4,"era":"삼국·가야","topic":"신라의 통치 체제","exp":"포항 중성리에서 발견된 가장 오래된 비석과 골품제라는 단서에서 '이 국가'가 신라임을 알 수 있다. 신라에는 귀족들이 모여 만장일치로 나라의 중요한 일을 결정하는 화백 회의가 있었다. 진대법은 고구려, 영고는 부여, 부여씨와 8성 귀족은 백제에 해당한다.","ans":3,"pts":2},{"id":"63-5","r":"63","n":5,"era":"삼국·가야","topic":"백제의 대외 교류","exp":"백제 금동 대향로, 무령왕릉과 함께 백제의 대외 교류를 보여 주는 문화유산을 찾는 문제이다. 칠지도는 백제가 왜에 전해 준 것으로 알려진 칼로 백제와 일본의 교류를 보여 준다. 천마도와 호우총 청동 그릇은 신라, 청자 상감 운학문 매병은 고려의 문화유산이다.","ans":1,"pts":1},{"id":"63-6","r":"63","n":6,"era":"남북국","topic":"발해","exp":"대조영의 아들인 무왕 대무예가 장문휴를 보내 당의 등주를 공격하였다는 사료에서 (가)가 발해임을 알 수 있다. 발해는 선왕 때 전성기를 맞아 중국으로부터 바다 동쪽의 융성한 나라라는 뜻의 해동성국이라 불렸다. 광덕·준풍의 연호는 고려 광종, 상수리 제도는 통일신라의 것이다.","ans":3,"pts":2},{"id":"63-7","r":"63","n":7,"era":"남북국","topic":"집사부","exp":"신라의 14부 중 하나로 왕의 명령 전달과 국가 기밀을 담당하고 장관을 중시(시중)라 불렀다는 힌트가 제시되었다. 이 기구는 왕권을 뒷받침한 신라의 핵심 행정 기구인 집사부이다. 정당성은 발해, 의정부는 조선, 도병마사는 고려의 기구이므로 혼동하지 않아야 한다.","ans":3,"pts":2},{"id":"63-8","r":"63","n":8,"era":"남북국","topic":"통일신라의 경제","exp":"촌락 문서(민정 문서)는 통일신라가 인구, 토지, 나무 수까지 조사해 조세를 걷던 자료이므로 (가)는 신라이다. 신라는 수도의 시장을 감독하기 위한 관청으로 동시전을 설치하였다. 활구(은병)는 고려, 고추·담배 재배와 공인의 활동은 조선 후기의 경제 모습이다.","ans":4,"pts":3},{"id":"63-9","r":"63","n":9,"era":"남북국","topic":"최치원","exp":"호가 고운이고 당의 빈공과에 합격하였으며 황소에게 항복을 권하는 격문으로 이름을 떨쳤다는 단서가 제시되었다. 이 인물은 진성 여왕에게 개혁안(시무 10여 조)을 올린 신라 말의 학자 최치원이다. 설총은 이두를 정리한 학자, 김부식은 고려의 삼국사기 편찬자이므로 구분해야 한다.","ans":4,"pts":1},{"id":"63-10","r":"63","n":10,"era":"고려","topic":"고려 태조 왕건","exp":"후대 왕들이 지켜야 할 가르침인 훈요 10조를 남겼다는 내용에서 (가)가 고려 태조 왕건임을 알 수 있다. 태조는 지방 호족의 자제를 수도에 머물게 하여 호족을 견제하는 기인 제도를 실시하였다. 노비안검법은 광종, 집현전 설치는 조선 세종의 정책이므로 혼동하기 쉽다.","ans":2,"pts":2},{"id":"63-11","r":"63","n":11,"era":"고려","topic":"고려 중기 정치 변동","exp":"고려 시대의 반란·정변을 순서대로 배열하는 문제이다. 왕실 외척 이자겸의 난(1126)이 먼저 일어났고, 이어 묘청이 서경에서 국호를 대위, 연호를 천개라 하며 난을 일으켰으며(1135), 그 뒤 정중부 등이 무신정변(1170)을 일으켰다. 따라서 (나)-(다)-(가) 순서가 맞다.","ans":3,"pts":3},{"id":"63-12","r":"63","n":12,"era":"고려","topic":"고려의 지방 제도","exp":"공주 명학소에서 망이·망소이가 봉기한 사건은 고려 무신 집권기의 일이므로 고려의 지방 통치를 찾으면 된다. 고려는 국경 지대에 북계와 동계의 양계를 두고 병마사를 파견하였다. 22담로는 백제, 5소경은 통일신라, 5경 15부 62주는 발해의 지방 제도이다.","ans":2,"pts":2},{"id":"63-13","r":"63","n":13,"era":"고려","topic":"고려의 교육 기관","exp":"고려의 교육 기관으로 옳지 않은 것을 고르는 문제이다. 경당은 고구려가 지방에 세워 글과 활쏘기를 가르친 교육 기관이므로 고려와는 관련이 없다. 고려에는 최고 국립 교육 기관인 국자감, 사학 12도, 지방의 향교가 있었다.","ans":2,"pts":2},{"id":"63-14","r":"63","n":14,"era":"고려","topic":"원 간섭기","exp":"중서문하성과 상서성이 첨의부로, 6부가 4사로 격하되었다는 것은 원의 간섭을 받던 시기의 관제 변화이다. 이 시기 원은 일본 원정을 구실로 정동행성을 설치하여 고려의 내정에 간섭하였다. 별무반은 여진 정벌을 위해 그 이전인 고려 숙종 때 편성된 부대이다.","ans":2,"pts":2},{"id":"63-15","r":"63","n":15,"era":"고려","topic":"공민왕의 개혁","exp":"기철 등 친원 세력을 제거하고 쌍성총관부를 공격해 철령 이북 땅을 되찾은 왕은 고려 공민왕이다. 공민왕은 신돈을 등용하고 전민변정도감을 설치하여 권문세족이 빼앗은 토지와 노비를 되돌렸다. 독서삼품과는 통일신라 원성왕, 북한산 순수비는 신라 진흥왕과 관련된다.","ans":4,"pts":2},{"id":"63-16","r":"63","n":16,"era":"고려","topic":"고려의 목조 건축","exp":"수덕사 대웅전, 봉정사 극락전과 함께 배흘림기둥과 주심포 양식이 나타난 고려 시대 목조 건축물을 찾는 문제이다. 영주 부석사 무량수전은 배흘림기둥과 주심포 양식으로 유명한 고려의 대표적 목조 건축이다. 종묘 정전과 경복궁 근정전은 조선 시대 건축물이다.","ans":4,"pts":2},{"id":"63-17","r":"63","n":17,"era":"고려","topic":"과전법","exp":"관료에게 경기 지역의 토지만 지급하자는 조준의 상소를 받아들여 제정한 법을 묻고 있다. 고려 말 공양왕 때 신진 사대부의 주도로 과전법이 제정되어 조선 초까지 관리에게 토지의 수조권을 지급하는 기준이 되었다. 대동법은 조선 후기에 공납의 폐단을 고치려 시행한 제도이다.","ans":1,"pts":3},{"id":"63-18","r":"63","n":18,"era":"조선 전기","topic":"세종의 업적","exp":"정초, 변효문 등이 왕명으로 우리 풍토에 맞는 농법을 정리한 농사직설을 편찬하였다는 내용에서 '왕'은 세종이다. 세종 때 장영실 등이 물시계인 자격루를 제작하는 등 과학 기술이 크게 발전하였다. 화통도감은 고려 우왕 때 최무선의 건의로 설치된 것이므로 시기가 다르다.","ans":1,"pts":2},{"id":"63-19","r":"63","n":19,"era":"조선 전기","topic":"조선 성종","exp":"국조오례의를 편찬하는 등 통치 체제를 정비한 조선 제9대 왕이라는 설명에서 성종임을 알 수 있다. 성종은 세조 때부터 편찬하던 나라의 기본 법전인 경국대전을 완성하여 반포하였다. 훈민정음 창제는 세종, 초계문신제 시행은 정조의 업적이므로 구분해야 한다.","ans":2,"pts":2},{"id":"63-20","r":"63","n":20,"era":"조선 전기","topic":"사화와 붕당의 형성","exp":"(가)는 조광조를 처벌하는 기묘사화(1519), (나)는 자의 대비의 상복 기간을 둘러싼 현종 때의 예송(1659)이다. 두 사건 사이인 선조 때 사림이 이조 전랑 자리 등을 놓고 동인과 서인으로 나뉘어 붕당이 형성되었다. 탕평비 건립은 영조 때의 일로 예송 이후이므로 맞지 않다.","ans":2,"pts":3},{"id":"63-21","r":"63","n":21,"era":"고려","topic":"귀주 대첩","exp":"고려 시대에 강감찬이 거란의 대군을 물리친 전투를 묻고 있다. 강감찬은 거란의 3차 침입 때 귀주에서 적을 크게 무찔렀는데 이것이 귀주 대첩(1019)이다. 행주 대첩은 임진왜란 때 권율의 승리, 황산 대첩은 고려 말 이성계가 왜구를 격퇴한 전투이므로 혼동하지 않아야 한다.","ans":1,"pts":1},{"id":"63-22","r":"63","n":22,"era":"조선 후기","topic":"조선 후기의 경제","exp":"통신사로 다녀온 조엄이 고구마를 들여왔다는 내용에서 조선 후기(영조 무렵)의 상황임을 알 수 있다. 조선 후기에는 상공업이 발달하면서 상평통보가 전국적으로 유통되었다. 전시과 제도와 벽란도의 번성, 팔관보는 모두 고려 시대의 경제 모습이다.","ans":1,"pts":2},{"id":"63-23","r":"63","n":23,"era":"조선 전기","topic":"이황","exp":"도산 서당에서 제자를 길렀고 성학십도를 저술한 성리학자라는 단서가 제시되었다. 이 인물은 조선 성리학을 크게 발전시켜 사후 도산 서원에 모셔진 퇴계 이황이다. 박제가는 조선 후기 북학파 실학자, 정몽주는 고려 말의 충신이므로 시대와 활동이 다르다.","ans":2,"pts":1},{"id":"63-24","r":"63","n":24,"era":"조선 전기","topic":"병자호란의 결과","exp":"남한산성에서 나와 삼전도에서 청 황제에게 항복하는 장면은 병자호란(1637)의 마지막 모습이다. 이후 효종 때 청에 당한 치욕을 갚자며 북벌이 추진되었다. 강화도 천도는 고려의 대몽 항쟁, 쓰시마섬 정벌은 세종 때의 일로 모두 병자호란 이전이다.","ans":1,"pts":2},{"id":"63-25","r":"63","n":25,"era":"조선 전기","topic":"훈련도감","exp":"임진왜란 중에 설치되었고 포수·사수·살수의 삼수병으로 구성되었다는 설명이 결정적 단서이다. 이 부대는 훈련도감으로, 조선에 표류해 온 박연(벨테브레이)이 소속되어 서양식 화포 기술을 전해 주었다. 별기군은 개항 이후 만든 신식 군대이므로 시기가 전혀 다르다.","ans":4,"pts":2},{"id":"63-26","r":"63","n":26,"era":"조선 후기","topic":"세도 정치기","exp":"김삿갓 김병연이 활동하고 안동 김씨 등 소수 외척 가문이 권력을 독점하던 시기는 19세기 세도 정치기이다. 이 시기 삼정의 문란으로 임술 농민 봉기가 일어나자 정부는 삼정이정청을 설치하여 수습하려 하였다. 계유정난은 15세기 수양 대군(세조)의 집권 과정이므로 시기가 다르다.","ans":4,"pts":3},{"id":"63-27","r":"63","n":27,"era":"조선 후기","topic":"홍대용","exp":"의산문답에서 무한 우주론을 펼치고 중국 중심 세계관을 비판한 북학파 실학자는 홍대용이다. 홍대용은 지구가 스스로 돈다는 지전설을 주장하여 성리학적 세계관에서 벗어나려 하였다. 추사체는 김정희, 대동여지도는 김정호의 업적이므로 인물을 혼동하지 않아야 한다.","ans":2,"pts":2},{"id":"63-28","r":"63","n":28,"era":"조선 후기","topic":"수원 화성","exp":"정조의 명으로 축조되었고 거중기를 이용해 공사 기간을 줄였으며 의궤 기록으로 복원되었다는 단서가 제시되었다. 이 성은 정조가 개혁 정치의 중심지로 삼고자 세운 수원 화성이다. 공사 과정을 기록한 화성성역의궤 덕분에 훼손된 부분을 원형에 가깝게 복원할 수 있었다.","ans":3,"pts":1},{"id":"63-29","r":"63","n":29,"era":"개항기","topic":"흥선대원군의 정책","exp":"고종의 아버지 이하응이 10여 년간 국정을 장악하였다는 내용에서 흥선대원군 집권기임을 알 수 있다. 이 시기 신미양요 이후 전국에 척화비를 세워 통상 수교 거부 의지를 밝혔으며, 당백전 발행과 호포제 실시도 이때의 일이다. 장용영 설치는 정조의 정책이므로 시기가 다르다.","ans":3,"pts":2},{"id":"63-30","r":"63","n":30,"era":"통합·기타","topic":"한국 음악사","exp":"음악사의 주요 사건을 순서대로 배열하는 문제이다. 우륵이 가야금 12곡을 만든 것은 삼국 시대, 성현이 악학궤범을 편찬한 것은 조선 성종 때, 신재효가 판소리 여섯 마당을 정리한 것은 조선 후기 19세기의 일이다. 따라서 (가)-(나)-(다) 순서가 맞다.","ans":1,"pts":3},{"id":"63-31","r":"63","n":31,"era":"개항기","topic":"조미 수호 통상 조약","exp":"조선책략 유포로 미국과의 수교론이 일어나고 청의 주선으로 체결되었으며 이후 보빙사를 파견하였다는 단서에서 조미 수호 통상 조약(1882)임을 알 수 있다. 이 조약에는 최혜국 대우와 거중조정 조항이 들어 있었다. 부산·원산·인천 개항은 강화도 조약, 통감부 설치는 을사늑약의 결과이다.","ans":1,"pts":3},{"id":"63-32","r":"63","n":32,"era":"개항기","topic":"근대 시설","exp":"개항 이후 세워진 근대 시설 중 우정총국의 역할을 묻는 문제이다. 우정총국은 1884년에 세워져 근대적 우편 업무를 담당하였으며, 개국 축하연에서 갑신정변이 일어난 장소이기도 하다. 한성순보를 발간한 곳은 박문국, 헐버트가 가르친 곳은 육영공원이다.","ans":2,"pts":2},{"id":"63-33","r":"63","n":33,"era":"개항기","topic":"갑오개혁","exp":"노비 제도와 과거제, 연좌제를 폐지하는 개혁 안건을 통과시킨 기구를 묻고 있다. 1894년 제1차 갑오개혁을 주도한 초정부적 개혁 기구인 군국기무처가 정답이다. 원수부는 대한제국 때 고종이 군 통수권을 장악하기 위해 세운 기구이므로 혼동하지 않아야 한다.","ans":4,"pts":2},{"id":"63-34","r":"63","n":34,"era":"개항기","topic":"독립신문","exp":"1896년 4월 7일 서재필이 창간한 우리나라 최초의 민간 신문은 독립신문이다. 독립신문은 한글판과 영문판으로 발행되어 국민과 외국인에게 나라 안팎의 소식을 알렸다. 천도교 기관지는 만세보이고, 시일야방성대곡을 실은 신문은 황성신문이므로 구분해야 한다.","ans":3,"pts":2},{"id":"63-35","r":"63","n":35,"era":"개항기","topic":"을미사변과 아관파천","exp":"일본군 수비대 등이 궁궐에 침입해 왕비를 시해한 사건은 1895년의 을미사변이다. 신변의 위협을 느낀 고종은 이듬해 러시아 공사관으로 피신하는 아관파천을 단행하였다. 제너럴 셔먼호 사건(1866)과 영선사 파견(1881)은 모두 을미사변 이전의 일이다.","ans":4,"pts":2},{"id":"63-36","r":"63","n":36,"era":"개항기","topic":"신민회","exp":"안창호·양기탁이 조직한 비밀 단체로 공화정 수립을 목표로 하고 오산 학교와 대성 학교를 세웠다는 단서가 제시되었다. 이 단체는 1907년 결성된 신민회로, 일제가 조작한 105인 사건으로 와해되었다. 근우회는 일제강점기 여성 운동 단체이므로 시기와 성격이 다르다.","ans":3,"pts":1},{"id":"63-37","r":"63","n":37,"era":"일제강점기","topic":"강우규 의거","exp":"구 서울역 앞 동상의 주인공으로 65세의 나이에 사이토 총독을 향해 폭탄을 던졌다는 설명이 결정적 단서이다. 노인 동맹단 소속의 강우규는 1919년 남대문역에서 의거를 일으키고 이듬해 서대문 형무소에서 순국하였다. 윤봉길은 상하이 훙커우 공원에서 의거한 인물이다.","ans":2,"pts":2},{"id":"63-38","r":"63","n":38,"era":"일제강점기","topic":"손병희","exp":"동학의 3대 교주로 동학을 천도교로 선포한 인물인 손병희에 대해 묻고 있다. 손병희는 3·1 운동 때 민족 대표 33인의 한 사람으로 독립 선언에 참여하였다. 이토 히로부미를 처단한 인물은 안중근, 청산리 전투를 이끈 인물은 김좌진이므로 혼동하지 않아야 한다.","ans":4,"pts":3},{"id":"63-39","r":"63","n":39,"era":"일제강점기","topic":"민립 대학 설립 운동","exp":"1920년대 초 이상재·이승훈 등이 고등 교육 기관을 세우기 위해 1천만 원 모금을 추진하였다는 내용이 단서이다. 이는 '한민족 1천만이 한 사람이 1원씩'을 구호로 한 민립 대학 설립 운동으로, 총독부의 방해 등으로 성과를 거두지 못하였다. 물산 장려 운동은 국산품 애용 운동이므로 구분해야 한다.","ans":4,"pts":1},{"id":"63-40","r":"63","n":40,"era":"일제강점기","topic":"강주룡","exp":"평양 을밀대 지붕에 올라가 고공 농성을 벌인 평원 고무 공장의 파업 여공을 묻고 있다. 강주룡은 1931년 임금 삭감에 맞서 우리나라 최초의 고공 농성을 벌인 노동 운동가이다. 유관순은 3·1 운동 때 만세 시위를 이끈 인물이므로 활동 분야가 다르다.","ans":1,"pts":2},{"id":"63-41","r":"63","n":41,"era":"일제강점기","topic":"조선 혁명군","exp":"총사령 양세봉의 지휘 아래 중국 의용군과 연합하여 영릉가 전투(1932)와 흥경성 전투(1933)에서 승리한 부대를 묻고 있다. 남만주에서 활약한 이 부대는 조선 혁명군이다. 한국 광복군은 1940년 충칭에서 창설된 대한민국 임시 정부의 군대이므로 구분해야 한다.","ans":3,"pts":3},{"id":"63-42","r":"63","n":42,"era":"일제강점기","topic":"민족 말살 통치기","exp":"태평양 전쟁이 전개되던 시기는 일제가 민족 말살 통치를 강화하던 1940년대 전후이다. 이 시기 일제는 학생들에게 황국 신민 서사를 암송하게 하는 등 우리 민족의 정신을 없애려 하였다. 원산 총파업은 1929년, 조선 태형령 시행은 1910년대 무단 통치기의 일이다.","ans":3,"pts":2},{"id":"63-43","r":"63","n":43,"era":"일제강점기","topic":"조선 건국 동맹","exp":"여운형의 주도로 1944년 국내에서 조직되었고 광복 직후 조선 건국 준비 위원회의 기반이 되었다는 단서가 제시되었다. 이 단체는 광복 이후 민주 국가 건설을 준비한 비밀 결사인 조선 건국 동맹이다. 조선 의용대는 1938년 김원봉이 중국에서 조직한 무장 부대이므로 다르다.","ans":4,"pts":2},{"id":"63-44","r":"63","n":44,"era":"현대","topic":"제헌 국회","exp":"5·10 총선거로 구성되어 국호를 대한민국으로 정하고 헌법을 제정한 임기 2년의 국회는 제헌 국회(1948)이다. 제헌 국회는 농지 개혁법과 반민족 행위 처벌법을 제정하였다. 국회의원의 3분의 1을 대통령 추천으로 뽑은 것은 유신 체제 때의 일이므로 시기가 다르다.","ans":2,"pts":3},{"id":"63-45","r":"63","n":45,"era":"현대","topic":"유신 체제","exp":"유신 헌법을 부정하는 행위를 금지한 긴급 조치 9호를 선포한 정부는 박정희 유신 정부(1972~1979)이다. 이 시기 말인 1979년 부산과 마산에서 유신 체제에 반대하는 부마 민주 항쟁이 일어났다. 서울 올림픽(1988)과 금융 실명제(1993)는 그 이후의 일이다.","ans":1,"pts":2},{"id":"63-46","r":"63","n":46,"era":"현대","topic":"전두환 정부의 경제","exp":"5·18 민주화 운동을 진압한 뒤 집권하여 1983년 프로 축구를 출범시킨 (가)는 전두환 정부이다. 이 시기에는 저금리·저유가·저달러의 3저 호황으로 경제가 크게 성장하였다. OECD 가입은 김영삼 정부, 한미 FTA 체결은 노무현 정부 시기의 일이므로 구분해야 한다.","ans":3,"pts":2},{"id":"63-47","r":"63","n":47,"era":"현대","topic":"김대중 정부","exp":"제15대 대통령으로 평화적 여야 정권 교체를 이루었고 최초의 남북 정상 회담과 6·15 남북 공동 선언, 노벨 평화상 수상이라는 단서가 제시되었다. 이 인물은 김대중 대통령이다. 김영삼은 제14대 대통령으로 금융 실명제 등을 시행한 인물이므로 혼동하지 않아야 한다.","ans":1,"pts":2},{"id":"63-48","r":"63","n":48,"era":"통합·기타","topic":"정월 대보름","exp":"음력 1월 15일에 부럼을 깨고 오곡밥을 먹는다는 내용에서 정월 대보름임을 알 수 있다. 정월 대보름에는 부스럼을 예방하려는 부럼 깨기 외에 달맞이, 쥐불놀이 등의 풍속이 있었다. 단오는 음력 5월 5일, 동지는 팥죽을 먹는 명절이므로 구분해야 한다.","ans":4,"pts":1},{"id":"63-49","r":"63","n":49,"era":"통합·기타","topic":"독도","exp":"안용복과 홍순칠의 우리 땅 지키기 활동, 동도와 서도, 바다사자인 강치가 결정적 단서이다. 이 섬은 우리나라 동쪽 끝의 영토인 독도로, 조선 숙종 때 안용복이 일본에 건너가 우리 땅임을 확인받았다. 거문도는 영국이 불법 점령했던 섬이므로 혼동하지 않아야 한다.","ans":1,"pts":1},{"id":"63-50","r":"63","n":50,"era":"통합·기타","topic":"진주 지역사","exp":"고려 12목의 하나, 임진왜란 때 김시민 장군이 싸운 곳, 유계춘 주도의 농민 봉기, 조선 형평사 창립이라는 단서가 모두 한 지역을 가리킨다. 김시민의 진주 대첩, 임술 농민 봉기의 출발지, 백정 차별 철폐를 내건 형평 운동이 모두 일어난 곳은 진주이다.","ans":4,"pts":2},{"id":"64-1","r":"64","n":1,"era":"선사·고조선","topic":"청동기 시대 생활","exp":"비파형 동검을 거푸집에 부어 만든다는 설명에서 (가)는 금속 도구를 처음 사용한 청동기 시대임을 알 수 있다. 청동기 시대에는 지배층이 등장하여 그 무덤으로 고인돌을 만들었다. 우경 보급과 철제 농기구는 철기 시대 이후, 동굴이나 막집 생활은 구석기 시대의 모습이다.","ans":4,"pts":1},{"id":"64-2","r":"64","n":2,"era":"선사·고조선","topic":"동예의 풍습","exp":"읍군·삼로라는 지배자, 제천 행사 무천, 책화와 족외혼, 특산물 단궁·반어피·과하마는 모두 동예의 특징이다. 따라서 (가)에 들어갈 나라는 동예이다. 부여는 영고, 삼한은 계절제 등 제천 행사가 서로 다르므로 구분해야 한다.","ans":1,"pts":1},{"id":"64-3","r":"64","n":3,"era":"삼국·가야","topic":"백제 근초고왕","exp":"4세기 중반 마한 복속과 남조·왜 교류를 이끈 왕은 백제의 전성기를 연 근초고왕이다. 근초고왕은 371년 평양성을 공격하여 고구려 고국원왕을 전사시켰다. 사비 천도는 6세기 성왕의 일이므로 시기가 맞지 않는다.","ans":3,"pts":2},{"id":"64-4","r":"64","n":4,"era":"삼국·가야","topic":"연개소문 정변","exp":"살수 대첩(612)과 안시성 싸움(645) 사이의 사실을 묻고 있다. 이 사이인 642년에 연개소문이 정변을 일으켜 권력을 잡았고, 이는 당 태종 침입의 구실이 되었다. 김흠돌의 반란은 통일 신라, 장문휴의 산둥 공격은 발해 무왕 때의 일이다.","ans":2,"pts":2},{"id":"64-5","r":"64","n":5,"era":"삼국·가야","topic":"신라 골품제","exp":"혈통에 따라 관직 진출은 물론 집 크기, 옷차림 같은 일상생활까지 제한한 신라의 신분 제도는 골품 제도이다. 성골·진골과 6두품 등으로 나뉘어 엄격하게 차별하였다. 음서 제도는 고려 시대에 공신·고위 관료의 자손을 시험 없이 관리로 뽑던 제도이므로 혼동하지 않아야 한다.","ans":1,"pts":1},{"id":"64-6","r":"64","n":6,"era":"삼국·가야","topic":"분황사 모전 석탑","exp":"신라 선덕여왕 때 돌을 벽돌 모양으로 다듬어 쌓았고 기단 모퉁이에 사자상이 있다는 설명은 경주 분황사 모전 석탑에 해당한다. 현재 남아 있는 신라 석탑 가운데 가장 오래된 탑이다. 정림사지 오층 석탑은 백제, 월정사 팔각 구층 석탑은 고려의 탑이다.","ans":1,"pts":1},{"id":"64-7","r":"64","n":7,"era":"남북국","topic":"원종과 애노의 난","exp":"진성여왕 3년(889)에 일어난 원종과 애노의 봉기는 신라 말 사회 혼란을 보여 주는 사건이다. 이는 혜공왕 피살(780)과 고려 건국(918) 사이 시기이므로 (라)에 해당한다. 신라 말에는 세금 독촉에 반발한 농민 봉기가 곳곳에서 일어났다.","ans":4,"pts":2},{"id":"64-8","r":"64","n":8,"era":"남북국","topic":"후백제 견훤","exp":"후백제를 세웠고 아들 신검에 의해 금산사에 유폐된 인물은 견훤이다. 견훤은 927년 공산 전투에서 고려 왕건의 군대를 크게 물리쳤다. 청해진을 설치한 인물은 장보고, 국호를 마진으로 한 인물은 궁예이므로 구분해야 한다.","ans":4,"pts":2},{"id":"64-9","r":"64","n":9,"era":"남북국","topic":"발해의 문화유산","exp":"대조영이 동모산에서 나라를 세우고 해동성국이라 불렸다는 내용에서 이 나라가 발해임을 알 수 있다. 영광탑은 중국 지린성에 남아 있는 발해의 벽돌탑이다. 금관총 금관은 신라, 금동 대향로는 백제, 판갑옷과 투구는 가야의 문화유산이다.","ans":1,"pts":2},{"id":"64-10","r":"64","n":10,"era":"고려","topic":"고려 광종","exp":"준풍이라는 독자 연호를 사용하고 노비안검법을 시행한 왕은 고려 광종이다. 광종은 쌍기의 건의를 받아들여 우리 역사상 처음으로 과거제를 실시하였다. 지방에 12목을 설치한 것은 성종, 강화도 천도는 무신 집권기 최우 때의 일이다.","ans":4,"pts":2},{"id":"64-11","r":"64","n":11,"era":"고려","topic":"고려의 여진 정벌","exp":"여진이 고려를 부모의 나라로 섬기던 현종 무렵과, 금이 강성해져 사대를 요구한 인종·이자겸 시기(1126) 사이를 묻고 있다. 이 사이인 숙종 때 윤관이 여진 정벌을 위해 별무반 설치를 건의하였고, 뒤에 동북 9성을 쌓았다. 김윤후의 처인성 전투는 몽골 침입기의 일이다.","ans":2,"pts":2},{"id":"64-12","r":"64","n":12,"era":"고려","topic":"고려의 화폐","exp":"주전도감은 고려 숙종 때 화폐를 만들기 위해 설치한 기관으로, 여기서 해동통보 등이 주조되었다. 따라서 (가)에 들어갈 화폐는 해동통보이다. 명도전은 철기 시대에 중국과 교류하며 쓰인 화폐이고, 당백전은 조선 흥선 대원군이 경복궁 중건 비용을 마련하려고 발행한 화폐이다.","ans":4,"pts":1},{"id":"64-13","r":"64","n":13,"era":"고려","topic":"팔만대장경판","exp":"부처의 힘으로 몽골의 침략을 물리치고자 만들어 강화도에서 합천 해인사로 옮겼다는 설명에서 (가)는 팔만대장경판임을 알 수 있다. 고려는 최씨 무신 정권 시기 대장도감을 두어 이를 새겼다. 초조대장경은 거란 침입 때 만들었으나 몽골 침입으로 불타 버렸으므로 구분해야 한다.","ans":3,"pts":2},{"id":"64-14","r":"64","n":14,"era":"고려","topic":"무신정변","exp":"묘청의 난(1135)과 만적의 난(1198) 사이 시기를 묻고 있다. 1170년 정중부 등 무신들이 차별 대우에 반발하여 정변을 일으키고 권력을 잡았으므로 문신을 죽이라는 정중부의 장면이 맞다. 강감찬의 거란 격퇴(1019)는 이전, 최무선의 진포 대첩과 삼별초 항쟁은 이후의 일이다.","ans":1,"pts":3},{"id":"64-15","r":"64","n":15,"era":"고려","topic":"고려 태조 왕건","exp":"후삼국을 통일하고 발해 유민까지 포용한 왕은 고려 태조 왕건이다. 태조는 가난한 백성에게 곡식을 빌려주는 흑창을 만들었다. 천리장성 축조는 고구려와 고려 덕종~정종 시기의 일이고, 전시과를 처음 시행한 왕은 경종이다.","ans":1,"pts":2},{"id":"64-16","r":"64","n":16,"era":"고려","topic":"원 간섭기의 사회","exp":"발립을 쓴 관리와 변발·호복을 한 무사가 유행한 시기는 몽골풍이 퍼진 원 간섭기이다. 이 시기에는 응방 관리, 공녀 차출, 권문세족의 토지 겸병을 볼 수 있었다. 황룡사 구층 목탑은 신라 선덕여왕 때 세워졌고 몽골 침입 때 이미 불타 버렸으므로 이 시기에 세우는 모습은 볼 수 없다.","ans":3,"pts":2},{"id":"64-17","r":"64","n":17,"era":"고려","topic":"이성계의 활동","exp":"요동 정벌이 무리라는 4불가론을 내세운 인물은 이성계이다. 이성계는 1380년 황산에서 왜구를 크게 물리쳐 이름을 떨쳤다. 강동 6주를 획득한 인물은 서희, 비격진천뢰는 조선 선조 때 이장손이 만든 무기이다.","ans":3,"pts":3},{"id":"64-18","r":"64","n":18,"era":"조선 전기","topic":"조선 세종","exp":"최윤덕과 김종서를 보내 4군 6진을 개척한 왕은 조선 세종이다. 세종 때는 한양을 기준으로 한 역법서인 칠정산이 편찬되었다. 동의보감 간행은 광해군, 백두산정계비 건립은 숙종 때의 일이다.","ans":2,"pts":2},{"id":"64-19","r":"64","n":19,"era":"조선 전기","topic":"조선 태종","exp":"6조 직계제, 호패법, 사간원 독립과 계미자 주조, 혼일강리역대국도지도 제작, 신문고 설치는 모두 태종의 업적이다. 태종은 두 차례 왕자의 난을 거쳐 즉위한 뒤 왕권 강화에 힘썼다. 따라서 (가)에 들어갈 왕은 태종이다.","ans":1,"pts":1},{"id":"64-20","r":"64","n":20,"era":"조선 후기","topic":"대동법","exp":"방납의 폐단을 막고자 토산물 대신 토지 결 수를 기준으로 쌀·옷감·동전을 내게 한 제도는 대동법이다. 광해군 때 경기도에서 처음 시행되었고 관청에 물품을 대는 공인이 등장하는 계기가 되었다. 균역법은 군포 부담을 2필에서 1필로 줄인 제도이므로 혼동하지 않아야 한다.","ans":2,"pts":2},{"id":"64-21","r":"64","n":21,"era":"조선 전기","topic":"임진왜란","exp":"김시민의 진주성, 이순신의 한산도 대첩, 송상현의 동래성은 모두 임진왜란의 격전지이므로 (가)는 임진왜란이다. 조헌의 금산 의병, 곽재우의 정암진 전투, 신립의 탄금대 전투는 임진왜란 때의 사실이다. 임경업이 백마산성에서 항전한 것은 병자호란 때의 일이므로 옳지 않다.","ans":2,"pts":3},{"id":"64-22","r":"64","n":22,"era":"조선 후기","topic":"명청 교체기 대외 관계","exp":"강홍립 부대 파병은 광해군 때인 1619년, 인조의 삼전도 항복은 병자호란 말인 1637년, 나선 정벌 파병은 효종 때인 1650년대의 일이다. 따라서 (가)-(다)-(나) 순서가 맞다. 광해군의 중립 외교에서 호란을 거쳐 청과의 관계가 굳어지는 흐름을 잡으면 된다.","ans":2,"pts":3},{"id":"64-23","r":"64","n":23,"era":"조선 전기","topic":"을사사화","exp":"명종 즉위 후 왕의 외척들 사이 권력 다툼으로 일어난 사건은 1545년의 을사사화이다. 대윤 윤임 세력과 소윤 윤원형 세력이 충돌하여 많은 사림이 화를 입었다. 경신환국은 조선 숙종 때, 병인박해는 흥선 대원군 시기의 천주교 탄압이다.","ans":4,"pts":2},{"id":"64-24","r":"64","n":24,"era":"조선 후기","topic":"정선의 진경산수화","exp":"겸재 정선은 우리 자연을 직접 보고 그리는 진경산수화를 개척한 조선 후기 화가이다. 인왕제색도는 비 갠 인왕산을 그린 정선의 대표작이다. 영통동구도는 강세황, 세한도는 김정희, 몽유도원도는 조선 전기 안견의 작품이다.","ans":2,"pts":2},{"id":"64-25","r":"64","n":25,"era":"조선 후기","topic":"조선 후기의 경제","exp":"상평통보가 전국에 유통된 시기는 조선 후기이다. 이 시기에는 장시가 열리고 공인과 송상 같은 상인이 활발히 활동하였다. 벽란도에서 국제 무역이 이루어진 것은 고려 시대의 일이므로 옳지 않은 답이다.","ans":4,"pts":2},{"id":"64-26","r":"64","n":26,"era":"조선 후기","topic":"조선 정조","exp":"초계문신제를 시행하고 규장각을 운영한 왕은 정조이다. 정조는 국왕 친위 부대인 장용영을 창설하여 왕권을 뒷받침하였다. 경복궁 중건은 흥선 대원군, 영선사 파견은 고종, 훈민정음 창제는 세종의 일이다.","ans":3,"pts":2},{"id":"64-27","r":"64","n":27,"era":"조선 후기","topic":"홍경래의 난","exp":"홍경래가 주도하여 정주성에서 관군과 맞선 사건은 1811년 홍경래의 난이다. 이 난은 서북(평안도) 지역민에 대한 차별과 세도 정치기의 수탈에 반발하여 일어났다. 보국안민을 내건 것은 동학 농민 운동, 선혜청과 일본 공사관 공격은 임오군란의 일이다.","ans":3,"pts":2},{"id":"64-28","r":"64","n":28,"era":"개항기","topic":"운요호 사건","exp":"강화도와 영종도 일대에서 일어난 사건을 계기로 신헌을 보내 조일 수호 조규(강화도 조약)를 맺었다는 내용이다. 1875년 일본 군함이 강화도에 접근해 무력 충돌을 일으킨 운요호 사건이 (가)에 해당한다. 제너럴 셔먼호 사건은 신미양요의 배경이 된 사건이므로 구분해야 한다.","ans":1,"pts":1},{"id":"64-29","r":"64","n":29,"era":"개항기","topic":"임오군란","exp":"구식 군인들이 차별 대우에 반발해 일으킨 변란으로, 흥선 대원군이 수습에 나섰다가 청에 납치된 사건은 1882년 임오군란이다. 신식 군대 별기군과의 차별이 원인이었다. 갑신정변은 1884년 급진 개화파가 일으킨 정변이므로 혼동하지 않아야 한다.","ans":3,"pts":2},{"id":"64-30","r":"64","n":30,"era":"개항기","topic":"안중근","exp":"1909년 하얼빈역에서 이토 히로부미를 처단한 인물은 안중근이다. 안중근은 뤼순 감옥에서 동양 평화론을 집필하다가 순국하였다. 독립 의군부를 조직한 인물은 임병찬, 시일야방성대곡을 발표한 인물은 장지연이다.","ans":3,"pts":2},{"id":"64-31","r":"64","n":31,"era":"일제강점기","topic":"서간도 독립운동","exp":"이회영의 부인 이은숙이 국권 피탈 후 망명하여 신흥 강습소 설립 과정을 기록했다는 데서 (가)는 서간도임을 알 수 있다. 신민회 인사들은 서간도 삼원보에 독립운동 기지를 세우고 독립군을 길러냈다. 하와이와 멕시코는 노동 이민으로 한인 사회가 형성된 곳이다.","ans":2,"pts":2},{"id":"64-32","r":"64","n":32,"era":"일제강점기","topic":"1910년대 무단 통치","exp":"조선 총독부가 토지 조사 사업을 벌인 것은 1910년대 무단 통치기이다. 이 시기 일제는 조선 태형령을 시행하여 한국인에게만 태형을 가하였다. 산미 증식 계획은 1920년대, 화폐 정리 사업은 1905년 재정 고문 메가타가 추진한 일이다.","ans":2,"pts":2},{"id":"64-33","r":"64","n":33,"era":"개항기","topic":"양기탁","exp":"영국인 베델과 함께 대한매일신보를 창간하고 비밀 결사 신민회를 조직한 인물은 양기탁이다. 그는 이후 상하이로 건너가 대한민국 임시 정부에서도 활동하였다. 김원봉은 의열단, 나석주는 동양 척식 주식회사에 폭탄을 던진 인물이다.","ans":4,"pts":2},{"id":"64-34","r":"64","n":34,"era":"개항기","topic":"근대 문물의 수용","exp":"한성 전기 회사가 전기를 공급한 전차는 1899년 서대문~동대문 구간에서 개통되었다. 이보다 뒤인 1905년에 경부선 철도가 개통되었으므로 그 개통식 장면이 이후의 모습으로 적절하다. 한성순보 발간(1883)과 만민 공동회(1898), 동문학(1883)은 모두 전차 개통 이전의 일이다.","ans":3,"pts":3},{"id":"64-35","r":"64","n":35,"era":"일제강점기","topic":"청산리 전투","exp":"1920년 봉오동 전투 이후 독립군 연합 부대가 백운평·어랑촌 등에서 일본군을 대파한 전투는 청산리 전투이다. 김좌진의 북로 군정서와 홍범도 부대 등이 함께 싸워 큰 승리를 거두었다. 이후 일제는 보복으로 간도 참변을 일으켰다.","ans":2,"pts":1},{"id":"64-36","r":"64","n":36,"era":"일제강점기","topic":"대한민국 임시 정부","exp":"3·1 운동을 계기로 수립되었고 충칭에 청사를 두었다는 데서 (가)는 대한민국 임시 정부임을 알 수 있다. 임시 정부는 1940년 충칭에서 한국 광복군을 창설하였다. 독립문 건립은 독립 협회, 서전서숙 설립은 이상설의 활동이다.","ans":4,"pts":2},{"id":"64-37","r":"64","n":37,"era":"일제강점기","topic":"이봉창 의거","exp":"1931년 상하이에서 한인 애국단의 1호 단원이 된 인물은 이봉창이다. 그는 1932년 도쿄에서 일왕을 향해 폭탄을 던지는 의거를 일으켰다. 훙커우 공원 의거는 같은 한인 애국단의 윤봉길, 스티븐스 사살은 장인환·전명운의 일이므로 구분해야 한다.","ans":1,"pts":2},{"id":"64-38","r":"64","n":38,"era":"개항기","topic":"대한제국과 광무개혁","exp":"고종이 러시아 공사관에서 경운궁으로 돌아와 황제로 즉위하고 선포한 국호 (가)는 대한(대한제국)이다. 대한제국은 광무개혁을 추진하며 양전 사업을 벌이고 토지 소유 문서인 지계를 발급하였다. 척화비 건립은 흥선 대원군, 군국기무처 설치는 1894년 갑오개혁 때의 일이다.","ans":1,"pts":2},{"id":"64-39","r":"64","n":39,"era":"일제강점기","topic":"민족 말살 통치","exp":"중일 전쟁 이후 창씨개명을 강요한 시기는 1930년대 후반 이후의 민족 말살 통치기이다. 이 시기에는 공출, 황국 신민 서사 암송, 국민 징용령이 시행되었다. 회사령은 1910년 무단 통치기에 공포된 것이므로 이 시기의 모습으로 적절하지 않다.","ans":4,"pts":3},{"id":"64-40","r":"64","n":40,"era":"일제강점기","topic":"근우회","exp":"1927년 민족주의 세력과 사회주의 세력이 협동하여 만든 여성 운동 단체는 근우회이다. 근우회는 신간회의 자매 단체로 전국에 지회를 두고 여성 계몽 활동을 펼쳤다. 보안회는 1904년 일제의 황무지 개간권 요구를 막아낸 단체이다.","ans":1,"pts":1},{"id":"64-41","r":"64","n":41,"era":"현대","topic":"6월 민주 항쟁","exp":"1987년 호헌 철폐와 독재 타도를 외치며 대통령 직선제 개헌을 이끌어 낸 민주화 운동은 6월 민주 항쟁이다. 박종철 고문치사 사건과 이한열의 희생으로 시위가 전국으로 확산되었다. 시민군이 조직된 것은 1980년 5·18 민주화 운동이므로 구분해야 한다.","ans":3,"pts":3},{"id":"64-42","r":"64","n":42,"era":"현대","topic":"김규식의 활동","exp":"호가 우사이고 파리 강화 회의에 신한 청년당 대표로 파견되었으며 임시 정부 부주석을 지내고 남북 협상에 참여한 인물은 김규식이다. 그는 광복 후 여운형과 함께 좌우 합작 위원회를 결성하여 통일 정부 수립을 위해 노력하였다. 대성 학교 설립은 안창호, 조선 혁명 선언 작성은 신채호의 일이다.","ans":3,"pts":3},{"id":"64-43","r":"64","n":43,"era":"현대","topic":"6·25 전쟁","exp":"1·4 후퇴가 일어난 (가) 전쟁은 6·25 전쟁이다. 전쟁 중에는 인천 상륙 작전, 흥남 철수, 발췌 개헌안 통과(1952) 등이 있었다. 반민족 행위 처벌법은 전쟁 전인 1948년에 제정되었으므로 옳지 않은 답이다.","ans":4,"pts":2},{"id":"64-44","r":"64","n":44,"era":"현대","topic":"박정희 정부","exp":"새마을 운동, 광주 대단지 사건, 100억 달러 수출 달성은 모두 박정희 정부 시기의 일이다. 이 시기인 1970년에 경부 고속 도로가 준공되었다. 금융 실명제 실시와 OECD 가입은 김영삼 정부, 농지 개혁법 제정은 이승만 정부 때의 일이다.","ans":2,"pts":2},{"id":"64-45","r":"64","n":45,"era":"현대","topic":"김대중 정부의 통일 노력","exp":"IMF 구제 금융 조기 상환, 정주영의 소 떼 방북, 한일 월드컵 개최는 김대중 정부 시기의 일이다. 김대중 정부는 2000년 최초의 남북 정상 회담을 열고 6·15 남북 공동 선언을 발표하였다. 남북 기본 합의서 채택과 유엔 동시 가입은 노태우 정부 때의 일이다.","ans":3,"pts":2},{"id":"64-46","r":"64","n":46,"era":"통합·기타","topic":"독도","exp":"우리나라 동쪽 끝에 있고 1900년 대한제국 칙령 제41호로 우리 영토임을 분명히 한 섬은 독도이다. 조선 숙종 때 안용복은 일본에 건너가 독도가 우리 땅임을 확인받았다. 정약전이 자산어보를 쓴 곳은 흑산도, 이종무가 정벌한 곳은 쓰시마섬(대마도)이다.","ans":4,"pts":1},{"id":"64-47","r":"64","n":47,"era":"조선 후기","topic":"의궤","exp":"조선 시대 왕실이나 국가의 중대한 행사를 글과 그림으로 기록한 책은 의궤이다. 정조와 혜경궁의 수원 화성 행차도 의궤로 남아 실감 콘텐츠의 바탕이 되었다. 경국대전은 조선의 기본 법전, 조선왕조실록은 왕대별 역사 기록이므로 구분해야 한다.","ans":1,"pts":2},{"id":"64-48","r":"64","n":48,"era":"통합·기타","topic":"인천 지역사","exp":"미추홀이라는 옛 이름, 개항 후 일본 제일은행 지점이 있던 개항 박물관, 제물포 구락부는 모두 인천의 역사 유적이다. 인천은 강화도 조약에 따라 개항된 항구 도시로 개항기 유적이 많이 남아 있다. 따라서 (가)에 들어갈 지역은 인천이다.","ans":4,"pts":2},{"id":"64-49","r":"64","n":49,"era":"통합·기타","topic":"한국사의 승려들","exp":"무애가를 지어 불교를 대중화한 원효는 십문화쟁론을 지어 여러 종파의 사상을 조화시키려 하였으므로 (가)에 들어갈 내용으로 옳다. 해동 천태종을 창시한 인물은 혜초가 아니라 의천이고, 수선사 결사를 제창한 인물은 유정이 아니라 지눌이다. 세속 5계는 신라 원광이 지은 것이다.","ans":1,"pts":3},{"id":"64-50","r":"64","n":50,"era":"통합·기타","topic":"시대별 교육 기관","exp":"태학과 경당은 고구려, 국자감(서적포 설치는 고려 숙종)은 고려, 성균관과 4부 학당은 조선의 교육 기관이다. 따라서 세운 순서는 (다)-(나)-(가)가 된다. 각 시대의 대표 교육 기관을 나라별로 연결해 두면 쉽게 풀 수 있다.","ans":4,"pts":3},{"id":"66-1","r":"66","n":1,"era":"선사·고조선","topic":"신석기 시대","exp":"자료의 '농경과 목축이 시작된 신석기 시대'라는 말과 움집·갈돌 갈판이 보이는 마을 그림이 결정적 단서이다. 신석기 시대에는 빗살무늬 토기를 만들어 식량을 저장하고 조리하였으므로 정답은 ②이다. 청동 방울이나 거친무늬 거울은 청동기 시대, 철제 농기구는 철기 시대의 것이므로 시대가 맞지 않는다.","ans":2,"pts":1},{"id":"66-2","r":"66","n":2,"era":"선사·고조선","topic":"부여의 풍속","exp":"'여러 가(加)들이 별도로 사출도를 다스렸다'는 설명이 부여를 가리키는 결정적 단서이다. 부여는 12월에 영고라는 제천 행사를 열어 하늘에 제사를 지냈으므로 정답은 ①이다. 소도는 삼한, 민며느리제는 옥저, 책화는 동예의 풍속이므로 구분해서 기억해야 한다.","ans":1,"pts":2},{"id":"66-3","r":"66","n":3,"era":"삼국·가야","topic":"고구려 장수왕","exp":"광개토 대왕릉비 건립, 평양 천도, 백제 한성 함락이라는 업적이 모두 장수왕(재위 413~491)을 가리킨다. 장수왕은 아버지 광개토 대왕의 업적을 기리는 비석을 세우고 남진 정책을 펴 한강 유역까지 영토를 넓혔으므로 정답은 ②이다. 소수림왕은 불교 수용과 태학 설립으로 유명하니 혼동하지 않도록 한다.","ans":2,"pts":2},{"id":"66-4","r":"66","n":4,"era":"통합·기타","topic":"칠석","exp":"견우와 직녀가 까치와 까마귀가 놓은 오작교에서 일 년에 한 번 만난다는 이야기가 단서이다. 이 전설과 관련된 세시 풍속은 음력 7월 7일 칠석이므로 정답은 ④이다. 단오는 5월 5일 그네뛰기·씨름, 동지는 팥죽을 먹는 날로 서로 다른 풍속이다.","ans":4,"pts":1},{"id":"66-5","r":"66","n":5,"era":"삼국·가야","topic":"백제 성왕","exp":"도읍을 부여(사비)로 옮긴 왕이라는 설명에서 (가)가 백제 성왕임을 알 수 있다. 성왕은 신라 진흥왕과 연합하여 고구려가 차지했던 한강 하류 지역을 일시적으로 되찾았으므로 정답은 ④이다. 왜에 칠지도를 보낸 것은 근초고왕 무렵, 동진으로부터 불교를 받아들인 것은 침류왕 때의 일이다.","ans":4,"pts":2},{"id":"66-6","r":"66","n":6,"era":"삼국·가야","topic":"삼국 통일 과정","exp":"삼국 통일 과정의 사건 순서를 묻는 문항이다. 백제 부흥 운동을 돕던 왜군이 백강 전투에서 패한 것이 663년, 고구려 평양성이 함락된 것이 668년, 신라가 기벌포에서 당군을 격파한 것이 676년이므로 (나)-(가)-(다) 순서인 ③이 정답이다. 백제 멸망 후 고구려가 멸망하고 마지막에 나당 전쟁으로 통일이 완성되는 흐름을 기억하면 된다.","ans":3,"pts":3},{"id":"66-7","r":"66","n":7,"era":"남북국","topic":"신라 신문왕","exp":"문무왕의 아들이며 만파식적 설화의 주인공이라는 점에서 '이 왕'이 신문왕임을 알 수 있다. 신문왕은 유학 교육 기관인 국학을 설립하여 왕권을 뒷받침할 인재를 길렀으므로 정답은 ①이다. 우산국 정벌은 지증왕, 화랑도의 국가 조직 개편은 진흥왕의 업적이다.","ans":1,"pts":2},{"id":"66-8","r":"66","n":8,"era":"삼국·가야","topic":"미륵사지 석탑","exp":"백제 무왕이 세운 절터에 남은, 목탑 양식이 반영된 석탑이라는 설명이 익산 미륵사지 석탑을 가리킨다. 복원 공사 중 사리장엄구와 금제 사리봉영기가 발견된 것도 이 탑이므로 정답은 ③이다. 분황사 모전 석탑은 신라 탑, 경천사지 십층 석탑은 고려 후기의 탑이다.","ans":3,"pts":2},{"id":"66-9","r":"66","n":9,"era":"남북국","topic":"장보고와 청해진","exp":"장보고가 완도에 청해진을 설치하고 해상 교역을 주도한 '이 시기'는 통일 신라 후기이다. 이 시기에는 진골 귀족들이 녹읍을 지급받으며 경제 기반을 누렸으므로 정답은 ②이다. 분청사기는 조선 전기, 장시의 전기수와 상평통보는 조선 후기의 모습이므로 시대가 맞지 않는다.","ans":2,"pts":2},{"id":"66-10","r":"66","n":10,"era":"남북국","topic":"발해의 문화유산","exp":"고구려를 계승한 해동성국이라는 표현과 상경·중경 등 5경이 표시된 지도에서 특별전의 주인공이 발해임을 알 수 있다. 치미, 연꽃무늬 수막새, 이불병좌상은 모두 발해 유물이지만 성덕 대왕 신종은 통일 신라의 종이므로 전시에 어울리지 않는 ④가 정답이다. 발해 유물에는 고구려 문화의 영향이 강하게 나타난다는 점도 함께 기억해 둔다.","ans":4,"pts":1},{"id":"66-11","r":"66","n":11,"era":"고려","topic":"견훤의 귀부","exp":"견훤이 아들 신검에게 왕위를 빼앗기고 나주로 도망쳐 고려 왕건에게 귀부한 사건은 935년의 일이다. 이는 공산 전투(927)와 후삼국 통일(936) 사이에 해당하므로 (라) 시기인 ④가 정답이다. 견훤의 귀부 직후 신라 경순왕도 항복하였고 이듬해 고려가 후삼국을 통일하였다.","ans":4,"pts":3},{"id":"66-12","r":"66","n":12,"era":"고려","topic":"거란의 침입","exp":"강감찬의 건의로 개경에 나성을 쌓았다는 설명에서 밑줄 그은 '전쟁'이 고려와 거란의 전쟁임을 알 수 있다. 강감찬은 거란의 3차 침입 때 귀주에서 대승을 거두었으므로 귀주 대첩을 탐구하는 ①이 정답이다. 안시성 전투는 고구려와 당의 전쟁, 진포 전투는 고려 말 왜구 격퇴와 관련된 것이므로 혼동하지 않도록 한다.","ans":1,"pts":2},{"id":"66-13","r":"66","n":13,"era":"고려","topic":"고려 성종","exp":"국자감 정비, 건원중보 발행, 최승로의 시무 28조 수용이라는 힌트가 모두 고려 성종을 가리키므로 정답은 ③이다. 성종은 시무 28조를 받아들여 유교 정치 이념을 바탕으로 통치 체제를 정비하고 12목에 지방관을 파견하였다. 광종은 노비안검법과 과거제 실시로 유명하니 구분해야 한다.","ans":3,"pts":1},{"id":"66-14","r":"66","n":14,"era":"고려","topic":"고려의 경제","exp":"송 사신단이 수도 개경에 도착한다는 대화에서 고려 시대의 경제 상황을 묻는 문항임을 알 수 있다. 고려 시대에는 예성강 하구의 벽란도가 국제 무역항으로 번성하여 송 상인은 물론 아라비아 상인까지 드나들었으므로 정답은 ③이다. 공인의 관청 물품 조달과 고추·담배 재배는 조선 후기의 모습이다.","ans":3,"pts":2},{"id":"66-15","r":"66","n":15,"era":"고려","topic":"대몽 항쟁","exp":"저고여 피살을 구실로 한 몽골의 침입과 강화도 천도에 이어질 3부 내용을 찾는 문항이다. 대몽 항쟁 중 승려 김윤후가 처인성에서 몽골 장수 살리타를 사살하는 활약을 하였으므로 정답은 ②이다. 윤관의 별무반은 여진 정벌, 서희의 외교 담판은 거란 침입 때의 일이므로 상대가 다르다.","ans":2,"pts":2},{"id":"66-16","r":"66","n":16,"era":"고려","topic":"고려의 문화유산","exp":"태조 왕건이 세운 국가, 즉 고려의 문화유산으로 우표를 만들었다는 것이 단서이며 수월관음도·팔만대장경판·부석사 무량수전이 이미 제시되어 있다. (가)에는 고려의 대표 문화유산인 청자 상감 운학문 매병이 들어가야 하므로 정답은 ④이다. 산수무늬 벽돌은 백제, 황남대총 금관은 신라, 도기 바퀴장식 뿔잔은 가야의 유물이다.","ans":4,"pts":1},{"id":"66-17","r":"66","n":17,"era":"고려","topic":"공민왕의 개혁","exp":"기철 등 친원파 제거, 정동행성 이문소 폐지, 왕비 노국 대장 공주라는 단서가 모두 고려 공민왕을 가리킨다. 공민왕은 반원 자주 정책을 펴 원이 빼앗아 갔던 철령 이북 땅을 되찾고자 쌍성총관부를 공격하여 수복하였으므로 정답은 ③이다. 동북 9성 축조는 고려 예종 때 윤관, 백두산정계비는 조선 숙종 때의 일이다.","ans":3,"pts":2},{"id":"66-18","r":"66","n":18,"era":"조선 전기","topic":"정도전","exp":"경복궁의 이름을 짓고 조선경국전을 저술하여 새 왕조의 통치 방향을 제시했다는 설명이 정도전을 가리키므로 정답은 ④이다. 정도전은 조선 건국을 주도한 개국 공신으로 재상 중심의 정치를 강조하였다. 정몽주는 끝까지 고려 왕조를 지키려다 죽임을 당한 인물이므로 반대편에 선 인물로 구분해야 한다.","ans":4,"pts":2},{"id":"66-19","r":"66","n":19,"era":"조선 전기","topic":"의금부","exp":"왕명을 받아 반역 사건과 강상죄를 처결한 사법 기구이며 도사·나장이 소속되어 있었다는 설명이 의금부를 가리키므로 정답은 ②이다. 의금부는 국왕 직속 특별 사법 기구로 왕권을 뒷받침하는 역할을 하였다. 사헌부는 관리의 비리를 감찰하는 기구라는 점에서 차이가 있다.","ans":2,"pts":2},{"id":"66-20","r":"66","n":20,"era":"조선 전기","topic":"조선 세조","exp":"조선 제7대 왕으로 단종을 몰아내고 즉위했으며 경연을 폐지하고 진관 체제를 실시했다는 카드 내용이 세조를 가리킨다. 세조는 현직 관리에게만 수조지를 지급하는 직전법을 시행하였으므로 정답은 ①이다. 탕평비 건립과 금난전권 폐지는 각각 영조와 정조의 정책이므로 시대가 한참 뒤이다.","ans":1,"pts":3},{"id":"66-21","r":"66","n":21,"era":"조선 전기","topic":"병자호란","exp":"광해군이 유배 가는 장면은 인조반정(1623) 직후이고, 청을 쳐서 삼전도의 치욕을 씻자는 북벌은 효종 때의 일이므로 (가)는 그 사이 시기이다. 이 사이에 청이 침입한 병자호란(1636)이 일어나 인조가 삼전도에서 항복하였으므로 정답은 ①이다. 훈련도감 창설은 임진왜란 중, 외규장각 도서 약탈은 1866년 병인양요 때의 일이다.","ans":1,"pts":2},{"id":"66-22","r":"66","n":22,"era":"조선 전기","topic":"조선 태종","exp":"왕자의 난으로 권력을 잡고 정종의 뒤를 이어 즉위했으며 6조 직계제를 실시한 (가) 왕은 태종이다. 태종은 신문고 설치, 계미자 주조, 호패법 시행 등의 업적을 남겼으나 역법서인 칠정산은 세종 때 편찬된 것이므로 옳지 않은 것은 ③이다. 태종은 왕권 강화를 위해 사병을 없앤 왕이라는 점도 기억해 둔다.","ans":3,"pts":3},{"id":"66-23","r":"66","n":23,"era":"조선 전기","topic":"앙부일구","exp":"영침의 그림자로 시각을 표시하고 동지·하지 같은 절기도 확인할 수 있는 기기라는 설명이 해시계인 앙부일구를 가리키므로 정답은 ④이다. 세종 때 만들어진 앙부일구는 종묘 앞과 혜정교 등 사람이 많이 다니는 곳에 설치되어 백성들도 시간을 알 수 있게 하였다. 자격루는 물의 힘으로 스스로 시각을 알리는 물시계라는 점에서 다르다.","ans":4,"pts":1},{"id":"66-24","r":"66","n":24,"era":"조선 전기","topic":"조광조","exp":"기묘사화 때 현량과 실시와 위훈 삭제를 주장하다 쫓겨난 인물이라는 설명이 조광조를 가리킨다. 조광조는 도교 행사를 담당하던 소격서의 폐지를 건의하는 등 급진적 개혁을 추진하였으므로 정답은 ④이다. 백운동 서원을 세운 인물은 주세붕이므로 혼동하지 않도록 한다.","ans":4,"pts":2},{"id":"66-25","r":"66","n":25,"era":"조선 전기","topic":"임진왜란","exp":"임진왜란의 격전지를 답사하는 상황에서 어울리지 않는 장소를 고르는 문항이다. 탄금대는 신립의 전투, 행주산성은 권율의 행주 대첩, 울산 왜성은 왜군과의 전투가 벌어진 곳이지만 수원 화성은 조선 후기 정조 때 축조된 성이므로 정답은 ③이다. 수원 화성은 거중기 등을 활용해 쌓은 계획 도시라는 점에서 전혀 다른 시대의 유적이다.","ans":3,"pts":2},{"id":"66-26","r":"66","n":26,"era":"조선 후기","topic":"균역법","exp":"영조 때 제정되어 군포 납부액을 2필에서 1필로 줄이고 어장세·소금세 등으로 부족한 수입을 보충했다는 설명이 균역법을 가리키므로 정답은 ②이다. 균역법은 백성의 군역 부담을 덜어 주기 위한 개혁이었다. 대동법은 공납을 쌀 등으로 내게 한 제도이므로 대상이 다르다는 점에 주의한다.","ans":2,"pts":1},{"id":"66-27","r":"66","n":27,"era":"조선 후기","topic":"신윤복의 풍속화","exp":"조선 후기 풍속화가 신윤복의 작품 두 점 중 단오풍정과 나란히 걸릴 그림을 찾는 문항이다. 달빛 아래 남녀의 만남을 그린 월하정인이 신윤복의 대표작이므로 정답은 ④이다. 씨름도는 김홍도, 고사관수도는 조선 전기 강희안의 작품이므로 화가를 구분해야 한다.","ans":4,"pts":2},{"id":"66-28","r":"66","n":28,"era":"조선 후기","topic":"임술 농민 봉기","exp":"1862년 진주에서 유계춘을 중심으로 일어난 농민 봉기는 임술 농민 봉기의 시작이다. 봉기가 전국으로 확산되자 정부는 삼정의 문란을 바로잡기 위해 삼정이정청을 설치하였으므로 정답은 ②이다. 서북인 차별에 반발한 것은 1811년 홍경래의 난이므로 배경을 구분해야 한다.","ans":2,"pts":2},{"id":"66-29","r":"66","n":29,"era":"조선 후기","topic":"정약용","exp":"남양주 여유당에 살았고 목민심서 등 많은 책을 저술한 실학자라는 설명이 정약용을 가리킨다. 정약용은 도르래 원리를 이용한 거중기를 설계하여 수원 화성 축조에 활용하게 하였으므로 정답은 ①이다. 열하일기는 박지원, 동의보감은 허준의 저술이므로 혼동하지 않도록 한다.","ans":1,"pts":2},{"id":"66-30","r":"66","n":30,"era":"개항기","topic":"신미양요와 척화비","exp":"미군이 손돌목을 지나가고 어재연 장군이 광성보에서 대비한다는 대화는 1871년 신미양요 직전 상황이다. 신미양요 이후 흥선 대원군은 전국에 척화비를 세워 통상 수교 거부 의지를 밝혔으므로 정답은 ③이다. 병인박해는 1866년으로 이 대화보다 앞선 사건이므로 순서에 주의한다.","ans":3,"pts":2},{"id":"66-31","r":"66","n":31,"era":"개항기","topic":"보빙사","exp":"1883년 푸트 미국 공사의 부임에 대한 답례로 민영익 등이 미국에 파견되어 대통령을 만났다는 설명이 보빙사를 가리키므로 정답은 ①이다. 보빙사는 조미 수호 통상 조약 체결 이후 미국에 보낸 최초의 사절단이다. 수신사는 일본에, 영선사는 청에 파견된 사절단이므로 파견 국가를 구분해야 한다.","ans":1,"pts":2},{"id":"66-32","r":"66","n":32,"era":"개항기","topic":"최익현","exp":"을사늑약에 저항하여 태인에서 의병을 일으켰고 쓰시마섬에 끌려가 순국했다는 기사 내용이 최익현을 가리키므로 정답은 ②이다. 최익현은 같은 동포끼리 싸울 수 없다며 관군과의 전투를 중단한 뒤 체포되었다. 신돌석은 같은 시기 평민 출신 의병장으로 유명하니 구분해서 기억한다.","ans":2,"pts":1},{"id":"66-33","r":"66","n":33,"era":"개항기","topic":"갑신정변","exp":"홍영식·박영효·서광범·김옥균·서재필이 역할을 나누어 거사를 계획했다는 박영효의 회고가 결정적 단서이다. 이들 급진 개화파가 1884년 우정총국 개국 축하연을 이용해 일으킨 사건이 갑신정변이므로 정답은 ①이다. 갑신정변은 청군의 개입으로 3일 만에 실패하였다.","ans":1,"pts":2},{"id":"66-34","r":"66","n":34,"era":"개항기","topic":"거문도 사건","exp":"영국 공관에 거문도 점유에 항의하는 문서를 보낸 것은 영국이 러시아를 견제한다며 거문도를 불법 점령한 거문도 사건(1885~1887) 때의 일이다. 이는 임오군란(1882)과 갑오개혁(1894) 사이이므로 (다) 시기인 ③이 정답이다. 갑신정변 이후 열강의 대립 속에 한반도 중립화론이 나온 배경 사건이기도 하다.","ans":3,"pts":3},{"id":"66-35","r":"66","n":35,"era":"개항기","topic":"안창호","exp":"호가 도산이고 신민회 결성, 대한인 국민회 조직, 흥사단 창설에 참여한 인물은 안창호이다. 안창호는 평양에 대성 학교를 세워 민족 교육에 힘썼으므로 정답은 ①이다. 이화 학당은 개신교 선교사가 세운 여성 교육 기관이므로 설립 주체가 다르다.","ans":1,"pts":2},{"id":"66-36","r":"66","n":36,"era":"개항기","topic":"국권 피탈 과정","exp":"한일 의정서(1904)와 한일 병합 조약(1910) 사이에 체결된 조약을 찾는 문항이다. 1907년 헤이그 특사 사건 후 일제는 정미 7조약(한일 신협약)을 강요하여 대한 제국 군대를 해산시켰으므로 정답은 ②이다. 톈진 조약과 제물포 조약은 1880년대에 맺어진 것으로 시기가 앞선다.","ans":2,"pts":2},{"id":"66-37","r":"66","n":37,"era":"개항기","topic":"동학 농민 운동","exp":"일본군이 경복궁을 점령했다는 전봉준과 김학진의 대화는 1894년 6월 이후의 상황이다. 이후 동학 농민군은 일본군을 몰아내기 위해 다시 봉기했으나 공주 우금치 전투에서 패배하였으므로 정답은 ②이다. 고부 농민 봉기와 삼례 집회는 모두 이 대화보다 앞선 사건이므로 순서에 주의한다.","ans":2,"pts":2},{"id":"66-38","r":"66","n":38,"era":"개항기","topic":"국채 보상 운동","exp":"일본에 진 빚 1,300만 원을 갚기 위해 의연금을 모은다는 대사가 결정적 단서이다. 1907년 대구에서 시작된 국채 보상 운동은 금주·금연과 반지 모으기 등으로 전국으로 확산되었으므로 정답은 ①이다. 물산 장려 운동은 1920년대 '조선 사람 조선 것' 구호의 토산품 애용 운동이므로 구분해야 한다.","ans":1,"pts":1},{"id":"66-39","r":"66","n":39,"era":"개항기","topic":"대한 제국기 근대 문물","exp":"대한 제국 시기(1897~1910)에 도입된 근대 문물이 아닌 것을 찾는 문항이다. 원각사 건립, 중명전 건립, 경부선 부설은 모두 대한 제국 시기의 일이지만 박문국에서 한성순보가 발행된 것은 1883년으로 대한 제국 수립 이전이므로 정답은 ③이다. 한성순보는 우리나라 최초의 근대 신문이라는 점도 함께 기억해 둔다.","ans":3,"pts":3},{"id":"66-40","r":"66","n":40,"era":"일제강점기","topic":"6·10 만세 운동","exp":"대한 제국의 마지막 황제 순종의 승하(1926) 소식을 전하는 호외 장면이 단서이다. 순종의 인산일에 학생들이 중심이 되어 6·10 만세 운동을 벌였으므로 정답은 ①이다. 헤이그 특사 파견(1907)과 토지 조사 사업(1910년대)은 모두 이보다 앞선 일이므로 순서에 주의한다.","ans":1,"pts":2},{"id":"66-41","r":"66","n":41,"era":"일제강점기","topic":"1910년대 무단 통치","exp":"김동인의 소설 태형을 통해 조선 태형령이 시행된 시기, 즉 1910년대 무단 통치기를 묻고 있다. 이 시기에는 제복을 입고 칼을 찬 헌병 경찰이 치안을 담당하였으므로 정답은 ②이다. 경성 제국 대학은 1924년에 세워졌고 국민 징용령은 1939년의 일이므로 시기가 맞지 않는다.","ans":2,"pts":2},{"id":"66-42","r":"66","n":42,"era":"일제강점기","topic":"대한민국 임시 정부","exp":"3·1 운동을 계기로 상하이에 수립되었고 김구·이시영이 활동했다는 설명이 대한민국 임시 정부를 가리킨다. 임시 정부는 독립운동 자금을 마련하기 위해 독립 공채를 발행하였으므로 정답은 ①이다. 만민 공동회는 독립 협회, 신흥 강습소는 신민회 인사들이 만주에 세운 것이므로 주체를 구분해야 한다.","ans":1,"pts":2},{"id":"66-43","r":"66","n":43,"era":"일제강점기","topic":"조선 의용대","exp":"김원봉이 만든 중국 관내 최초의 한인 무장 부대라는 설명이 결정적 단서이다. 김원봉은 1938년 중국 우한에서 조선 의용대를 창설하였으므로 정답은 ③이다. 대한 독립군은 홍범도, 조선 혁명군은 양세봉이 이끈 만주 지역 부대이므로 활동 지역과 지휘관을 구분해야 한다.","ans":3,"pts":2},{"id":"66-44","r":"66","n":44,"era":"통합·기타","topic":"제주도의 역사","exp":"삼성혈, 탐라국, 김만덕, 하멜, 4·3 사건 등의 단어가 모두 제주도의 역사를 가리킨다. 고려 시대 삼별초는 진도에 이어 제주도로 옮겨 최후까지 항쟁하였으므로 제주에서의 탐구 활동으로 ②가 적절하다. 운요호 사건은 강화도, 고려 왕릉은 개성 일대와 강화도에 있으므로 지역이 다르다.","ans":2,"pts":2},{"id":"66-45","r":"66","n":45,"era":"통합·기타","topic":"신분 차별 극복","exp":"(가)는 만적처럼 신분 해방을 꾀한 노비, (나)는 서얼, (다)는 백정을 가리킨다. 조선 후기 서얼은 차별 완화 운동의 결과 정조 때 유득공·박제가 등 일부가 규장각 검서관에 기용되었으므로 정답은 ②이다. 골품에 따라 승진 제한을 받은 것은 신라 6두품의 일이고, 매매·상속의 대상이 된 것은 노비에만 해당한다.","ans":2,"pts":3},{"id":"66-46","r":"66","n":46,"era":"현대","topic":"제헌 국회","exp":"유엔 결의에 따른 총선거, 즉 1948년 5·10 총선거로 출범한 국회는 제헌 국회이다. 제헌 국회는 제헌 헌법 제정, 반민족 행위 처벌법 가결, 이승만 초대 대통령 선출을 담당했으나 한미 상호 방위 조약은 6·25 전쟁 후인 1953년에 체결된 것이므로 적절하지 않은 것은 ③이다. 제헌 국회 의원의 임기는 2년으로 1950년에 끝났다는 점을 기억하면 쉽다.","ans":3,"pts":3},{"id":"66-47","r":"66","n":47,"era":"현대","topic":"5·18 민주화 운동","exp":"시민군의 항쟁 중심지였던 옛 전남도청과 '임을 위한 행진곡'이 결정적 단서이다. 1980년 신군부의 계엄 확대에 맞서 광주에서 일어난 민주화 운동이 5·18 민주화 운동이므로 정답은 ④이다. 6월 민주 항쟁은 1987년 대통령 직선제 개헌을 이끌어 낸 운동이므로 구분해야 한다.","ans":4,"pts":1},{"id":"66-48","r":"66","n":48,"era":"현대","topic":"박정희 정부 통일 노력","exp":"분단 26년 만의 남북 직통 전화 개설과 남북 적십자 회담 준비는 1971년 박정희 정부 시기의 일이다. 이 정부 시기에 자주·평화·민족 대단결 원칙을 담은 7·4 남북 공동 성명이 발표(1972)되었으므로 정답은 ③이다. 남북한 유엔 동시 가입은 노태우 정부, 금강산 관광과 최초의 남북 정상 회담은 김대중 정부 때의 일이다.","ans":3,"pts":3},{"id":"66-49","r":"66","n":49,"era":"현대","topic":"김영삼 정부 경제","exp":"대통령 긴급 명령으로 금융 실명제를 실시한다는 연설에서 김영삼 정부 시기임을 알 수 있다. 김영삼 정부는 1996년 경제 협력 개발 기구(OECD)에 가입하였으므로 정답은 ④이다. 경부 고속 도로 준공과 경제 개발 5개년 계획은 박정희 정부, 3저 호황은 전두환 정부 시기의 일이다.","ans":4,"pts":2},{"id":"66-50","r":"66","n":50,"era":"통합·기타","topic":"한글을 빛낸 인물","exp":"(가)는 세종이 설치한 집현전, (나)는 1907년 학부에 설치된 국문 연구소, (다)는 정세권이 후원하고 1942년 탄압 사건을 겪은 조선어 학회이다. 조선어 학회는 한글 맞춤법 통일안을 제정하고 우리말 큰사전 편찬을 추진하였으므로 정답은 ③이다. 한글 신문인 독립신문은 서재필이 창간한 것으로 국문 연구소와는 관련이 없다.","ans":3,"pts":3},{"id":"67-1","r":"67","n":1,"era":"선사·고조선","topic":"청동기 시대","exp":"화순 고인돌 유적과 '처음으로 금속 도구를 사용한 시대'라는 단서를 통해 (가)가 청동기 시대임을 알 수 있다. 청동기 시대에는 벼농사가 본격화되어 반달 돌칼로 벼 이삭을 수확하였다. 철제 농기구 사용은 철기 시대, 동굴이나 막집 생활은 구석기 시대, 빗살무늬 토기는 신석기 시대의 모습이므로 구분해야 한다.","ans":3,"pts":1},{"id":"67-2","r":"67","n":2,"era":"선사·고조선","topic":"옥저","exp":"동해안에 위치하고, 여자아이를 데려와 기른 뒤 며느리로 삼는 민며느리제가 있었으며, 읍군·삼로라는 군장이 다스렸다는 힌트가 모두 옥저를 가리킨다. 옥저는 왕이 없는 군장 국가로 소금과 해산물이 풍부하였다. 같은 동해안의 동예는 무천이라는 제천 행사와 책화 풍속이 있었던 나라이므로 혼동하지 않도록 한다.","ans":2,"pts":2},{"id":"67-3","r":"67","n":3,"era":"삼국·가야","topic":"광개토 대왕","exp":"고구려 제19대 왕으로 거란, 숙신, 후연, 동부여 등을 정벌하여 영토를 크게 넓혔다는 설명은 광개토 대왕에 해당한다. 광개토 대왕은 신라 내물왕의 요청을 받아 군대를 보내 신라에 침입한 왜를 격퇴하였다. 태학 설립은 소수림왕, 평양 천도는 장수왕의 업적이므로 구분해야 한다.","ans":4,"pts":2},{"id":"67-4","r":"67","n":4,"era":"삼국·가야","topic":"백제 문화유산","exp":"백제의 문화유산을 조사하는 보고서로, 무령왕릉과 함께 들어갈 백제 유산을 찾아야 한다. 몽촌토성은 한성 시기 백제의 도성 유적으로 서울 송파구에 남아 있다. 금동 연가 7년명 여래 입상과 장군총은 고구려, 천마총 장니 천마도는 신라의 문화유산이다.","ans":3,"pts":3},{"id":"67-5","r":"67","n":5,"era":"삼국·가야","topic":"신라 진흥왕","exp":"단양 신라 적성비는 고구려 영토였던 적성을 점령하고 세운 비석으로, 이사부가 활약한 (가) 왕은 진흥왕이다. 진흥왕은 화랑도를 국가적인 조직으로 정비하여 인재를 길렀다. 국학 설치는 신문왕, 독서삼품과 시행은 원성왕, 김헌창의 난 진압은 헌덕왕 때의 일이다.","ans":2,"pts":2},{"id":"67-6","r":"67","n":6,"era":"삼국·가야","topic":"가야","exp":"김해 대성동, 고령 지산동, 함안 말이산 고분군은 각각 금관가야, 대가야, 아라가야의 유적이므로 '이 나라'는 가야이다. 가야는 질 좋은 철이 풍부하여 낙랑과 왜에 철을 수출하며 성장하였다. 22담로는 백제, 화백 회의는 신라에 해당하는 설명이다.","ans":3,"pts":2},{"id":"67-7","r":"67","n":7,"era":"삼국·가야","topic":"삼국 통일 과정","exp":"삼국 통일 과정의 순서를 묻는 문항이다. 김춘추가 고구려에 군사를 요청한 것(642)이 가장 먼저이고, 김유신이 황산벌에서 계백의 백제군을 물리친 것(660)이 다음이며, 문무왕 때 기벌포에서 당의 수군을 몰아낸 것(676)이 마지막이다. 따라서 (가)-(다)-(나) 순서가 된다.","ans":2,"pts":3},{"id":"67-8","r":"67","n":8,"era":"남북국","topic":"발해 문화유산","exp":"상경성을 도읍으로 삼고 문왕이 당의 장안성을 본떠 도성을 만들었다는 설명에서 (가)는 발해임을 알 수 있다. 이불병좌상, 영광탑, 정효 공주 무덤 벽화는 모두 발해의 문화유산이다. 칠지도는 백제가 왜에 보낸 칼이므로 발해와 관련이 없어 정답이 된다.","ans":1,"pts":2},{"id":"67-9","r":"67","n":9,"era":"남북국","topic":"석굴암 본존불","exp":"화강암으로 만든 인공 석굴 사원인 석굴암 내부의 불상을 찾는 문항이다. 석굴암 본존불은 통일신라 불교 예술의 걸작으로 균형 잡힌 조각미를 자랑한다. 금동 미륵보살 반가사유상이나 서산 마애여래삼존상 등 다른 불상과 혼동하지 않도록 한다.","ans":1,"pts":1},{"id":"67-10","r":"67","n":10,"era":"남북국","topic":"호족","exp":"신라 말 지방에서 독자적인 세력을 형성하고 스스로 성주 또는 장군이라 칭했다는 설명은 호족에 해당한다. 호족은 일정한 지역에서 정치·군사·경제적 지배권을 장악하며 새로운 사회 건설을 주도하였다. 권문세족은 고려 후기, 신진 사대부는 고려 말의 지배 세력이므로 시기가 다르다.","ans":2,"pts":1},{"id":"67-11","r":"67","n":11,"era":"고려","topic":"고려 태조 왕건","exp":"발해 유민을 받아들이고 적대 관계였던 견훤까지 포용하며 민족 통합에 힘쓴 고려의 왕은 태조 왕건이다. 태조는 빈민 구제를 위해 곡식을 빌려주는 흑창을 설치하였다. 과거제를 처음 실시한 왕은 광종이고, 강화 천도는 무신 정권기 최우가 주도한 일이다.","ans":1,"pts":2},{"id":"67-12","r":"67","n":12,"era":"고려","topic":"고려의 경제생활","exp":"태안 마도 2호선에서 발견된 청자 매병과 죽찰, 개경이라는 표현을 통해 (가)가 고려임을 알 수 있다. 고려에서는 활구라고도 불린 은병을 화폐로 만들어 사용하였다. 덕대, 신해통공, 만상은 모두 조선 후기의 경제 모습이므로 시대가 맞지 않는다.","ans":4,"pts":2},{"id":"67-13","r":"67","n":13,"era":"고려","topic":"서희의 외교 담판","exp":"거란의 침입 이유와 여진 축출·옛 땅 반환 요구가 오가는 장면은 거란의 1차 침입 때 서희의 외교 담판(993)이다. 서희는 이 담판으로 강동 6주를 확보하였다. 993년은 후삼국 통일(936)과 귀주 대첩(1019) 사이이므로 (가) 시기가 정답이다.","ans":1,"pts":3},{"id":"67-14","r":"67","n":14,"era":"고려","topic":"묘청의 서경 천도 운동","exp":"이자겸의 난(1126)과 정중부의 정변(1170) 사이에 들어갈 사건을 찾는 문항이다. 묘청은 서경 천도와 금 정벌을 주장하다가 받아들여지지 않자 1135년 반란을 일으켰고, 김부식이 이를 진압하였다. 이괄의 난과 위화도 회군은 각각 조선과 고려 말의 사건으로 시기가 다르다.","ans":3,"pts":1},{"id":"67-15","r":"67","n":15,"era":"고려","topic":"안향","exp":"고려 후기 문신으로 성리학 도입에 힘썼고 소수 서원에서 제향된다는 단서를 통해 '나'는 안향임을 알 수 있다. 안향은 원에서 성리학을 들여와 후학 양성에 힘썼고, 조선 중종 때 주세붕이 그를 기려 백운동 서원(소수 서원)을 세웠다. 정몽주는 고려 말 성리학자이지만 소수 서원 제향 인물이 아니다.","ans":1,"pts":2},{"id":"67-16","r":"67","n":16,"era":"고려","topic":"삼별초","exp":"고려 정부가 몽골과 강화하고 개경으로 환도하자 이에 반발해 진도 용장성으로 옮겨 항쟁한 군대는 삼별초이다. 삼별초는 최우가 만든 야별초에서 비롯되어 최씨 무신 정권의 군사적 기반이 되었다. 신기군·신보군·항마군으로 구성된 부대는 여진 정벌을 위해 윤관이 조직한 별무반이다.","ans":4,"pts":2},{"id":"67-17","r":"67","n":17,"era":"고려","topic":"진포 대첩","exp":"최무선이 왜구에 맞서 군대를 지휘하고 화포를 사용했다는 대화에서 진포 대첩(1380)임을 알 수 있다. 최무선은 화통도감에서 만든 화포를 처음 실전에 사용하여 진포에서 왜구의 배를 크게 격파하였다. 명량 대첩은 임진왜란 때 이순신, 행주 대첩은 권율의 승리이므로 혼동하지 않도록 한다.","ans":3,"pts":2},{"id":"67-18","r":"67","n":18,"era":"조선 전기","topic":"조선 세종","exp":"박연에게 편경을 만들게 하고 아악을 정비하도록 한 왕은 세종이다. 세종 때에는 자격루 제작, 농사직설 간행, 삼강행실도 편찬 등이 이루어졌다. 악학궤범은 성종 때 성현 등이 완성한 음악 이론서이므로 세종의 업적이 아니어서 정답이 된다.","ans":3,"pts":2},{"id":"67-19","r":"67","n":19,"era":"조선 전기","topic":"조선왕조실록","exp":"태조에서 철종까지 470여 년의 역사를 왕별로 기록했고 유네스코 세계 기록 유산에 등재되었다는 설명은 조선왕조실록에 해당한다. 실록은 사관이 남긴 사초 등을 바탕으로 왕이 죽은 뒤 편찬되어 사고에 보관되었다. 경국대전은 법전, 동의보감은 의학서, 목민심서는 정약용의 저술이다.","ans":4,"pts":1},{"id":"67-20","r":"67","n":20,"era":"조선 전기","topic":"조선 세조","exp":"집현전을 없애고 경연을 정지했으며, 성삼문 등의 상왕 복위 시도를 빌미로 단종을 노산군으로 낮춰 영월로 보낸 왕은 세조이다. 세조는 왕권 강화를 위해 6조가 의정부를 거치지 않고 왕에게 직접 보고하는 6조 직계제를 시행하였다. 탕평책은 영조, 한양 천도는 태조의 일이다.","ans":4,"pts":3},{"id":"67-21","r":"67","n":21,"era":"조선 전기","topic":"무오사화","exp":"김종직이 쓴 조의제문이 연산군 때 일어난 사건의 빌미가 되었다는 설명에서 (가)는 무오사화(1498)임을 알 수 있다. 훈구 세력이 조의제문을 문제 삼아 김일손 등 사림 세력이 큰 화를 입었다. 신유박해는 순조 때 천주교 탄압 사건이므로 시기와 성격이 다르다.","ans":3,"pts":2},{"id":"67-22","r":"67","n":22,"era":"조선 후기","topic":"대동법","exp":"김육이 경기도와 강원도에서 이미 시행 중인 제도를 충청도에도 확대하자고 건의하는 장면에서 (가)는 대동법임을 알 수 있다. 대동법은 집집마다 부과하던 특산물 대신 토지를 기준으로 쌀, 베, 동전 등을 내게 한 제도이다. 군포를 2필에서 1필로 줄인 것은 균역법, 전세를 4~6두로 고정한 것은 영정법이다.","ans":4,"pts":3},{"id":"67-23","r":"67","n":23,"era":"조선 후기","topic":"병자호란과 북벌론","exp":"남한산성에서 항전하던 임금이 삼전도에서 청에 항복하고 세자와 봉림 대군이 볼모로 끌려갔다는 대화는 병자호란(1636~1637)의 결말을 보여 준다. 이후 왕위에 오른 효종은 청에 당한 치욕을 갚자는 북벌론을 추진하였다. 4군 6진 개척은 세종 때, 정동행성 설치는 고려 원 간섭기의 일로 모두 병자호란 이전이다.","ans":1,"pts":2},{"id":"67-24","r":"67","n":24,"era":"조선 후기","topic":"조선 정조","exp":"정약용이 설계한 배다리를 건너 아버지 사도 세자의 묘에 참배하러 가는 왕은 정조이다. 정조는 왕권을 뒷받침하기 위해 친위 부대인 장용영을 설치하고 수원 화성을 건설하였다. 당백전 발행은 흥선 대원군, 훈민정음 반포는 세종의 일이므로 구분해야 한다.","ans":1,"pts":1},{"id":"67-25","r":"67","n":25,"era":"통합·기타","topic":"토지 제도의 변천","exp":"우리 역사 속 토지 제도의 순서를 묻는 문항이다. 신라 신문왕이 관료전을 지급하고 녹읍을 폐지한 것(가)이 가장 먼저이고, 고려의 전시과 제도로 전·현직 관리에게 전지와 시지를 차등 지급한 것(다)이 다음이며, 조선 세조가 과전법을 혁파하고 직전법을 실시한 것(나)이 마지막이다. 따라서 (가)-(다)-(나) 순서가 정답이다.","ans":2,"pts":3},{"id":"67-26","r":"67","n":26,"era":"조선 후기","topic":"조선 후기 사회 모습","exp":"조엄이 통신사로 일본에 다녀오며 고구마를 들여온 것은 조선 후기 영조 때의 일이다. 조선 후기에는 상평통보 유통, 판소리 공연, 한글 소설을 읽어 주는 전기수 등이 등장하였다. 황룡사 구층 목탑은 신라 선덕여왕 때 세워진 것이므로 이 시기에 볼 수 없는 모습이다.","ans":4,"pts":2},{"id":"67-27","r":"67","n":27,"era":"조선 후기","topic":"임술 농민 봉기","exp":"세도 정치기에 경상 우병사 백낙신의 수탈에 저항하여 유계춘을 중심으로 일어났고 삼정이정청 설치의 계기가 된 사건은 임술 농민 봉기(1862)이다. 정부는 사태 수습을 위해 박규수를 안핵사로 파견하였다. 서북 지역민 차별이 원인이 된 것은 홍경래의 난이므로 혼동하지 않도록 한다.","ans":2,"pts":2},{"id":"67-28","r":"67","n":28,"era":"조선 후기","topic":"김정희","exp":"북한산비가 진흥왕 순수비임을 고증하고, 금석학을 연구해 독창적인 서체(추사체)를 만들었으며 제주도 유배 중 세한도를 그린 인물은 김정희이다. 김정희는 금석과안록을 지어 고증 결과를 남겼다. 박지원은 열하일기를 쓴 실학자로 활동 분야가 다르다.","ans":1,"pts":2},{"id":"67-29","r":"67","n":29,"era":"개항기","topic":"동학 농민 운동","exp":"부패한 지도층과 외세의 침략에 저항했고 전봉준 공초 등 관련 기록물이 유네스코 세계 기록 유산이 된 사건은 동학 농민 운동(1894)이다. 농민군은 전주 화약 이후 집강소를 설치하여 폐정 개혁을 추진하였다. 청산리 전투는 일제강점기 독립군의 승리이므로 관련이 없다.","ans":3,"pts":2},{"id":"67-30","r":"67","n":30,"era":"개항기","topic":"신돌석","exp":"평민 출신 의병장으로 을미사변 후 영해에서 활동했고 태백산 호랑이라 불린 인물은 신돌석이다. 그는 을사늑약 체결 뒤 울진, 평해 등지에서 뛰어난 전술로 일본군에 맞서 싸웠다. 최익현은 양반 유생 출신 의병장, 홍범도는 일제강점기 봉오동 전투의 주역이므로 구분해야 한다.","ans":1,"pts":1},{"id":"67-31","r":"67","n":31,"era":"통합·기타","topic":"시대별 개혁가","exp":"시무 10여 조를 건의한 (가)는 최치원, 시무 28조를 올린 (나)는 최승로, 갑신정변을 일으킨 (라)는 김옥균이 맞다. 그러나 훈구 세력을 견제하며 현량과 실시를 주장한 (다)는 조선 중종 때의 조광조이다. 정도전은 조선 건국을 주도한 인물이므로 (다)에 맞지 않아 정답이 된다.","ans":3,"pts":2},{"id":"67-32","r":"67","n":32,"era":"개항기","topic":"병인양요","exp":"1866년 프랑스군이 침입하여 외규장각 의궤를 약탈해 간 사건은 병인양요이다. 이때 양헌수 부대가 정족산성에서 프랑스군을 물리쳤다. 제너럴 셔먼호 사건은 신미양요의 배경이 된 별개의 사건이고, 오페르트 도굴 사건도 1868년에 따로 일어난 일이므로 혼동하지 않도록 한다.","ans":4,"pts":2},{"id":"67-33","r":"67","n":33,"era":"개항기","topic":"독립 협회","exp":"종로에서 관민 공동회를 개최하고 헌의 6조를 올린 단체는 독립 협회이다. 독립 협회는 국민 성금을 모아 청 사신을 맞던 영은문 자리 부근에 독립문을 세웠다. 광혜원 설립은 정부와 알렌이 주도하였고, 파리 강화 회의 대표 파견은 신한 청년당의 활동이다.","ans":3,"pts":2},{"id":"67-34","r":"67","n":34,"era":"일제강점기","topic":"무단 통치기","exp":"헌병이 일반 경찰 업무까지 맡는 헌병 경찰 제도가 시행된 '이 시기'는 1910년대 무단 통치기이다. 이 시기에는 교사까지 제복을 입고 칼을 차게 하여 위압적인 분위기를 조성하였다. 한성순보 발간(1883), 단발령(1895), 경인선 개통(1899)은 모두 국권 피탈 이전의 일이다.","ans":1,"pts":2},{"id":"67-35","r":"67","n":35,"era":"개항기","topic":"이상설","exp":"북간도, 헤이그, 연해주로 이어진 이상설의 활동을 순서대로 구성하는 문항으로, 만국 평화 회의 특사 파견(1907) 앞에 들어갈 일을 찾아야 한다. 이상설은 1906년 북간도 용정에 민족 교육 기관인 서전서숙을 세웠다. 의열단 조직은 김원봉, 동양 평화론 집필은 안중근, 시일야방성대곡 발표는 장지연의 활동이다.","ans":2,"pts":3},{"id":"67-36","r":"67","n":36,"era":"일제강점기","topic":"3·1 운동","exp":"1919년 학생과 시민들의 만세 시위가 전국으로 확산되었고 제암리 학살로 탄압받은 이 운동은 3·1 운동이다. 3·1 운동은 독립운동을 이끌 지도부의 필요성을 일깨워 대한민국 임시 정부 수립의 계기가 되었다. 순종의 인산일에 전개된 것은 6·10 만세 운동(1926)이므로 구분해야 한다.","ans":3,"pts":2},{"id":"67-37","r":"67","n":37,"era":"일제강점기","topic":"물산 장려 운동","exp":"'조선 사람 조선 것', '내 살림 내 것으로'라는 구호와 조만식 등이 주도했다는 단서에서 (가)는 물산 장려 운동임을 알 수 있다. 이 운동은 평양에서 시작되어 국산품 애용으로 민족 경제를 지키자는 취지로 전국에 퍼졌다. 브나로드 운동은 동아일보가 주도한 문맹 퇴치 운동이므로 혼동하지 않도록 한다.","ans":2,"pts":2},{"id":"67-38","r":"67","n":38,"era":"일제강점기","topic":"신채호","exp":"호가 단재이고 독사신론과 조선상고사를 지어 민족의식을 고취한 인물은 신채호이다. 신채호는 의열단의 활동 지침이 된 조선 혁명 선언을 작성하였다. 대한 광복회 조직은 박상진, 조선말 큰사전 편찬은 조선어 학회가 주도한 일이다.","ans":3,"pts":3},{"id":"67-39","r":"67","n":39,"era":"일제강점기","topic":"윤봉길","exp":"한인 애국단에 가입하고 훙커우 공원 의거를 일으켰으며 김구에게 시계를 남겼다는 단서는 모두 윤봉길을 가리킨다. 윤봉길은 1932년 상하이 훙커우 공원에서 폭탄을 던져 일본군 장성 등을 처단하였다. 나석주는 동양 척식 주식회사에 폭탄을 던진 의열단원이므로 구분해야 한다.","ans":3,"pts":1},{"id":"67-40","r":"67","n":40,"era":"일제강점기","topic":"태평양 전쟁기","exp":"태평양 전쟁(1941~1945)이 전개되던 시기 일제는 한국인을 전쟁에 강제 동원하였다. 이 시기 한국 광복군은 영국군의 요청으로 미얀마 전선에 대원을 파견하여 활동하였다. 6·10 만세 운동(1926)이나 토지 조사령 공포(1912)는 그보다 앞선 시기의 일이므로 맞지 않는다.","ans":4,"pts":2},{"id":"67-41","r":"67","n":41,"era":"현대","topic":"좌우 합작 위원회","exp":"1946년 7월 미군정의 지원 아래 여운형, 김규식 등이 중심이 되어 결성한 단체는 좌우 합작 위원회이다. 이 위원회는 좌우 대립을 넘어 통일 정부 수립을 목표로 좌우 합작 7원칙을 발표하였다. 남북 조절 위원회는 1972년 7·4 남북 공동 성명에 따라 설치된 기구이므로 시기가 다르다.","ans":3,"pts":2},{"id":"67-42","r":"67","n":42,"era":"현대","topic":"제주 4·3 사건","exp":"미군정기에 시작되어 이승만 정부 수립 이후까지 이어졌고, 남한만의 단독 정부 수립에 반대하는 무장대와 토벌대 간 충돌 및 진압 과정에서 많은 주민이 희생된 사건은 제주 4·3 사건이다. 동백꽃은 이 사건 희생자를 기리는 상징이다. 2·28 민주 운동은 1960년 대구에서 일어난 학생 시위이므로 구분해야 한다.","ans":2,"pts":2},{"id":"67-43","r":"67","n":43,"era":"현대","topic":"6·25 전쟁","exp":"북한군의 남침으로 시작되어 인천 상륙 작전, 중국군 참전, 정전 협정 체결로 이어진 (가) 전쟁은 6·25 전쟁(1950~1953)이다. 전쟁 중 유엔군 참전, 흥남 철수 작전, 거제도 포로수용소 설치가 있었다. 13도 창의군의 서울 진공 작전은 1908년 정미의병 때의 일이므로 옳지 않아 정답이 된다.","ans":4,"pts":2},{"id":"67-44","r":"67","n":44,"era":"현대","topic":"4·19 혁명","exp":"대학 교수단이 시국 선언 후 가두 시위에 나섰고 이승만 대통령이 하야했다는 일기 내용은 4·19 혁명(1960)에 해당한다. 4·19 혁명은 3·15 부정 선거에 항의하여 일어나 독재 정권을 무너뜨렸다. 신군부에 저항한 것은 5·18 민주화 운동, 대통령 직선제 개헌을 이끈 것은 6월 민주 항쟁이다.","ans":4,"pts":2},{"id":"67-45","r":"67","n":45,"era":"현대","topic":"노태우 정부","exp":"서울 올림픽 개최, 남북한 유엔 동시 가입, 한중 국교 수립은 모두 노태우 정부 시기의 일이므로 (가)에도 같은 시기의 사실이 들어가야 한다. 노태우 정부는 1991년 남북 사이의 화해와 불가침 등을 담은 남북 기본 합의서를 채택하였다. 7·4 남북 공동 성명은 박정희 정부, 6·15 남북 공동 선언은 김대중 정부 때의 일이다.","ans":2,"pts":3},{"id":"67-46","r":"67","n":46,"era":"현대","topic":"박정희 정부","exp":"한일 협정 조인식(1965)은 박정희 정부 시기의 사건이다. 박정희 정부는 경제 개발을 추진하며 1970년 경부 고속 도로를 개통하였다. 농지 개혁법 제정은 이승만 정부, OECD 가입은 김영삼 정부, 한미 FTA 체결은 노무현 정부 시기의 일이므로 구분해야 한다.","ans":2,"pts":2},{"id":"67-47","r":"67","n":47,"era":"현대","topic":"전태일","exp":"서울 평화 시장에서 재단사로 일하며 바보회를 조직하였고 1970년 노동자의 인권을 위해 자신을 희생한 인물은 전태일이다. 그는 근로 기준법 준수를 외치며 분신하여 노동 운동에 큰 영향을 주었다. 이한열은 1987년 6월 민주 항쟁 과정에서 희생된 대학생이므로 혼동하지 않도록 한다.","ans":4,"pts":1},{"id":"67-48","r":"67","n":48,"era":"통합·기타","topic":"허난설헌","exp":"한국사 속 여성을 다룬 강의에서 허난설헌에 해당하는 내용을 찾는 문항이다. 허난설헌은 조선 중기의 시인으로, 그녀의 시는 사후 난설헌집으로 묶여 중국과 일본에서도 높은 평가를 받았다. 재산을 기부해 제주도민을 구제한 인물은 김만덕이고, 임금 삭감에 저항해 농성한 인물은 강주룡이다.","ans":1,"pts":2},{"id":"67-49","r":"67","n":49,"era":"통합·기타","topic":"부산 지역사","exp":"동삼동 패총, 초량 왜관, 임시 수도 기념관, 민주 공원이라는 답사 경로에서 (가) 지역이 부산임을 알 수 있다. 임진왜란 때 동래 부사 송상현은 동래성에서 왜군에 맞서 싸우다 순절하였다. 장보고가 청해진을 설치한 곳은 완도이고, 망이·망소이가 봉기한 곳은 공주 명학소이므로 지역이 다르다.","ans":4,"pts":3},{"id":"67-50","r":"67","n":50,"era":"통합·기타","topic":"동지","exp":"일 년 중 밤이 가장 길고 '작은 설'이라고도 불리며 팥죽을 쑤어 먹는 세시 풍속의 날은 동지이다. 동지에는 나쁜 기운을 물리치기 위해 대문이나 담장에 팥죽을 뿌리기도 하였다. 단오는 음력 5월 5일로 창포물에 머리를 감는 풍속이 있는 날이므로 구분해야 한다.","ans":2,"pts":1},{"id":"69-1","r":"69","n":1,"era":"선사·고조선","topic":"구석기 시대","exp":"뗀석기인 주먹도끼를 처음 사용한 시대라는 단서와 연천 전곡리 유적을 통해 구석기 시대임을 알 수 있다. 구석기 사람들은 먹을거리를 찾아 이동 생활을 하며 주로 동굴이나 강가의 막집에서 살았다. 가락바퀴로 실을 뽑은 것은 신석기 시대, 고인돌을 만든 것은 청동기 시대의 일이다.","ans":2,"pts":1},{"id":"69-2","r":"69","n":2,"era":"선사·고조선","topic":"고조선","exp":"우리 역사상 최초의 국가이며 단군왕검·곰·호랑이가 등장하는 건국 이야기를 가진 나라는 고조선이다. 고조선은 범금 8조(8조법)를 두어 사람을 죽이거나 남을 다치게 한 자를 처벌하는 등 사회 질서를 유지하였다. 영고라는 제천 행사는 부여, 책화는 동예의 풍습이므로 혼동하지 않아야 한다.","ans":4,"pts":2},{"id":"69-3","r":"69","n":3,"era":"삼국·가야","topic":"가야의 문화유산","exp":"'철의 왕국'이라는 별명과 유네스코 세계유산에 등재된 가야고분군을 기념한다는 내용에서 가야 특별전임을 알 수 있다. 가야는 질 좋은 철이 많이 나 철제 판갑옷 같은 철기 문화가 발달하였으므로 철제 판갑옷이 답이다. 칠지도는 백제가 왜에 보낸 칼이고, 성덕 대왕 신종은 통일신라의 범종이다.","ans":4,"pts":2},{"id":"69-4","r":"69","n":4,"era":"삼국·가야","topic":"신라 법흥왕","exp":"병부 설치, 율령 반포와 공복 제정, 불교 공인(널리 퍼짐)은 모두 신라 법흥왕의 업적이다. 법흥왕은 이러한 정책으로 나라의 통치 체제를 정비하고 금관가야를 병합하기도 하였다. 한강 유역을 차지하고 영토를 크게 넓힌 진흥왕과 구분해야 한다.","ans":1,"pts":2},{"id":"69-5","r":"69","n":5,"era":"삼국·가야","topic":"백제(사비 시기)","exp":"성왕이 수도로 삼은 부여(사비)와 부소산성·정림사지 등의 답사 코스를 통해 (가)가 백제임을 알 수 있다. 백제는 무령왕 때 지방의 주요 지역에 22담로를 두고 왕족을 보내 다스리게 하였다. 주몽이 세운 나라는 고구려이고, 한의 침략으로 멸망한 나라는 고조선이다.","ans":2,"pts":2},{"id":"69-6","r":"69","n":6,"era":"삼국·가야","topic":"살수 대첩","exp":"고구려가 외세의 침략을 막아낸 사례를 묻고 있다. 을지문덕은 612년 살수에서 수의 대군을 크게 물리쳤는데 이것이 살수 대첩이다. 계백의 황산벌 전투는 백제가 신라에 맞선 싸움이고, 이성계와 왕건의 활약은 고구려와 관계가 없다.","ans":1,"pts":2},{"id":"69-7","r":"69","n":7,"era":"남북국","topic":"원효","exp":"『대승기신론소』를 짓고 모든 것이 한마음에서 나온다는 일심 사상을 주장한 인물은 신라의 승려 원효이다. 원효는 무애가라는 노래를 지어 부르며 백성에게 어려운 불교 교리를 쉽게 전해 불교 대중화에 힘썼다. 왕오천축국전을 지은 인물은 혜초, 수선사 결사를 제창한 인물은 고려의 지눌이다.","ans":4,"pts":3},{"id":"69-8","r":"69","n":8,"era":"남북국","topic":"발해","exp":"문왕 때 '대흥' 연호를 쓴 정효 공주 묘지와 상경성에서 출토된 이불병좌상은 모두 발해의 문화유산이다. 발해는 전성기에 중국으로부터 바다 동쪽의 융성한 나라라는 뜻의 해동성국이라 불렸다. 9주 5소경을 둔 나라는 통일신라이므로 구분해야 한다.","ans":3,"pts":1},{"id":"69-9","r":"69","n":9,"era":"남북국","topic":"신라 하대의 동요","exp":"혜공왕 피살 이후 왕위 다툼이 치열했던 시기는 신라 하대로, 지도의 김헌창의 난과 원종과 애노의 난이 이를 보여준다. 이 시기 지방에서는 스스로를 성주·장군이라 부르는 호족이 성장하였다. 장용영은 조선 정조, 별무반은 고려 숙종 때의 군사 조직이므로 시기가 맞지 않는다.","ans":4,"pts":2},{"id":"69-10","r":"69","n":10,"era":"남북국","topic":"궁예","exp":"수도를 송악에서 철원으로 옮기고 광평성 등 관서를 설치한 인물은 후고구려를 세운 궁예이다. 궁예는 나라 이름을 마진을 거쳐 태봉으로 바꾸었다. 백제 계승을 내세운 인물은 후백제의 견훤이고, 우산국 복속은 신라 지증왕 때의 일이다.","ans":3,"pts":3},{"id":"69-11","r":"69","n":11,"era":"고려","topic":"거란의 침입 격퇴","exp":"서희의 강동 6주 확보(1차), 양규의 흥화진 방어(2차)에 이어지는 고려와 거란의 전쟁 장면을 묻고 있다. 3차 침입 때 강감찬이 귀주에서 거란군을 크게 물리친 귀주 대첩이 (가)에 들어가야 한다. 김윤후의 충주성 전투는 몽골, 윤관의 동북 9성은 여진과 관련된 사건이다.","ans":3,"pts":2},{"id":"69-12","r":"69","n":12,"era":"고려","topic":"고려의 화폐","exp":"고려 숙종 때 의천의 건의로 주전도감을 설치하고 화폐를 발행하였다는 단서에서 해동통보를 찾을 수 있다. 해동통보는 건원중보, 은병(활구)과 함께 고려 시대의 대표적인 화폐이다. 상평통보는 조선 후기, 백동화는 개항기에 사용된 화폐이다.","ans":4,"pts":2},{"id":"69-13","r":"69","n":13,"era":"고려","topic":"만적의 난","exp":"개경에서 노비 만적이 신분 해방을 외치며 봉기를 계획한 만적의 난(1198)에 대한 자료이다. 이 사건은 무신정변(1170) 이후 무신 집권기에 일어났으므로 연표의 (다) 시기에 해당한다. 무신 집권기에는 신분 질서가 흔들리며 하층민의 봉기가 잇따랐다.","ans":3,"pts":3},{"id":"69-14","r":"69","n":14,"era":"고려","topic":"화통도감","exp":"최무선이 원의 기술자에게 염초 만드는 법을 배워 설치를 건의하였다는 내용에서 화약과 화포를 만들던 화통도감임을 알 수 있다. 고려 우왕 때 설치된 화통도감의 화약 무기는 진포 대첩에서 왜구를 무찌르는 데 활용되었다. 훈련도감은 조선이 임진왜란 중에 설치한 군영이므로 혼동하지 않아야 한다.","ans":3,"pts":2},{"id":"69-15","r":"69","n":15,"era":"고려","topic":"대몽 항쟁","exp":"최우의 강화 천도(1232)와 김통정의 삼별초가 제주 항파두리성에서 항전한 시기(1271~1273) 사이의 사실을 묻고 있다. 이 시기 고려는 부처의 힘으로 몽골을 물리치고자 팔만대장경판을 만들었다. 삼국사기 편찬, 이자겸의 난, 묘청의 서경 천도 운동은 모두 몽골 침입 이전의 일이다.","ans":3,"pts":3},{"id":"69-16","r":"69","n":16,"era":"고려","topic":"일연","exp":"『삼국유사』를 저술하였고 인각사에서 입적하였다는 단서에서 (가) 인물이 승려 일연임을 알 수 있다. 일연은 단군의 건국 이야기를 비롯한 우리 역사와 불교 설화를 삼국유사에 담았다. 의상은 화엄 사상을 정리한 신라 승려이고, 지눌은 수선사 결사를 이끈 고려 승려이다.","ans":2,"pts":1},{"id":"69-17","r":"69","n":17,"era":"조선 전기","topic":"조선의 건국 과정","exp":"도평의사사의 건의로 경기 지역 토지에 과전법이 제정된 것은 1391년 고려 말의 일이다. 이후 1392년 이성계가 조선을 건국하고 1394년 한양을 새 도읍으로 정하였으므로 한양 천도가 답이다. 위화도 회군(1388)은 과전법 제정보다 앞서 일어난 사건이므로 답이 될 수 없다.","ans":3,"pts":2},{"id":"69-18","r":"69","n":18,"era":"조선 전기","topic":"조선의 과학 기술","exp":"천상열차분야지도, 수표, 칠정산과 함께 조선 시대 과학 문화유산 스탬프에 들어갈 수 없는 것을 골라야 한다. 측우기·자격루·혼천의는 모두 조선 세종 때를 중심으로 만들어진 과학 기구이다. 첨성대는 신라 선덕여왕 때 세워진 천문 관측 시설이므로 조선 시대 스탬프로 적절하지 않다.","ans":4,"pts":1},{"id":"69-19","r":"69","n":19,"era":"조선 전기","topic":"향약","exp":"『퇴계집』에 실린 자료로, 고을의 풍속을 바로잡기 위해 향약을 세운다는 내용이다. 향약은 조선의 사림이 보급한 향촌 자치 규약으로, 양반 중심의 향촌 질서가 자리 잡는 과정을 보여준다. 향·부곡·소 주민의 차별은 고려의 지방 제도와 관련된 주제이므로 거리가 멀다.","ans":4,"pts":3},{"id":"69-20","r":"69","n":20,"era":"조선 전기","topic":"임진왜란","exp":"부산진 첨사 정발이 조총을 앞세운 일본군에 맞서는 부산진순절도는 임진왜란(1592)의 첫 전투를 그린 것이다. 임진왜란 중 권율은 행주산성에서 왜군을 크게 물리쳤다. 어재연의 광성보 항전은 신미양요, 인조의 남한산성 피란은 병자호란 때의 일이다.","ans":1,"pts":2},{"id":"69-21","r":"69","n":21,"era":"조선 전기","topic":"경복궁","exp":"광화문을 정문으로 하는 (가) 문화유산은 조선의 법궁인 경복궁이다. 경복궁은 근정전을 정전으로 하여 국가의 중요한 의식을 치렀다. 역대 왕과 왕비의 신주를 모신 곳은 종묘이고, 정조의 명으로 축조된 것은 수원 화성이다.","ans":1,"pts":2},{"id":"69-22","r":"69","n":22,"era":"조선 전기","topic":"율곡 이이","exp":"신사임당의 아들이며 오죽헌에서 살았고 『동호문답』, 『성학집요』를 저술한 유학자는 율곡 이이이다. 이이는 현실 개혁 방안을 제시한 조선의 대표적 성리학자이다. 송시열은 조선 후기 서인(노론)의 영수, 홍대용은 지전설을 주장한 실학자이다.","ans":1,"pts":1},{"id":"69-23","r":"69","n":23,"era":"조선 후기","topic":"홍경래의 난","exp":"홍경래 등이 주도하고 관군이 정주성을 공격한다는 내용에서 세도 정치기의 홍경래의 난(1811)임을 알 수 있다. 이 봉기는 서북(평안도) 지역민에 대한 차별과 지배층의 수탈이 원인이 되어 일어났다. 집강소가 설치된 것은 동학 농민 운동, 박규수가 안핵사로 파견된 것은 임술 농민 봉기 때이다.","ans":2,"pts":2},{"id":"69-24","r":"69","n":24,"era":"통합·기타","topic":"봉수 제도","exp":"높은 곳에 봉수대를 두고 불과 연기의 개수로 적의 침입을 중앙에 알리는 장면이므로 봉수 제도이다. 봉수 제도는 고려와 조선에서 정비된 전통 시대의 대표적인 군사 통신 제도이다. 역참은 말을 갈아타는 교통 제도, 파발은 사람이 달려가 문서를 전하는 제도, 조운은 세금으로 걷은 곡식을 배로 나르는 제도이다.","ans":1,"pts":1},{"id":"69-25","r":"69","n":25,"era":"조선 전기","topic":"삼강행실도","exp":"효자·충신·열녀의 이야기를 엮어 유교 윤리를 보급하고자 편찬하였고 성종 때 한글로 풀이해 보급한 책은 『삼강행실도』이다. 세종 때 처음 만들어진 이 책은 그림과 함께 모범 사례를 실어 백성이 쉽게 이해하도록 하였다. 동의보감은 허준의 의학서, 목민심서는 정약용이 지방관의 자세를 정리한 책이다.","ans":3,"pts":2},{"id":"69-26","r":"69","n":26,"era":"조선 후기","topic":"조선 후기의 경제","exp":"박지원의 『열하일기』와 허생전이 쓰인 '이 시기'는 조선 후기이다. 조선 후기에는 대동법 실시 이후 관청에 물품을 조달하는 공인이 활동하며 상품 화폐 경제가 발달하였다. 동시전 설치는 신라, 솔빈부의 말은 발해, 벽란도 번성은 고려의 경제 모습이다.","ans":4,"pts":2},{"id":"69-27","r":"69","n":27,"era":"조선 후기","topic":"영조","exp":"탕평비를 세워 탕평 의지를 드러낸 (가) 왕은 조선 영조이다. 영조는 군역 부담을 줄여 주기 위해 군포를 2필에서 1필로 줄이는 균역법을 실시하였다. 규장각을 설치한 왕은 정조이고, 비변사를 폐지한 인물은 흥선 대원군이므로 구분해야 한다.","ans":2,"pts":2},{"id":"69-28","r":"69","n":28,"era":"조선 후기","topic":"붕당 정치의 전개","exp":"사림의 성장과 붕당 정치의 전개 순서를 묻는 문제이다. 조광조 개혁에 대한 훈구의 반발로 일어난 기묘사화(1519, 다) 이후, 효종 사후 상복 문제로 예송(1659, 나)이 벌어졌고, 희빈 장씨 소생 원자 책봉을 둘러싼 기사환국(1689, 가)으로 남인이 집권하였다. 따라서 (다)-(나)-(가) 순서가 맞다.","ans":4,"pts":3},{"id":"69-29","r":"69","n":29,"era":"개항기","topic":"갑신정변","exp":"우정국 개국 축하연에서 시작되어 개화당 정부가 청군의 개입으로 3일 만에 무너졌다는 내용에서 갑신정변(1884)임을 알 수 있다. 정변 이후 조선은 일본과 한성 조약을 맺어 배상금 지불 등을 약속하였다. 임오군란(1882)과 통리기무아문 설치(1880)는 갑신정변 이전의 일이다.","ans":2,"pts":2},{"id":"69-30","r":"69","n":30,"era":"개항기","topic":"갑오개혁","exp":"2024년 기준 130주년이며 노비제와 연좌제를 폐지한 근대적 개혁은 1894년의 갑오개혁이다. 갑오개혁으로 신분제가 법적으로 폐지되었으나 백정 등에 대한 사회적 차별은 남아 있었다. 광무개혁은 대한제국 수립 이후 추진된 개혁이므로 혼동하지 않아야 한다.","ans":2,"pts":1},{"id":"69-31","r":"69","n":31,"era":"일제강점기","topic":"남강 이승훈","exp":"신민회 결성 참여, 민족 대표 33인, 민립 대학 설립 운동의 주인공은 남강 이승훈이다. 이승훈은 평안북도 정주에 오산 학교를 세워 민족 교육과 인재 양성에 힘썼다. 훙커우 공원 의거는 윤봉길, 을밀대 고공 농성은 노동 운동가 강주룡의 활동이다.","ans":3,"pts":3},{"id":"69-32","r":"69","n":32,"era":"일제강점기","topic":"대한 광복회","exp":"박상진이 1915년 조직한 비밀 결사로 독립 전쟁 자금 모금과 친일 부호 처단을 주도하였다는 단서에서 대한 광복회임을 알 수 있다. 대한 광복회는 공화정 수립을 목표로 국내에서 활동한 1910년대 대표적 비밀 결사이다. 의열단은 1919년 김원봉이 만주에서 조직한 단체이므로 구분해야 한다.","ans":2,"pts":2},{"id":"69-33","r":"69","n":33,"era":"개항기","topic":"정미의병","exp":"1907년 고종의 강제 퇴위와 군대 해산에 반발하여 일어난 의병은 정미의병이다. 해산 군인들이 합류해 전투력이 강해진 정미의병은 13도 창의군을 결성하여 서울 진공 작전을 시도하였다. 최익현이 주도한 것은 을사의병이고, 백산 4대 강령은 동학 농민군이 발표한 것이다.","ans":2,"pts":2},{"id":"69-34","r":"69","n":34,"era":"일제강점기","topic":"독립군의 활동 순서","exp":"홍범도 부대 중심의 봉오동 전투는 1920년, 양세봉의 조선 혁명군이 중국군과 연합한 영릉가 전투는 1932년, 지청천의 한국광복군이 인도·미얀마 전선에서 영국군과 공동 작전을 편 것은 1943년경이다. 따라서 (가)-(나)-(다) 순서가 맞다. 독립군 활동이 1920년대 만주에서 1940년대 연합 작전으로 발전하는 흐름을 기억해 두면 좋다.","ans":1,"pts":3},{"id":"69-35","r":"69","n":35,"era":"개항기","topic":"안중근","exp":"이토 히로부미를 처단하고 뤼순 감옥에서 1910년 순국하며 유묵을 남긴 인물은 안중근이다. 안중근은 옥중에서 한·중·일이 협력해야 한다는 『동양 평화론』을 저술하였다. 한인 애국단을 조직한 인물은 김구, 조선 혁명 선언을 쓴 인물은 신채호이다.","ans":1,"pts":2},{"id":"69-36","r":"69","n":36,"era":"현대","topic":"여운형","exp":"신한 청년당 결성, 조선 건국 준비 위원회 위원장, 좌우 합작 위원회 조직이라는 힌트를 종합하면 몽양 여운형이다. 여운형은 광복 직후 건국을 준비하고 좌우 대립을 극복하고자 김규식과 함께 좌우 합작 운동을 이끌었다. 김규식은 좌우 합작에 함께했지만 건국 준비 위원회 위원장은 아니었다.","ans":2,"pts":2},{"id":"69-37","r":"69","n":37,"era":"일제강점기","topic":"대한민국 임시 정부","exp":"상하이에서 수립되었고 독립 공채를 발행해 자금을 모았다는 내용에서 대한민국 임시 정부임을 알 수 있다. 임시 정부는 미국에 구미 위원부를 두어 외교 활동을 전개하였다. 한성순보를 발행한 곳은 박문국이고, 만민 공동회를 개최한 것은 독립 협회이다.","ans":2,"pts":2},{"id":"69-38","r":"69","n":38,"era":"일제강점기","topic":"산미 증식 계획","exp":"1920년부터 실시되어 쌀은 늘었지만 더 많은 양이 군산항 등을 통해 일본으로 빠져나간 정책은 산미 증식 계획이다. 이로 인해 조선의 식량 사정은 오히려 나빠졌다. 토지 조사 사업은 1910년대에 실시된 정책이고, 방곡령은 개항기에 곡물 유출을 막으려던 조치이다.","ans":3,"pts":1},{"id":"69-39","r":"69","n":39,"era":"일제강점기","topic":"광주 학생 항일 운동","exp":"광주의 비밀 학생 조직 성진회, 1929년 한일 학생 간의 충돌이 발단이라는 단서에서 광주 학생 항일 운동임을 알 수 있다. 이 운동에는 신간회가 진상 조사단을 파견하여 지원하였다. 순종의 인산일을 계기로 일어난 것은 6·10 만세 운동(1926)이므로 혼동하지 않아야 한다.","ans":4,"pts":2},{"id":"69-40","r":"69","n":40,"era":"일제강점기","topic":"민족 말살 통치기","exp":"중일 전쟁(1937) 이후 침략 전쟁을 확대하며 한국인을 강제 동원하던 '이 시기'는 1930년대 후반 이후의 민족 말살 통치기이다. 이 시기 일제는 미곡 공출제를 시행해 식량을 강제로 거두어 갔다. 조선 태형령과 헌병 경찰 제도는 1910년대 무단 통치기의 정책이다.","ans":3,"pts":2},{"id":"69-41","r":"69","n":41,"era":"현대","topic":"모스크바 3국 외상 회의","exp":"신탁 통치 문제를 왜곡 보도하여 반탁 운동이 일어나게 한 '이 회의'는 1945년 12월의 모스크바 3국 외상 회의이다. 이 회의는 8·15 광복(1945.8)과 대한민국 정부 수립(1948.8) 사이에 열렸으므로 (가) 시기에 해당한다. 회의에서는 임시 민주 정부 수립과 최대 5년간의 신탁 통치 등이 결정되었다.","ans":1,"pts":3},{"id":"69-42","r":"69","n":42,"era":"일제강점기","topic":"브나로드 운동","exp":"심훈의 소설 상록수의 배경이 된, 동아일보가 주도한 농촌 계몽 운동은 브나로드 운동(1931~1934)이다. '민중 속으로'라는 뜻의 이 운동은 한글 보급과 문맹 퇴치에 힘썼다. 물산 장려 운동은 국산품 애용 운동이고, 형평 운동은 백정에 대한 차별 철폐 운동이다.","ans":2,"pts":2},{"id":"69-43","r":"69","n":43,"era":"현대","topic":"6·25 전쟁","exp":"'님 계신 전선'과 흥남 부두·1·4 후퇴가 나오는 '굳세어라 금순아'는 모두 6·25 전쟁(1950~1953)과 관련된 노래이다. 유엔군 참전, 인천 상륙 작전, 발췌 개헌(1952)은 전쟁 중의 사실이 맞다. 반민족 행위 처벌법은 전쟁 이전인 1948년에 제정되었으므로 옳지 않은 것은 ④이다.","ans":4,"pts":2},{"id":"69-44","r":"69","n":44,"era":"현대","topic":"6월 민주 항쟁","exp":"이한열이 최루탄에 맞아 쓰러진 사건과 '호헌 철폐, 독재 타도' 구호에서 1987년 6월 민주 항쟁임을 알 수 있다. 6월 민주 항쟁의 결과 6·29 선언이 발표되어 5년 단임의 대통령 직선제 개헌이 이루어졌다. 3·15 부정 선거에 항의한 것은 4·19 혁명, 시민군이 조직된 것은 5·18 민주화 운동이다.","ans":3,"pts":2},{"id":"69-45","r":"69","n":45,"era":"현대","topic":"김대중 정부의 경제","exp":"1998년 제15대 대통령으로 취임하였고 노벨 평화상을 수상한 인물은 김대중 대통령이다. 김대중 정부는 외환 위기 극복에 힘써 국제 통화 기금(IMF)의 구제 금융 자금을 예정보다 앞당겨 상환하였다. 경제 협력 개발 기구(OECD) 가입은 김영삼 정부, 한미 FTA 체결은 노무현 정부 시기의 일이다.","ans":4,"pts":2},{"id":"69-46","r":"69","n":46,"era":"통합·기타","topic":"역사 속 귀화 인물","exp":"허황옥이 결혼한 (가)는 금관가야의 김수로왕, 쌍기의 건의를 받은 (나)는 고려 광종, 이지란이 도운 (다)는 조선 태조 이성계, 김충선에게 관직을 내린 (라)는 선조이다. 광종은 노비안검법을 실시해 억울하게 노비가 된 사람들을 풀어 주고 호족의 힘을 약화시켰으므로 ②가 맞다. 태학 설립은 고구려 소수림왕, 경국대전 완성은 조선 성종의 업적이다.","ans":2,"pts":3},{"id":"69-47","r":"69","n":47,"era":"통합·기타","topic":"전주 지역사","exp":"태조 어진을 모신 경기전, 전라 감영 선화당, 동학 농민군과 정부군이 화약을 맺은 곳, 전동 성당이라는 힌트가 모두 가리키는 지역은 전주이다. 전주는 후백제의 도읍이었고 동학 농민 운동 때 전주 화약이 체결된 곳이기도 하다. 비빔밥이라는 경품도 전주를 암시하는 단서이다.","ans":3,"pts":1},{"id":"69-48","r":"69","n":48,"era":"통합·기타","topic":"시대별 유학자","exp":"시대를 대표하는 유학자들의 활동을 묻는 통합형 문제이다. 신라 말 6두품 출신 최치원은 진성 여왕에게 개혁안인 시무 10여 조를 건의하였으므로 ①이 맞다. 백운동 서원을 세운 인물은 주세붕, 동사강목을 저술한 인물은 안정복이므로 짝이 맞지 않는다.","ans":1,"pts":2},{"id":"69-49","r":"69","n":49,"era":"조선 전기","topic":"앙부일구","exp":"조선 시대에 제작된 해시계라는 설명에서 (가)가 앙부일구임을 알 수 있다. 앙부일구는 오목한 솥 모양의 시계로, 영침의 그림자가 가리키는 위치로 시각과 절기를 읽었다. 소리로 시간을 알려주는 장치는 물시계인 자격루의 특징이므로 구분해야 한다.","ans":3,"pts":2},{"id":"69-50","r":"69","n":50,"era":"통합·기타","topic":"정월 대보름","exp":"음력 1월 15일에 액운을 물리치고 건강과 풍년을 기원하며 달집태우기를 하는 세시 풍속은 정월 대보름이다. 정월 대보름에는 부럼 깨기, 오곡밥 먹기, 쥐불놀이 등도 행해졌다. 동지는 팥죽을 먹는 날이고, 추석은 음력 8월 15일이므로 날짜 단서로 구분할 수 있다.","ans":4,"pts":1},{"id":"71-1","r":"71","n":1,"era":"선사·고조선","topic":"신석기 시대 생활","exp":"농경과 목축이 시작되었고 빗살무늬 토기와 갈돌·갈판을 사용했다는 단서에서 (가)는 신석기 시대임을 알 수 있다. 신석기 시대 사람들은 가락바퀴로 실을 뽑아 옷이나 그물을 만들었다. 철제 농기구는 철기 시대, 고인돌과 거푸집은 청동기 시대의 모습이므로 구분해야 한다.","ans":1,"pts":1},{"id":"71-2","r":"71","n":2,"era":"선사·고조선","topic":"동예의 풍습","exp":"단궁·과하마·반어피라는 특산물, 무천이라는 제천 행사, 책화의 풍습은 모두 동예의 특징이다. 동예는 다른 부족의 영역을 침범하면 노비나 소·말로 배상하게 하는 책화라는 풍습이 있었다. 부여는 영고, 삼한 지역의 마한은 별도의 소국 연맹이므로 헷갈리지 않아야 한다.","ans":1,"pts":2},{"id":"71-3","r":"71","n":3,"era":"삼국·가야","topic":"신라 진흥왕","exp":"황룡사를 창건하고 화랑도를 국가 조직으로 정비한 왕은 신라 진흥왕이다. 진흥왕은 한강 유역을 차지한 뒤 북한산에 순수비를 세워 영토 확장을 기념하였다. 김흠돌의 난을 진압한 것은 통일 이후의 신문왕이므로 구분해야 한다.","ans":4,"pts":2},{"id":"71-4","r":"71","n":4,"era":"삼국·가야","topic":"백제 성왕","exp":"수도를 웅진에서 사비로 옮기고 국호를 남부여로 바꾸었으며 한강 유역 일부를 되찾았다는 내용에서 일기의 주인공이 백제 성왕임을 알 수 있다. 성왕은 사비 천도와 체제 정비로 백제 중흥을 꾀하였다. 무령왕은 22담로에 왕족을 파견한 왕이므로 혼동하지 않아야 한다.","ans":1,"pts":2},{"id":"71-5","r":"71","n":5,"era":"삼국·가야","topic":"금관가야의 발전","exp":"김해 구지봉과 김수로의 건국 설화, 풍부한 철 생산이라는 단서에서 (가)는 금관가야임을 알 수 있다. 금관가야는 질 좋은 철을 바탕으로 낙랑군과 왜를 잇는 중계 무역으로 번성하였다. 범금 8조는 고조선, 화백 회의는 신라의 것이므로 구분해야 한다.","ans":1,"pts":2},{"id":"71-6","r":"71","n":6,"era":"삼국·가야","topic":"고구려의 발전","exp":"수도 국내성, 광개토 대왕릉비, 안악 3호분 행렬도는 모두 고구려의 문화유산이다. 고구려는 수도에 태학, 지방에 경당을 두어 학문과 무예를 가르치며 인재를 길렀다. 독서삼품과는 통일신라, 정사암 회의는 백제의 제도이므로 헷갈리지 않아야 한다.","ans":4,"pts":3},{"id":"71-7","r":"71","n":7,"era":"남북국","topic":"신라 말 사회 동요","exp":"원종과 애노가 사벌주에서 반란을 일으키고 적고적이라 불린 도적이 일어났다는 내용은 신라 말의 혼란을 보여 준다. 진성 여왕 무렵 세금 독촉으로 농민 봉기가 잇따르며 신라 사회가 크게 흔들렸으므로 탐구 주제로는 신라 말의 사회 동요가 알맞다.","ans":2,"pts":1},{"id":"71-8","r":"71","n":8,"era":"남북국","topic":"신라 학자 설총","exp":"원효 대사의 아들이며 이두를 체계화하고 신문왕에게 화왕계를 지어 바쳤다는 단서에서 (가)는 설총임을 알 수 있다. 설총은 유학 경전을 우리말 표기 방식으로 풀이하여 학문 발전에 기여한 통일신라의 유학자이다. 혜초는 왕오천축국전을 지은 승려이므로 구분해야 한다.","ans":2,"pts":2},{"id":"71-9","r":"71","n":9,"era":"남북국","topic":"발해의 발전","exp":"문왕의 딸 정혜 공주의 묘지석과 보력이라는 독자 연호에서 (가)는 발해임을 알 수 있다. 발해는 5경 15부 62주의 지방 행정 제도를 갖추고 해동성국이라 불릴 만큼 발전하였다. 사출도는 부여, 청해진의 해상 무역은 통일신라 장보고와 관련되므로 헷갈리지 않아야 한다.","ans":4,"pts":2},{"id":"71-10","r":"71","n":10,"era":"고려","topic":"후삼국 통일 과정","exp":"견훤이 완산주에 도읍하여 후백제를 세운 것이 900년, 고려가 고창 전투에서 승리한 것이 930년, 경순왕이 고려에 항복한 것이 935년이다. 따라서 (가)-(다)-(나)의 순서가 옳다. 후삼국 시대는 고려 태조 왕건의 통일로 마무리되었다.","ans":2,"pts":3},{"id":"71-11","r":"71","n":11,"era":"고려","topic":"고려 광종","exp":"고려 제4대 왕으로 광덕 등 독자 연호를 쓰고 처음 과거제를 실시했으며 관리의 공복을 제정한 왕은 광종이다. 광종은 노비안검법을 시행해 불법으로 노비가 된 사람을 풀어 주고 호족의 세력을 약화시켰다. 훈요 10조는 태조, 전민변정도감은 공민왕과 관련되므로 구분해야 한다.","ans":3,"pts":1},{"id":"71-12","r":"71","n":12,"era":"고려","topic":"고려의 지방 제도","exp":"수월관음도는 고려 시대에 제작된 대표적인 불화이므로 (가)는 고려이다. 고려는 국경 지대에 동계와 북계라는 군사 행정 구역을 두어 외적의 침입에 대비하였다. 5소경과 9서당 10정은 통일신라, 22담로는 백제의 제도이므로 헷갈리지 않아야 한다.","ans":3,"pts":2},{"id":"71-13","r":"71","n":13,"era":"고려","topic":"고려 현종과 거란","exp":"강조의 정변으로 옹립되었고 거란 침입 때 나주로 피란했으며 귀주 대첩에서 승리한 강감찬을 맞이한 왕은 고려 현종이다. 현종 때 거란의 침입을 부처의 힘으로 물리치고자 초조대장경을 만들기 시작하였다. 이자겸의 난은 인종 때의 일이므로 구분해야 한다.","ans":3,"pts":3},{"id":"71-14","r":"71","n":14,"era":"고려","topic":"부석사 무량수전","exp":"고려 시대 목조 건축물로 배흘림기둥과 주심포 양식이 특징이라는 단서에 해당하는 것은 영주 부석사 무량수전이다. 무량수전은 현재 남아 있는 대표적인 고려 목조 건축물이다. 불국사 대웅전이나 법주사 팔상전은 조선 시대에 다시 지어진 건물이므로 헷갈리지 않아야 한다.","ans":2,"pts":2},{"id":"71-15","r":"71","n":15,"era":"고려","topic":"망이·망소이의 난","exp":"공주 명학소 사람 망이·망소이가 봉기했다는 내용으로 1176년의 망이·망소이의 난임을 알 수 있다. 이 봉기는 무신 정변(1170) 이후 무신 집권기의 혼란 속에서 일어났고 강화도 천도(1232) 이전이므로 (나) 시기에 해당한다. 특수 행정 구역인 소에 대한 차별이 봉기의 배경이었다.","ans":2,"pts":3},{"id":"71-16","r":"71","n":16,"era":"고려","topic":"윤관의 여진 정벌","exp":"숙종 때 별무반을 조직한 장면과 금이 형제 관계를 요구하는 장면 사이가 (가) 시기이다. 이 사이인 예종 때 윤관이 별무반을 이끌고 여진을 정벌하여 동북 9성을 쌓았다. 서희의 강동 6주 확보는 그보다 앞선 성종 때 거란과의 담판으로 이룬 것이므로 구분해야 한다.","ans":1,"pts":2},{"id":"71-17","r":"71","n":17,"era":"고려","topic":"고려의 팔관회","exp":"태조가 중요성을 강조했고 개경에서 열렸으며 주변 나라 상인과 사신이 특산물을 바쳤다는 내용에서 (가)는 팔관회임을 알 수 있다. 팔관회는 부처와 여러 토속신에게 제사하며 나라의 평안을 빈 고려 최대의 국가 행사였다. 영고는 부여의 제천 행사이므로 헷갈리지 않아야 한다.","ans":3,"pts":1},{"id":"71-18","r":"71","n":18,"era":"고려","topic":"고려의 경제생활","exp":"고려의 경제 상황을 묻는 문항으로, 고려에서는 활구라고 불린 은병이 고액 화폐로 사용되었다. 감자·고구마 재배와 만상·내상의 무역 활동은 조선 후기의 모습이다. 동시전은 신라 지증왕 때 시장을 감독하기 위해 설치된 기구이므로 구분해야 한다.","ans":2,"pts":2},{"id":"71-19","r":"71","n":19,"era":"조선 전기","topic":"조선 태종의 정책","exp":"왕자의 난을 일으키고 사병을 혁파했으며 신덕 왕후의 정릉을 옮긴 왕은 조선 태종 이방원이다. 태종은 호패법을 시행하여 인구를 파악하고 국가 재정과 군역의 기초를 마련하였다. 현량과는 중종 때 조광조의 건의로 실시되었고 경국대전 반포는 성종 때의 일이다.","ans":2,"pts":2},{"id":"71-20","r":"71","n":20,"era":"조선 전기","topic":"분청사기의 특징","exp":"그릇 표면에 백토를 분칠해 장식했고 고려 말부터 조선 전기까지 주로 만들어졌다는 설명은 분청사기에 해당한다. 따라서 분청사기 음각어문 편병이 알맞다. 상감 청자는 고려, 달항아리와 청화 백자는 조선 후기에 유행한 자기이므로 구분해야 한다.","ans":2,"pts":2},{"id":"71-21","r":"71","n":21,"era":"조선 전기","topic":"세조의 직전법","exp":"세조가 과전을 개혁하여 현직 관리에게만 수조권을 주도록 한 제도는 직전법이다. 세조는 관리에게 지급할 토지가 부족해지자 직전법을 실시해 재정 문제를 해결하고자 하였다. 균역법은 영조, 영정법은 인조 때의 수취 제도 개혁이므로 헷갈리지 않아야 한다.","ans":3,"pts":2},{"id":"71-22","r":"71","n":22,"era":"조선 전기","topic":"공납과 대동법","exp":"각 지역의 토산물을 정기적으로 거두던 수취 제도는 공납이다. 해당 고을에서 나지 않는 물품이 부과되는 등 폐단이 커지자 이를 해결하기 위해 조선 후기에 특산물 대신 쌀 등으로 내게 하는 대동법이 실시되었다. 군역은 노동력, 전세는 토지에 매기는 세금이므로 구분해야 한다.","ans":1,"pts":2},{"id":"71-23","r":"71","n":23,"era":"조선 전기","topic":"임진왜란의 전개","exp":"1592년 일본의 침략으로 시작되었고 강항이 의병을 모집했다가 포로로 잡혀갔다는 내용에서 (가)는 임진왜란(정유재란 포함)임을 알 수 있다. 이 전쟁 중 이순신이 명량 해전에서 큰 승리를 거두었다. 이종무의 쓰시마섬 정벌은 세종 때, 어재연의 광성보 항전은 신미양요 때의 일이다.","ans":4,"pts":2},{"id":"71-24","r":"71","n":24,"era":"조선 후기","topic":"조선 정조의 정책","exp":"아버지 사도 세자의 무덤에 참배하고 돌아가며 지지대 고개에서 천천히 가자고 했다는 국왕은 정조이다. 정조는 젊고 유능한 문신을 뽑아 재교육하는 초계문신제를 실시하고 규장각을 키워 개혁 정치를 펼쳤다. 훈민정음 창제는 세종의 업적이므로 구분해야 한다.","ans":3,"pts":3},{"id":"71-25","r":"71","n":25,"era":"조선 후기","topic":"김홍도의 풍속화","exp":"조선 후기 서민들의 생활 모습을 생생하게 그린 김홍도의 풍속화 전시라는 단서에 맞는 작품은 무동이다. 무동은 악사들의 연주에 맞춰 춤추는 소년을 그린 김홍도의 대표 풍속화이다. 월하정인은 신윤복, 고사관수도는 조선 전기 강희안의 작품이므로 헷갈리지 않아야 한다.","ans":3,"pts":1},{"id":"71-26","r":"71","n":26,"era":"조선 후기","topic":"조선 후기 생활 모습","exp":"윤지충이 서학을 믿어 어머니의 신주를 불사르고 처형된 사건은 정조 때인 1791년의 신해박해로, 대화의 배경은 조선 후기이다. 이 시기에는 정감록 유행, 판소리 공연, 상평통보 사용을 볼 수 있었다. 삼별초는 고려 시대 대몽 항쟁 때의 군대이므로 볼 수 없는 모습이다.","ans":3,"pts":2},{"id":"71-27","r":"71","n":27,"era":"개항기","topic":"임오군란의 발발","exp":"정부의 개화 정책과 차별 대우에 반발해 구식 군인이 일으켰고 선혜청·별기군과 관련된 사건은 1882년 임오군란이다. 밀린 급료로 모래 섞인 쌀을 받은 구식 군인들의 분노가 폭발하여 일어났다. 갑신정변은 1884년 급진 개화파가 일으킨 정변이므로 구분해야 한다.","ans":4,"pts":2},{"id":"71-28","r":"71","n":28,"era":"조선 후기","topic":"서얼에 대한 차별","exp":"양반의 첩이 낳은 자식인 서얼에 대해 묻는 문항이다. 서얼은 문과 응시 등에서 차별을 받았고, 조선 후기에 이러한 차별을 없애 달라며 청요직 진출을 요구하는 통청 운동을 전개하였다. 매매·상속의 대상이 된 것은 노비이고 골품에 따른 제한은 신라의 골품제이다.","ans":4,"pts":3},{"id":"71-29","r":"71","n":29,"era":"개항기","topic":"흥선대원군의 정책","exp":"어린 고종을 대신해 나라를 다스렸고 경복궁 중건을 위해 원납전을 거두고 당백전을 발행한 인물은 흥선대원군이다. 그는 신미양요 이후 전국에 척화비를 세워 통상 수교 거부 의지를 밝혔다. 신해통공은 정조, 나선 정벌은 효종 때의 일이므로 헷갈리지 않아야 한다.","ans":1,"pts":2},{"id":"71-30","r":"71","n":30,"era":"개항기","topic":"개화파 김홍집","exp":"1880년 제2차 수신사로 일본에 다녀오며 황준헌의 조선책략을 들여왔고 갑오개혁 때 총리대신을 지낸 인물은 김홍집이다. 그는 군국기무처를 중심으로 개혁 전반을 이끌었다. 김옥균은 갑신정변, 서재필은 독립 협회를 주도한 인물이므로 구분해야 한다.","ans":2,"pts":2},{"id":"71-31","r":"71","n":31,"era":"개항기","topic":"강화도 조약","exp":"병자년(1876)에 일본과 체결해 부산 외 두 개 항구를 추가로 개항하기로 한 조약은 강화도 조약이다. 이 조약에 따라 원산과 인천이 차례로 개항되었으며, 우리나라 최초의 근대적 조약이자 불평등 조약이었다. 정미 7조약은 1907년 군대 해산과 관련된 조약이므로 구분해야 한다.","ans":4,"pts":1},{"id":"71-32","r":"71","n":32,"era":"개항기","topic":"항일 의병 운동","exp":"최익현이 조약을 허락한 을사오적을 처단해야 한다며 의병을 일으키는 장면이므로 학습 주제는 항일 의병 운동의 전개가 알맞다. 을사늑약으로 외교권을 빼앗기자 최익현 등 유생과 민중이 각지에서 의병을 일으켰다. 임술 농민 봉기는 조선 철종 때의 농민 봉기이므로 헷갈리지 않아야 한다.","ans":4,"pts":2},{"id":"71-33","r":"71","n":33,"era":"개항기","topic":"동학 농민 운동","exp":"전봉준이 이끄는 농민군이 황룡촌에서 관군을 격파했다는 단서에서 (가)는 1894년 동학 농민 운동임을 알 수 있다. 농민군은 전주성을 점령한 뒤 정부와 전주 화약을 맺고 집강소를 설치해 개혁을 추진하였다. 박규수가 안핵사로 파견된 것은 1862년 임술 농민 봉기 때의 일이다.","ans":2,"pts":2},{"id":"71-34","r":"71","n":34,"era":"개항기","topic":"대한제국기 근대 문물","exp":"한성 전기 회사가 전차를 개통하고 동대문 발전소에서 전등 개설식이 열렸다는 기사로 1900년 무렵 대한 제국 시기임을 알 수 있다. 이 시기에는 1899년 개통된 경인선 기차를 타는 승객을 볼 수 있었다. 한성순보는 1880년대 박문국에서 발행되었고 라디오 방송은 일제강점기에 시작되었다.","ans":1,"pts":3},{"id":"71-35","r":"71","n":35,"era":"일제강점기","topic":"토지 조사 사업","exp":"조선 총독부가 지세 수취 등을 위해 임시 토지 조사국을 두고 시행한 (가)는 1910년대의 토지 조사 사업이다. 같은 시기에 회사 설립을 총독의 허가제로 한 회사령이 시행되었다. 원산 총파업(1929)과 국가 총동원법 제정(1938)은 이후 시기의 일이므로 구분해야 한다.","ans":1,"pts":2},{"id":"71-36","r":"71","n":36,"era":"일제강점기","topic":"봉오동 전투","exp":"1920년 6월 홍범도가 이끄는 독립군 연합 부대가 승리했고 이후 일본군이 훈춘 사건을 구실로 공격했다는 내용에서 (가)는 봉오동 전투임을 알 수 있다. 봉오동 전투는 독립군이 일본군 정규 부대를 크게 무찌른 승리였다. 청산리 전투는 같은 해 10월 김좌진 부대 중심으로 벌어졌으므로 구분해야 한다.","ans":1,"pts":1},{"id":"71-37","r":"71","n":37,"era":"일제강점기","topic":"방정환의 활동","exp":"천도교 소년회를 조직하는 등 소년 운동을 전개한 인물은 방정환이다. 방정환은 어린이라는 말을 널리 알리고 어린이날 제정에 기여하였다. 의열단 창설은 김원봉, 헤이그 특사 파견은 이준·이상설·이위종과 관련되므로 헷갈리지 않아야 한다.","ans":3,"pts":1},{"id":"71-38","r":"71","n":38,"era":"일제강점기","topic":"민족 말살 통치","exp":"황국 신민 서사 암송을 강요한 시기는 일제가 중일 전쟁(1937) 이후 침략 전쟁을 확대하던 민족 말살 통치기이다. 이 시기 일제는 신사 참배와 창씨개명 등을 강요하였다. 신간회 창립(1927)과 동양 척식 주식회사 설립(1908)은 그 이전의 일이므로 구분해야 한다.","ans":2,"pts":2},{"id":"71-39","r":"71","n":39,"era":"일제강점기","topic":"3·1 운동","exp":"고종의 장례 기간 중 탑골 공원 등에서 만세 시위로 시작되어 전국으로 확산된 (가)는 1919년 3·1 운동이다. 3·1 운동은 독립운동을 이끌 통일된 조직의 필요성을 일깨워 대한민국 임시 정부 수립의 계기가 되었다. 청군의 개입으로 진압된 것은 임오군란이므로 헷갈리지 않아야 한다.","ans":4,"pts":2},{"id":"71-40","r":"71","n":40,"era":"일제강점기","topic":"민립 대학 설립 운동","exp":"1920년대 이상재 등이 한국인의 고등 교육을 위해 1천만 원 모금을 목표로 전개한 운동은 민립 대학 설립 운동이다. 이 운동은 일제의 감시와 자연재해 등으로 어려움을 겪어 목표를 이루지 못했다. 물산 장려 운동은 토산품 애용을 내세운 경제 운동이므로 구분해야 한다.","ans":4,"pts":1},{"id":"71-41","r":"71","n":41,"era":"일제강점기","topic":"1920년대 일제 통치","exp":"올해 치안 유지법이 제정되었다는 대사에서 기사가 보도된 시기가 1925년 무렵임을 알 수 있다. 이 시기 조선 총독부는 일본의 쌀 부족을 메우기 위해 산미 증식 계획을 추진하고 있었다. 조선 건국 준비 위원회는 1945년 광복 직후에 조직되었으므로 볼 수 없는 모습이다.","ans":3,"pts":3},{"id":"71-42","r":"71","n":42,"era":"일제강점기","topic":"한인 애국단","exp":"1932년 1월 8일 도쿄에서 이봉창이 일왕을 향해 폭탄을 던졌다는 내용에서 (가)는 김구가 조직한 한인 애국단임을 알 수 있다. 한인 애국단은 이봉창·윤봉길 의거를 통해 침체된 대한민국 임시 정부에 활기를 불어넣었다. 조선어 학회는 한글 연구 단체이므로 헷갈리지 않아야 한다.","ans":4,"pts":2},{"id":"71-43","r":"71","n":43,"era":"일제강점기","topic":"저항 시인 이육사","exp":"수감 번호를 이름처럼 사용했고 시 광야를 지었다는 단서에서 '나'는 이육사임을 알 수 있다. 본명이 이원록인 그는 수감 번호 264에서 이육사라는 이름을 따왔으며 광야, 절정 등의 저항시를 남겼다. 한용운은 님의 침묵을 지은 승려 시인이므로 구분해야 한다.","ans":3,"pts":2},{"id":"71-44","r":"71","n":44,"era":"현대","topic":"정부 수립 과정","exp":"유엔 한국 임시 위원단을 설치해 총선거를 감독하도록 한 유엔 총회 결의안 112호는 1947년 11월에 발표되었다. 이는 8·15 광복(1945)과 대한민국 정부 수립(1948) 사이의 일이므로 (가) 시기에 해당한다. 이 결의에 따라 1948년 5·10 총선거가 실시되었다.","ans":1,"pts":3},{"id":"71-45","r":"71","n":45,"era":"현대","topic":"이승만 정부의 정책","exp":"친일파 청산을 위한 반민특위 활동에 비협조적이었던 (가) 정부는 이승만 정부이다. 이승만 정부 시기인 1949년 농지 개혁법이 제정되어 농민에게 농지가 분배되었다. 100억 달러 수출 달성은 박정희 정부, OECD 가입은 김영삼 정부 시기의 일이므로 구분해야 한다.","ans":1,"pts":2},{"id":"71-46","r":"71","n":46,"era":"현대","topic":"5·18 민주화 운동","exp":"1980년 광주 전남도청 앞 금남로에서 계엄군의 집단 발포로 많은 사상자가 발생했다는 단서에서 (가)는 5·18 민주화 운동임을 알 수 있다. 신군부의 계엄 확대에 맞서 광주 시민들이 민주주의를 요구하며 저항하였다. 6월 민주 항쟁은 1987년 대통령 직선제를 요구한 운동이므로 구분해야 한다.","ans":4,"pts":1},{"id":"71-47","r":"71","n":47,"era":"현대","topic":"박정희 정부의 경제","exp":"경부 고속 도로는 박정희 정부 시기인 1970년에 완공되었으므로 (가)는 박정희 정부이다. 이 시기 제2차 경제 개발 5개년 계획이 추진되어 수출 중심의 경제 성장이 이루어졌다. 금융 실명제는 김영삼 정부, 3저 호황은 전두환 정부 시기의 일이므로 헷갈리지 않아야 한다.","ans":3,"pts":2},{"id":"71-48","r":"71","n":48,"era":"현대","topic":"김영삼 정부의 정책","exp":"광복 50주년(1995)을 맞아 일제 잔재 청산을 추진했고 국민학교 명칭을 초등학교로 바꾼 정부는 김영삼 정부이다. 김영삼 정부는 역사 바로 세우기의 하나로 조선 총독부 건물을 철거하였다. 한일 월드컵 개최는 김대중 정부, G20 정상 회의는 이명박 정부 시기의 일이다.","ans":1,"pts":3},{"id":"71-49","r":"71","n":49,"era":"현대","topic":"10·4 남북 정상 선언","exp":"대통령이 처음으로 군사 분계선을 걸어서 넘었고 개성 공업 지구를 방문했다는 단서에서 2007년 노무현 정부의 남북 정상 회담임을 알 수 있다. 이 회담에서 6·15 남북 공동 선언을 계승한 10·4 남북 정상 선언이 발표되었다. 남북 기본 합의서는 노태우 정부 시기에 채택되었으므로 구분해야 한다.","ans":3,"pts":2},{"id":"71-50","r":"71","n":50,"era":"통합·기타","topic":"주권 의식의 변화","exp":"황제의 무한한 군주권을 규정한 대한국 국제 반포는 1899년, 융희 황제의 주권 포기를 국민 주권의 시작으로 선언한 대동단결 선언은 1917년, 국민 주권을 명시한 제헌 헌법 공포는 1948년의 일이다. 따라서 (가)-(다)-(나)의 순서가 옳다. 주권이 황제에서 국민으로 옮겨 가는 과정을 보여 주는 문항이다.","ans":2,"pts":2},{"id":"73-1","r":"73","n":1,"era":"선사·고조선","topic":"청동기 시대","exp":"울주 검단리 유적의 환호와 고인돌, '계급이 출현한 시대'라는 단서로 청동기 시대를 묻는 문항이다. 청동기 시대에는 비파형 동검을 만들어 지배자의 권위를 드러냈으므로 ②가 맞다. ③ 동굴이나 막집 생활은 구석기, ④ 가락바퀴는 신석기 시대부터 사용된 도구라서 답이 아니다.","ans":2,"pts":1},{"id":"73-2","r":"73","n":2,"era":"선사·고조선","topic":"부여","exp":"좋은 말이 생산되고 마가·우가 등 여러 가(加)가 사출도를 다스렸다는 내용은 부여의 특징이다. 부여는 12월에 영고라는 제천 행사를 열었으므로 ①이 정답이다. ② 소도는 삼한, ③ 민며느리제는 옥저, ④ 범금 8조는 고조선의 풍습이다.","ans":1,"pts":2},{"id":"73-3","r":"73","n":3,"era":"삼국·가야","topic":"금관가야","exp":"수로왕이 세웠다고 전해지고 김해 대성동 고분군 유물이 나온 나라는 금관가야이다. 수로왕 탄생 설화에는 구지가라는 노래가 등장하므로 건국 신화를 분석하는 ④가 적절한 탐구 활동이다. ① 서옥제는 고구려의 혼인 풍습, ③ 이차돈 순교는 신라 불교 공인과 관련된다.","ans":4,"pts":2},{"id":"73-4","r":"73","n":4,"era":"남북국","topic":"승려 의상","exp":"화엄종 개창, 부석사 건립, 관음 신앙 강조는 모두 신라 승려 의상의 활동이므로 ③이 정답이다. 의상은 당에서 화엄학을 공부하고 돌아와 부석사를 세우고 화엄 사상을 널리 폈다. ② 원효는 무애가를 부르며 아미타 신앙을 전파한 인물로 구분해야 한다.","ans":3,"pts":1},{"id":"73-5","r":"73","n":5,"era":"삼국·가야","topic":"고구려 소수림왕","exp":"재위 371~384년, 전진으로부터 불교 수용, 태학 설립이라는 단서는 고구려 소수림왕의 업적이다. 소수림왕은 율령 반포와 함께 국가 체제를 정비하였으므로 ③이 정답이다. ④ 광개토대왕은 영토를 크게 넓힌 왕으로 시기가 더 늦다.","ans":3,"pts":2},{"id":"73-6","r":"73","n":6,"era":"삼국·가야","topic":"신라의 골품제","exp":"경주 금령총에서 출토된 도기 기마인물형 명기는 신라의 문화유산이다. 신라는 골품제라는 신분 제도로 관직 승진과 일상생활까지 제한하였으므로 ②가 정답이다. ③ 진대법은 고구려, ④ 책화는 동예의 풍습이라서 답이 아니다.","ans":2,"pts":2},{"id":"73-7","r":"73","n":7,"era":"삼국·가야","topic":"백제 멸망 이후","exp":"의자왕이 웅진성으로 피신하고 부여융이 항복하는 장면은 660년 백제 멸망 당시의 상황이다. 그 이후 나당 연합군은 668년 평양성을 함락시켜 고구려를 멸망시켰으므로 ④가 정답이다. ③ 고구려의 한성 함락(475)이나 ① 대가야 정복(562)은 모두 그 이전의 일이다.","ans":4,"pts":3},{"id":"73-8","r":"73","n":8,"era":"삼국·가야","topic":"백제 사비 문화유산","exp":"사비는 지금의 충남 부여로 백제의 마지막 수도였다. 부여 지역에 있는 백제 문화유산은 정림사지 오층 석탑이므로 ③이 정답이다. ① 풍납토성은 한성(서울) 시기 유적이고 ② 석굴암과 ④ 호우총 유물은 경주(신라)의 것이라서 조건에 맞지 않는다.","ans":3,"pts":3},{"id":"73-9","r":"73","n":9,"era":"남북국","topic":"발해","exp":"해동성국이라 불렸고 유득공이 그 역사를 정리하였다는 내용에서 발해임을 알 수 있다. 발해는 대조영이 동모산에서 건국하였으므로 ①이 정답이다. ④ 무태·성책은 궁예가 쓴 연호이고, 발해는 인안·대흥 등의 독자 연호를 사용하였다.","ans":1,"pts":2},{"id":"73-10","r":"73","n":10,"era":"남북국","topic":"후백제 견훤","exp":"아들 신검에 의해 금산사에 유폐되었다가 탈출해 왕건에게 귀부한 인물은 견훤이다. 견훤은 완산주(전주)에서 후백제를 세웠으므로 ③이 정답이다. ② 국호를 마진으로 바꾼 인물은 후고구려의 궁예이므로 혼동하지 않아야 한다.","ans":3,"pts":2},{"id":"73-11","r":"73","n":11,"era":"고려","topic":"서희의 외교 담판","exp":"거란 장수 소손녕과 담판을 벌여 강동 6주를 확보한 고려의 외교가는 서희이므로 ①이 정답이다. 서희는 거란의 1차 침입 때 싸우지 않고 외교로 영토를 넓힌 인물이다. ② 윤관은 별무반을 이끌고 여진을 정벌한 인물로 구분된다.","ans":1,"pts":1},{"id":"73-12","r":"73","n":12,"era":"고려","topic":"봉정사 극락전","exp":"고려 시대 목조 건축물이며 우리나라에 남아 있는 가장 오래된 목조 건축물이라는 단서에서 안동 봉정사 극락전임을 알 수 있다. 공민왕 때 지붕을 수리한 기록이 남아 있어 건립 시기가 그 이전임이 증명되었으므로 ②가 정답이다. ③ 법주사 팔상전과 ④ 화엄사 각황전은 조선 후기 건축물이다.","ans":2,"pts":2},{"id":"73-13","r":"73","n":13,"era":"고려","topic":"이자겸의 난","exp":"인종이 척준경을 회유해 이자겸을 제거하려는 장면으로, 이자겸의 난(1126)이 일어난 시기를 묻는다. 이는 귀주 대첩(1019)과 무신 정변(1170) 사이의 일이므로 (나) 시기인 ②가 정답이다. 이자겸의 난은 고려 문벌 사회가 흔들리기 시작한 사건이다.","ans":2,"pts":3},{"id":"73-14","r":"73","n":14,"era":"고려","topic":"삼국사기","exp":"본기·열전으로 구성된 기전체이고 김부식 등이 왕명을 받아 편찬한 현존하는 가장 오래된 역사서는 삼국사기이므로 ②가 정답이다. 삼국사기는 고려 인종 때(1145) 완성되었다. ③ 삼국유사는 일연이 지었고 단군 신화가 실려 있다는 점에서 구분된다.","ans":2,"pts":1},{"id":"73-15","r":"73","n":15,"era":"고려","topic":"대몽 항쟁","exp":"몽골의 침략을 물리친 전투를 조사하는 활동으로, 박서의 귀주성, 송문주의 죽주성과 같은 사례가 들어가야 한다. 김윤후는 처인성에서 부곡민과 함께 몽골 장수 살리타를 사살하였으므로 ④가 정답이다. ① 양헌수의 정족산성 전투는 병인양요, ③ 을지문덕의 살수 대첩은 수의 침입을 막은 것이다.","ans":4,"pts":2},{"id":"73-16","r":"73","n":16,"era":"고려","topic":"의창","exp":"고려와 조선 초의 구휼 기관으로, 창고에 비축한 곡물을 어려운 백성에게 빌려주거나 나누어 준 기구는 의창이므로 ①이 정답이다. 고려 태조의 흑창을 성종이 확대 개편한 것이 의창이다. ③ 제중원은 개항기에 세워진 서양식 병원으로 시대가 다르다.","ans":1,"pts":2},{"id":"73-17","r":"73","n":17,"era":"고려","topic":"공민왕의 개혁","exp":"정동행성 이문소를 폐지해 자주적인 정치를 실현하려 한 왕은 고려 공민왕이다. 공민왕은 쌍성총관부를 공격해 철령 이북의 땅을 되찾았으므로 ③이 정답이다. ① 12목 설치는 성종, ④ 노비안검법은 광종의 업적으로 구분해야 한다.","ans":3,"pts":2},{"id":"73-18","r":"73","n":18,"era":"고려","topic":"보조국사 지눌","exp":"선과 교를 함께 닦자는 정혜쌍수를 주장하고 사후 불일보조국사 시호를 받은 고려 승려는 지눌이다. 지눌은 타락한 불교계를 개혁하고자 수선사 결사를 제창하였으므로 ②가 정답이다. ① 천태종을 창시한 인물은 의천이라서 혼동하기 쉽다.","ans":2,"pts":2},{"id":"73-19","r":"73","n":19,"era":"고려","topic":"이성계와 황산 대첩","exp":"고려 말 황산에서 아지발도가 이끄는 왜구를 무찌르고 이후 위화도 회군으로 권력을 잡은 인물은 이성계이므로 ③이 정답이다. 이성계는 이 승리로 백성의 신망을 얻어 조선 건국의 기반을 다졌다. ④ 강감찬은 거란을 물리친 귀주 대첩의 주인공으로 시대가 다르다.","ans":3,"pts":1},{"id":"73-20","r":"73","n":20,"era":"조선 전기","topic":"조선의 대일 외교","exp":"신숙주가 쓴 해동제국기에 실렸고 쇼군이 사절단을 보냈다는 내용에서 (가)는 일본임을 알 수 있다. 조선은 세종 때 부산포·제포·염포의 삼포를 열어 일본과 제한된 무역을 허용하였으므로 ①이 정답이다. ③ 4군 6진 개척은 여진에 대한 정책이고 ④ 장문휴의 등주 공격은 발해 무왕의 일이다.","ans":1,"pts":3},{"id":"73-21","r":"73","n":21,"era":"조선 전기","topic":"세종의 업적","exp":"훈민정음을 창제한 왕은 세종으로, 훈민정음 해례본은 유네스코 세계 기록 유산에 등재되어 있다. 세종은 한양을 기준으로 한 역법서인 칠정산을 편찬하게 하였으므로 ①이 정답이다. ② 악학궤범은 성종, ③ 혼일강리역대국도지도는 태종 때 만들어졌다.","ans":1,"pts":2},{"id":"73-22","r":"73","n":22,"era":"조선 전기","topic":"원각사지 십층 석탑","exp":"1467년(세조 13년) 대리석으로 만들어졌고 화려한 조각이 새겨진 국보 탑은 서울 원각사지 십층 석탑이므로 ①이 정답이다. 이 탑은 고려의 경천사지 십층 석탑 양식을 계승하였다. ④ 익산 미륵사지 석탑은 백제의 탑이라서 시기가 전혀 다르다.","ans":1,"pts":3},{"id":"73-23","r":"73","n":23,"era":"통합·기타","topic":"공기놀이","exp":"다섯 개 이상의 돌을 던져 손으로 잡으며 노는 놀이라는 설명에서 공기놀이임을 알 수 있으므로 ②가 정답이다. 지역에 따라 짜게받기, 살구, 닷짝걸이 등으로 불렸고 오주연문장전산고에 관련 기록이 있다. ① 윷놀이는 윷가락을 던져 말을 옮기는 놀이로 구분된다.","ans":2,"pts":1},{"id":"73-24","r":"73","n":24,"era":"조선 전기","topic":"임진왜란","exp":"김시민이 진주성에서 활약한 전쟁은 임진왜란이다. 임진왜란 중 곽재우가 의령에서 의병을 일으켜 붉은 옷을 입고 싸웠으므로 ③이 정답이다. ① 김상용의 강화도 순절은 병자호란, ② 한성근의 문수산성 항전은 병인양요 때의 일이라서 답이 아니다.","ans":3,"pts":2},{"id":"73-25","r":"73","n":25,"era":"조선 전기","topic":"의녀","exp":"조선 시대에 남자 의원에게 진료받기를 꺼리는 여성들을 치료하기 위해 둔 여자 의원은 의녀이므로 ①이 정답이다. 의녀는 내의원·혜민서 등에서 활동하였고 장금·장덕의 활동이 조선왕조실록에 기록되어 있다. ② 무당은 굿을 하는 사람으로 의료 관직이 아니다.","ans":1,"pts":2},{"id":"73-26","r":"73","n":26,"era":"조선 후기","topic":"김홍도의 풍속화","exp":"단원은 조선 후기 화가 김홍도의 호로, 특별전에는 그의 작품이 들어가야 한다. 서당은 김홍도의 대표적인 풍속화이므로 ①이 정답이다. ③ 세한도는 김정희, ④ 인왕제색도는 정선의 작품이라서 답이 아니다.","ans":1,"pts":1},{"id":"73-27","r":"73","n":27,"era":"조선 후기","topic":"정조의 정책","exp":"금난전권 폐지(신해통공)와 장용영 설치는 조선 정조의 업적이다. 정조는 수원 화성을 축조해 개혁 정치의 중심지로 삼았으므로 ①이 정답이다. ④ 프랑스군의 외규장각 도서 약탈은 1866년 병인양요 때의 일로 시기가 다르다.","ans":1,"pts":2},{"id":"73-28","r":"73","n":28,"era":"개항기","topic":"영선사","exp":"청에 파견되어 톈진 기기국에서 근대식 무기 제조법을 배우고 돌아와 기기창 설립에 힘쓴 사절단은 영선사이므로 ③이 정답이다. 영선사는 1881년 김윤식을 중심으로 파견되었다. ② 수신사는 일본에 보낸 사절단이라서 파견 대상 국가가 다르다.","ans":3,"pts":2},{"id":"73-29","r":"73","n":29,"era":"개항기","topic":"신미양요","exp":"어재연이 전사한 전투는 1871년 신미양요 때 광성보 전투이다. 신미양요 직후 흥선대원군은 전국 각지에 척화비를 세워 통상 수교 거부 의지를 밝혔으므로 ④가 정답이다. ① 병인박해(1866)는 신미양요 이전의 일이라서 답이 아니다.","ans":4,"pts":3},{"id":"73-30","r":"73","n":30,"era":"통합·기타","topic":"충주 지역사","exp":"조동리 유적, 남한 유일의 고구려비(충주 고구려비), 고려의 덕흥창, 신립의 탄금대 전투가 모두 있었던 지역은 충주이므로 ④가 정답이다. 충주는 남한강 물길의 중심지로 시대마다 중요한 역할을 하였다. 지역의 역사를 시대별로 통합해 묻는 문항이다.","ans":4,"pts":2},{"id":"73-31","r":"73","n":31,"era":"개항기","topic":"박규수","exp":"박지원의 손자이며 평안 감사로서 제너럴 셔먼호를 불태운 인물은 박규수이다. 그는 임술 농민 봉기 때 안핵사로 파견되어 삼정이정청 설치를 건의하였으므로 ④가 정답이다. ① 추사체는 김정희, ③ 대동여지도는 김정호가 만든 것이라서 답이 아니다.","ans":4,"pts":2},{"id":"73-32","r":"73","n":32,"era":"개항기","topic":"동학 농민 운동","exp":"황룡촌 전투(1894년 4월)와 우금치 전투(1894년 11월) 사이의 사실을 묻는 문항이다. 황룡촌 승리 후 농민군은 전주성을 점령하고 정부와 전주 화약을 맺었으므로 ③이 정답이다. ④ 고부 관아 습격은 동학 농민 운동의 시작으로 황룡촌 전투보다 앞선 일이다.","ans":3,"pts":3},{"id":"73-33","r":"73","n":33,"era":"개항기","topic":"독립협회","exp":"중추원 관제 개편으로 의관의 절반을 회원 중에서 선출하기로 한 단체는 독립협회이다. 독립협회는 만민 공동회를 열어 민권 신장과 자주 국권 운동을 벌였으므로 ④가 정답이다. ③ 대성 학교 설립은 신민회, ① 잡지 개벽 창간은 천도교의 활동이다.","ans":4,"pts":2},{"id":"73-34","r":"73","n":34,"era":"개항기","topic":"러일 전쟁 시기","exp":"러시아와 일본 사이의 전쟁이 1년 넘게 이어지고 제물포 해전이 언급된 것으로 보아 러일 전쟁(1904~1905) 시기의 대화이다. 1905년 1월 경부선이 개통되었으므로 이 시기에 볼 수 있는 모습은 ①이다. ③ 우정총국 개국 축하연은 1884년 갑신정변, ④ 치안 유지법은 1925년 일제강점기의 일이다.","ans":1,"pts":3},{"id":"73-35","r":"73","n":35,"era":"개항기","topic":"을사늑약","exp":"대한 제국 황제가 외교권을 박탈한 조약의 부당함을 국제 사회에 알리려 했다는 내용에서 1905년 을사늑약임을 알 수 있다. 을사늑약으로 통감부가 설치되고 이토 히로부미가 초대 통감으로 왔으므로 ②가 정답이다. ③ 청일 전쟁(1894)은 이 조약과 관계없는 이전의 일이다.","ans":2,"pts":2},{"id":"73-36","r":"73","n":36,"era":"개항기","topic":"백동화","exp":"전환국에서 발행한 보조 화폐로 화폐 정리 사업 때 발행이 중단된 동전은 백동화이므로 ②가 정답이다. 백동화는 1905년 메가타가 주도한 화폐 정리 사업으로 일본 제일은행권에 밀려 사라졌다. ① 당백전은 흥선대원군이 경복궁 중건 비용을 마련하려고 발행한 것이다.","ans":2,"pts":1},{"id":"73-37","r":"73","n":37,"era":"개항기","topic":"정미의병","exp":"1907년 군대 해산에 반발해 원주진위대의 민긍호 등이 일으킨 의병은 정미의병이다. 정미의병은 13도 창의군을 결성해 서울 진공 작전을 전개하였으므로 ①이 정답이다. ② 조선 혁명 선언은 의열단의 지침이고 ③ 독립 공채 발행은 대한민국 임시 정부의 활동이다.","ans":1,"pts":3},{"id":"73-38","r":"73","n":38,"era":"일제강점기","topic":"1910년대 무단 통치","exp":"회사령, 조선 태형령, 관리와 교원의 제복 착용은 모두 1910년대 무단 통치 시기의 정책이다. 이 시기 일제는 토지 조사 사업(1910~1918)을 실시해 식민 지배의 경제 기반을 마련하였으므로 ③이 정답이다. ④ 경성 제국 대학 설립(1924)은 1920년대 문화 통치기의 일이다.","ans":3,"pts":2},{"id":"73-39","r":"73","n":39,"era":"일제강점기","topic":"3·1 운동","exp":"1919년 3~4월의 만세 시위와 제암리 학살 사건이 나오므로 (가)는 3·1 운동이다. 3·1 운동을 계기로 독립운동을 이끌 통일된 조직의 필요성이 커져 대한민국 임시 정부가 수립되었으므로 ④가 정답이다. ② 국채 보상 운동(1907)은 3·1 운동보다 앞선 경제적 구국 운동이다.","ans":4,"pts":2},{"id":"73-40","r":"73","n":40,"era":"일제강점기","topic":"신간회","exp":"이상재를 회장으로 창립되어 100개가 넘는 지회를 두었고 자매단체로 근우회가 있던 단체는 신간회(1927)이다. 신간회는 광주 학생 항일 운동에 진상 조사단을 파견해 지원하였으므로 ④가 정답이다. ② 신흥 강습소를 세운 것은 신민회 인사들의 활동이라서 답이 아니다.","ans":4,"pts":2},{"id":"73-41","r":"73","n":41,"era":"일제강점기","topic":"물산 장려 운동","exp":"조만식의 주도로 평양에서 시작되었고 '조선 사람 조선 것' 구호를 내건 운동은 물산 장려 운동이므로 ④가 정답이다. 이 운동은 국산품 애용으로 민족 경제를 살리자는 1920년대 실력 양성 운동이다. ② 브나로드 운동은 동아일보가 주도한 문맹 퇴치 운동으로 구분된다.","ans":4,"pts":1},{"id":"73-42","r":"73","n":42,"era":"일제강점기","topic":"민족 말살 통치","exp":"국가 총동원법(1938) 시행, 황국 신민 서사 암송, 일본식 이름 강요는 1930년대 후반 이후 민족 말살 통치기의 모습이다. 이 시기 일제는 애국반을 조직해 공출을 독려하고 전쟁 물자를 수탈하였으므로 ②가 정답이다. ① 한성순보 발행(1883)과 ④ 육영 공원(1886)은 개항기의 일이다.","ans":2,"pts":2},{"id":"73-43","r":"73","n":43,"era":"일제강점기","topic":"홍범도","exp":"대한 독립군 총사령관으로 봉오동 전투를 승리로 이끌었고 카자흐스탄으로 강제 이주당한 인물은 홍범도이므로 ④가 정답이다. 홍범도는 청산리 대첩에도 참여하였고 만년을 크질오르다에서 보냈다. ③ 지청천은 한국 광복군 총사령관을 지낸 인물로 혼동하지 않아야 한다.","ans":4,"pts":2},{"id":"73-44","r":"73","n":44,"era":"일제강점기","topic":"조선 의용대","exp":"김원봉이 중심이 되어 창설되었고 일부가 한국 광복군에 합류한 부대는 조선 의용대(1938)이다. 조선 의용대는 중국 관내(관내 지역)에서 결성된 최초의 한인 무장 조직이므로 ④가 정답이다. ① 청산리 대첩은 북로 군정서 등의 활약이고 ③ 자유시 참변은 대한 독립 군단이 입은 피해이다.","ans":4,"pts":2},{"id":"73-45","r":"73","n":45,"era":"일제강점기","topic":"나운규와 아리랑","exp":"1926년 단성사에서 개봉한 영화 아리랑의 감독이자 주연은 나운규이므로 ②가 정답이다. 아리랑은 나라 잃은 민중의 울분을 담아 큰 호응을 얻은 민족 영화이다. ① 심훈은 소설 상록수를 쓴 작가라서 분야가 다르다.","ans":2,"pts":1},{"id":"73-46","r":"73","n":46,"era":"현대","topic":"박정희 정부","exp":"1977년 수출 100억 달러를 달성한 시기의 정부는 박정희 정부이다. 박정희 정부 시기인 1970년에 경부 고속 도로가 준공되었으므로 ③이 정답이다. ① 개성 공단 조성은 2000년대, ④ 한미 FTA 체결은 노무현 정부 때의 일이다.","ans":3,"pts":2},{"id":"73-47","r":"73","n":47,"era":"현대","topic":"6·25 전쟁","exp":"1·4 후퇴와 흥남 철수로 가족과 헤어졌다는 사연에서 (가)는 6·25 전쟁임을 알 수 있다. 전쟁 중이던 1950년 9월 국군과 유엔군은 인천 상륙 작전으로 전세를 뒤집었으므로 ②가 정답이다. ① 5·10 총선거(1948)와 ④ 조선 건국 준비 위원회 결성(1945)은 전쟁 이전의 일이다.","ans":2,"pts":2},{"id":"73-48","r":"73","n":48,"era":"현대","topic":"김영삼 정부","exp":"지방 자치제 전면 실시, 조선 총독부 건물 철거, OECD 가입은 모두 김영삼 정부 시기의 일이다. 김영삼 정부는 1993년 금융 실명제를 전격 실시하였으므로 ②가 정답이다. ① 베트남 파병은 박정희 정부, ③ 야간 통행 금지 해제는 전두환 정부 시기라서 답이 아니다.","ans":2,"pts":2},{"id":"73-49","r":"73","n":49,"era":"현대","topic":"6월 민주 항쟁","exp":"4·13 호헌 조치에 반대하며 민주 헌법 쟁취 국민 운동 본부를 세우고 대통령 직선제를 요구한 운동은 1987년 6월 민주 항쟁이다. 시위 도중 대학생 이한열이 최루탄에 맞아 희생되었으므로 ④가 정답이다. ② 시민군이 조직된 것은 5·18 민주화 운동의 일이라서 구분해야 한다.","ans":4,"pts":3},{"id":"73-50","r":"73","n":50,"era":"현대","topic":"노태우 정부 통일 노력","exp":"북방 외교로 사회주의 국가들과 수교하고 남북한 유엔 동시 가입(1991)을 이룬 정부는 노태우 정부이다. 노태우 정부는 1991년 남북 기본 합의서를 교환해 상호 화해와 불가침에 합의하였으므로 ①이 정답이다. ③ 7·4 남북 공동 성명은 박정희 정부, ④ 6·15 남북 공동 선언은 김대중 정부의 일이다.","ans":1,"pts":2},{"id":"75-1","r":"75","n":1,"era":"선사·고조선","topic":"구석기 시대","exp":"연천 전곡리 유적과 뗀석기·주먹도끼는 구석기 시대를 알려주는 대표 단서이다. 구석기 사람들은 먹을 것을 찾아 이동하며 주로 동굴이나 강가의 막집에서 살았으므로 ③이 맞다. 반달 돌칼(②)과 가락바퀴(④)는 농경이 시작된 신석기·청동기 시대의 도구이므로 혼동하지 않아야 한다.","ans":3,"pts":1},{"id":"75-2","r":"75","n":2,"era":"삼국·가야","topic":"고구려 장수왕","exp":"승려 도림을 백제에 첩자로 보내고 한성을 함락해 개로왕을 죽인 왕은 광개토 대왕의 아들 장수왕이다. 장수왕은 수도를 국내성에서 평양으로 옮기고 남진 정책을 펼쳐 한강 유역을 차지하였으므로 ③이 맞다. 태학 설립(①)은 소수림왕, 황룡사 구층 목탑(④)은 신라 선덕 여왕 때의 일이다.","ans":3,"pts":2},{"id":"75-3","r":"75","n":3,"era":"선사·고조선","topic":"고조선","exp":"개천절이 기념하는, 단군이 세운 우리 역사상 최초의 나라는 고조선이다. 고조선에는 사회 질서를 유지하기 위한 범금 8조(8조법)가 있어 사람을 죽인 자는 사형에 처하는 등 엄격히 다스렸으므로 ④가 맞다. 동맹(①)은 고구려, 책화(②)는 동예, 사출도(③)는 부여의 풍습이다.","ans":4,"pts":2},{"id":"75-4","r":"75","n":4,"era":"삼국·가야","topic":"가야 문화유산","exp":"고령 지산동 고분군과 여러 고분군이 연맹 체제를 이루었다는 설명은 대가야를 중심으로 한 가야를 가리킨다. 가야 고분에서는 금동관을 비롯한 화려한 껴묻거리가 출토되었으므로 ①이 맞다. 칠지도(②)는 백제가 왜에 보낸 칼이고, 성덕 대왕 신종(③)은 통일 신라의 유물이므로 구분해야 한다.","ans":1,"pts":3},{"id":"75-5","r":"75","n":5,"era":"삼국·가야","topic":"백제 웅진(공주)","exp":"공산성, 무령왕릉, 정지산 유적은 모두 백제의 두 번째 수도 웅진, 즉 지금의 충남 공주에 있는 유적이다. 따라서 지도의 (나) 공주가 답사 지역으로 맞다. 부여(다)는 백제의 마지막 수도 사비이므로 헷갈리지 않도록 주의해야 한다.","ans":2,"pts":2},{"id":"75-6","r":"75","n":6,"era":"남북국","topic":"신라 골품제","exp":"흥덕왕, 진골·6두품 같은 골품에 따라 옷감 사용까지 차등을 둔 나라는 신라이다. 신라는 신문왕 때 유학 교육 기관인 국학을 세워 인재를 길렀으므로 ③이 맞다. 완산주 도읍(①)은 견훤의 후백제, 5도 양계(②)는 고려, 정사암 회의(④)는 백제의 것이다.","ans":3,"pts":2},{"id":"75-7","r":"75","n":7,"era":"삼국·가야","topic":"백제 멸망","exp":"정림사지 오층 석탑에 새겨진 비문은 백제를 멸망시킨 당나라 장수 소정방의 공적을 기록한 것이다. 백제는 660년 신라와 당이 연합한 나당 연합군의 공격으로 멸망했으므로, 이 비문을 탐구하려면 나당 연합군의 활동을 조사하는 ①이 적절하다. 이자겸의 난(②)과 전민변정도감(③)은 고려 시대의 일이다.","ans":1,"pts":3},{"id":"75-8","r":"75","n":8,"era":"남북국","topic":"장보고","exp":"산둥반도에 적산법화원을 세우고 일본 승려 엔닌을 도운 신라인은 장보고이다. 장보고는 완도에 청해진을 설치하고 해적을 소탕하며 동아시아 해상 무역을 장악하였으므로 ④가 맞다. 왕오천축국전(①)은 혜초, 만권당에서의 교유(②)는 고려의 이제현에 해당한다.","ans":4,"pts":1},{"id":"75-9","r":"75","n":9,"era":"남북국","topic":"발해","exp":"대조영이 건국하고 5경 15부 62주의 지방 제도를 갖추었으며 신라와 함께 남북국을 이룬 나라는 발해이다. 발해는 전성기에 중국으로부터 바다 동쪽의 융성한 나라라는 뜻의 해동성국이라 불렸으므로 ④가 맞다. 22담로(②)는 백제 무령왕, 독서삼품과(③)는 통일 신라의 제도이다.","ans":4,"pts":1},{"id":"75-10","r":"75","n":10,"era":"고려","topic":"고려 성종","exp":"최승로가 시무 28조를 올리고 국자감이 창설되었다는 내용에서 밑줄 그은 왕이 고려 성종임을 알 수 있다. 성종은 유교 정치 이념을 바탕으로 전국 주요 지역에 12목을 설치하고 지방관을 파견하였으므로 ③이 맞다. 노비안검법(①)은 광종, 공산 전투(④)는 태조 왕건 시기의 일이다.","ans":3,"pts":2},{"id":"75-11","r":"75","n":11,"era":"고려","topic":"고려 시대 사건 순서","exp":"(가)는 최충헌 집권기에 일어난 만적의 봉기(1198), (나)는 서경에서 대위국을 선포한 묘청의 난(1135), (다)는 정중부 등이 문신을 제거한 무신정변(1170)이다. 시간 순서대로 배열하면 묘청의 난, 무신정변, 만적의 봉기 순이므로 ③ (나)-(다)-(가)가 맞다. 무신정변 이후 신분 해방을 꿈꾼 만적의 봉기가 일어났다는 흐름을 기억하면 쉽다.","ans":3,"pts":3},{"id":"75-12","r":"75","n":12,"era":"고려","topic":"고려 태조 왕건","exp":"후삼국을 통일하고 개태사를 창건한 왕은 고려 태조 왕건이다. 태조는 지방 호족을 견제하고 관리하기 위해 호족 출신을 그 지역 담당자로 삼는 사심관 제도를 시행하였으므로 ③이 맞다. 과거제 도입(①)은 광종, 북한산 순수비(④)는 신라 진흥왕의 업적이므로 구분해야 한다.","ans":3,"pts":2},{"id":"75-13","r":"75","n":13,"era":"고려","topic":"원 간섭기 응방","exp":"원 간섭기에 고려가 원에 바칠 사냥매를 잡고 기르는 일을 맡았던 기구는 응방이다. 매 응(鷹) 자를 쓰는 이름에서 알 수 있듯 충렬왕 때 설치되어 매 사육을 담당했으므로 ②가 맞다. 도방(①)은 무신 정권의 사병 집단, 정방(③)은 최우가 설치한 인사 행정 기구이다.","ans":2,"pts":2},{"id":"75-14","r":"75","n":14,"era":"고려","topic":"최영","exp":"공민왕 때 홍건적을 물리치고, 우왕 때 홍산에서 왜구를 격파했으며 요동 정벌을 추진한 인물은 고려 말의 명장 최영이다. 따라서 ①이 맞다. 최무선(④)은 화약 무기를 개발해 진포에서 왜구를 무찌른 인물이므로 왜구 격퇴라는 공통점 때문에 혼동하지 않도록 주의한다.","ans":1,"pts":1},{"id":"75-15","r":"75","n":15,"era":"고려","topic":"고려 전기 석탑","exp":"고려 전기의 대표 석탑으로 송의 영향을 받았고 각이 많은 다각 다층탑이라는 설명에 해당하는 것은 평창 월정사 팔각 구층 석탑이다. 팔각 지붕돌이 아홉 층으로 쌓인 모습이 특징이므로 ③이 맞다. 개성 경천사지 십층 석탑(④)은 원의 영향을 받은 고려 후기 탑이므로 시기와 영향을 준 나라를 구분해야 한다.","ans":3,"pts":2},{"id":"75-16","r":"75","n":16,"era":"고려","topic":"몽골의 침입","exp":"팔만대장경은 고려가 몽골의 침입을 부처의 힘으로 물리치고자 만든 것이므로 밑줄 그은 시기는 대몽 항쟁기이다. 이때 승려 김윤후가 처인성에서 몽골 장수 살리타를 사살하는 등 크게 활약하였으므로 ③이 맞다. 망이·망소이의 봉기(④)는 몽골 침입 이전인 무신 집권기의 일이다.","ans":3,"pts":2},{"id":"75-17","r":"75","n":17,"era":"고려","topic":"윤관과 별무반","exp":"여진을 정벌하고 동북 9성을 개척한 뒤 고려의 경계라는 비석을 세운 인물은 윤관이다. 윤관은 기병 중심의 여진에 맞서기 위해 신기군·신보군·항마군으로 이루어진 별무반 설치를 건의하였으므로 ③이 맞다. 강동 6주 확보(②)는 거란과 담판한 서희의 활동이다.","ans":3,"pts":2},{"id":"75-18","r":"75","n":18,"era":"고려","topic":"대각국사 의천","exp":"고려의 승려로 문종의 아들이며 송에서 불교를 공부하고 신편제종교장총록을 간행한 인물은 대각국사 의천이다. 의천은 교종을 중심으로 선종을 통합하고자 해동 천태종을 창시하였으므로 ①이 맞다. 수선사 결사(③)는 지눌, 삼국유사(②)는 일연의 활동이므로 승려들끼리 혼동하지 않아야 한다.","ans":1,"pts":2},{"id":"75-19","r":"75","n":19,"era":"조선 전기","topic":"계유정난","exp":"수양 대군이 권력을 잡고 단종을 영월 청령포로 유배 보냈다는 내용에서 (가)는 계유정난임을 알 수 있다. 계유정난(1453)은 수양 대군이 김종서 등 반대 세력을 제거하고 실권을 장악한 사건으로, 이후 그는 세조로 즉위하였다. 따라서 ③이 맞으며, 갑자사화(①)는 연산군 때의 일이다.","ans":3,"pts":2},{"id":"75-20","r":"75","n":20,"era":"조선 후기","topic":"통신사","exp":"에도 막부의 요청으로 조선이 일본에 파견한 공식 사절단은 통신사이다. 통신사는 임진왜란 이후 국교가 회복되면서 파견되어 마상재 공연 등으로 일본에서 큰 인기를 끌며 문화 교류에 이바지했으므로 ④가 맞다. 수신사(①)는 개항 이후 일본에 보낸 사절단이므로 시기가 다르다.","ans":4,"pts":1},{"id":"75-21","r":"75","n":21,"era":"조선 전기","topic":"병자호란","exp":"소현 세자 일행이 청의 수도 심양에 볼모로 끌려갔다는 내용에서 이 전쟁이 병자호란(1636)임을 알 수 있다. 병자호란 때 인조는 남한산성으로 피란해 청군에 맞섰으나 결국 삼전도에서 항복하였으므로 ②가 맞다. 권율의 행주 대첩(①)과 곽재우의 의병 활동(③)은 임진왜란 때의 일이다.","ans":2,"pts":2},{"id":"75-22","r":"75","n":22,"era":"조선 전기","topic":"퇴계 이황","exp":"안동 도산 서원에서 제자들이 기리는 인물, 즉 퇴계는 조선의 대표 성리학자 이황이다. 이황은 성리학의 핵심을 열 가지 그림으로 정리한 성학십도를 지어 선조에게 올렸으므로 ④가 맞다. 목민심서(②)는 정약용, 반계수록(③)은 유형원의 저술이다.","ans":4,"pts":3},{"id":"75-23","r":"75","n":23,"era":"조선 전기","topic":"조광조와 기묘사화","exp":"현량과 실시를 건의하는 장면의 주인공은 중종 때 개혁 정치를 이끈 조광조이다. 조광조의 급진적 개혁에 반발한 훈구 세력의 공격으로 기묘사화(1519)가 일어나 조광조 등 사림이 화를 입었으므로, 이 장면 이후의 사실은 ①이 맞다. 경국대전 반포(③)는 성종 때로 이 장면보다 앞선 일이다.","ans":1,"pts":2},{"id":"75-24","r":"75","n":24,"era":"조선 전기","topic":"훈련도감","exp":"왜란 중에 설치되었고 포수·살수·사수의 삼수병으로 편성되었으며 매달 쌀로 급료를 받았다는 내용은 훈련도감의 특징이다. 훈련도감은 임진왜란 중 유성룡의 건의로 설치된 직업 군인 부대이므로 ④가 맞다. 9서당(①)은 통일 신라의 중앙군, 장용영(③)은 정조가 만든 국왕 친위 부대이다.","ans":4,"pts":2},{"id":"75-25","r":"75","n":25,"era":"조선 후기","topic":"영조","exp":"백성의 군포 부담을 줄이는 균역법을 실시했다는 단서에서 (가) 왕이 영조임을 알 수 있다. 영조는 붕당 간의 다툼을 줄이고자 탕평책을 펴고 성균관 앞에 탕평비를 세웠으므로 ②가 맞다. 집현전 설치(①)는 세종, 초계문신제(④)는 정조의 정책이므로 구분해야 한다.","ans":2,"pts":1},{"id":"75-26","r":"75","n":26,"era":"조선 후기","topic":"박지원","exp":"양반전을 지어 양반의 허례허식을 풍자한 연암은 조선 후기 실학자 박지원이다. 박지원은 청에 다녀온 경험을 담아 열하일기를 저술하고 수레와 선박 이용 등을 주장하였으므로 ④가 맞다. 거중기 설계(③)는 정약용, 추사체(②)는 김정희의 업적이다.","ans":4,"pts":1},{"id":"75-27","r":"75","n":27,"era":"개항기","topic":"조미 수호 통상 조약","exp":"조선이 미국과 조약을 맺은 뒤 민영익 등을 보빙사로 파견했다는 내용에서 이 조약이 조미 수호 통상 조약(1882)임을 알 수 있다. 이 조약은 서양 나라와 맺은 최초의 조약으로, 최혜국 대우가 처음으로 규정되었으므로 ②가 맞다. 운요호 사건(④)은 강화도 조약 체결의 계기이므로 순서를 혼동하지 않아야 한다.","ans":2,"pts":3},{"id":"75-28","r":"75","n":28,"era":"조선 후기","topic":"조선 후기 경제","exp":"민영 수공업 발달, 담배·면화 같은 상품 작물 재배는 모두 조선 후기의 경제 모습이다. 이 시기에는 대동법 실시로 관청에 물품을 조달하는 공인이 활동하였으므로 ④가 맞다. 솔빈부의 말(①)은 발해, 활구 은병(②)은 고려의 경제에 해당한다.","ans":4,"pts":2},{"id":"75-29","r":"75","n":29,"era":"개항기","topic":"박문국","exp":"자료는 우리나라 최초의 근대 신문인 한성순보의 창간 취지로, 신문을 발행한 기구를 묻고 있다. 한성순보는 1883년 설치된 박문국에서 발행되었으므로 ③이 맞다. 기기창(②)은 근대 무기 제조 기구, 전환국(④)은 화폐를 만들던 기구이므로 역할을 구분해야 한다.","ans":3,"pts":2},{"id":"75-30","r":"75","n":30,"era":"개항기","topic":"대한제국과 광무개혁","exp":"1897년 고종이 황제로 즉위하며 선포한 새 국호 (가)는 대한제국이다. 대한제국 시기 광무개혁의 하나로 양전 사업을 벌여 토지 소유 증명서인 지계를 발급하였으므로 ①이 맞다. 신미양요(②)와 거문도 사건(④)은 대한제국 선포 이전의 일이다.","ans":1,"pts":2},{"id":"75-31","r":"75","n":31,"era":"개항기","topic":"보안회","exp":"일본의 황무지 개간권 요구에 반대해 1904년 서울에서 조직된 단체가 (가)에 들어간다. 나라를 지키고 백성을 편안하게 한다는 뜻의 이름을 가진 보안회는 반대 운동을 벌여 일본의 요구를 철회시켰으므로 ②가 맞다. 신민회(④)는 국권 회복을 목표로 한 비밀 결사이므로 활동 내용이 다르다.","ans":2,"pts":1},{"id":"75-32","r":"75","n":32,"era":"개항기","topic":"을미개혁","exp":"1895년 관보에 실린 태양력 사용, 건양 연호 제정, 임금이 먼저 단발한다는 내용은 모두 을미개혁의 조치이다. 따라서 을미개혁의 내용을 조사하는 ①이 가장 적절한 탐구 활동이다. 삼정이정청(③)은 임술 농민 봉기 수습을 위해 설치된 기구로 시기가 훨씬 앞선다.","ans":1,"pts":2},{"id":"75-33","r":"75","n":33,"era":"개항기","topic":"13도 창의군","exp":"전국 의병이 경기도 양주에 집결해 이인영을 총대장으로 추대하고 해산 군인까지 합류했다는 내용에서 (가)는 정미의병 때 결성된 13도 창의군임을 알 수 있다. 13도 창의군은 서울로 진격해 통감부를 몰아내려는 서울 진공 작전을 전개하였으므로 ①이 맞다. 백산 4대 강령(②)은 동학 농민 운동과 관련된 것이다.","ans":1,"pts":2},{"id":"75-34","r":"75","n":34,"era":"일제강점기","topic":"미주 한인 독립운동","exp":"하와이 이주로 시작된 미주 한인들의 삶과 독립운동을 다룬 다큐멘터리이므로 (가)에는 미주 지역의 활동이 들어가야 한다. 미주 한인들은 1910년 샌프란시스코에서 대한인 국민회를 창설해 독립운동 자금을 모으고 외교 활동을 벌였으므로 ④가 맞다. 중광단(①)은 북간도, 신흥 강습소(③)는 서간도에서 조직된 것이므로 지역이 다르다.","ans":4,"pts":3},{"id":"75-35","r":"75","n":35,"era":"개항기","topic":"국채 보상 운동","exp":"나랏빚 1,300만 원을 갚기 위해 담배를 끊고 비녀와 가락지를 모았다는 내용은 1907년 대구에서 시작된 국채 보상 운동이다. 이 운동은 대한매일신보 등 언론의 지원을 받아 전국으로 확산되었으므로 ②가 맞다. 근우회(①)는 일제강점기의 여성 운동 단체이므로 시기가 다르다.","ans":2,"pts":2},{"id":"75-36","r":"75","n":36,"era":"일제강점기","topic":"의열단","exp":"김원봉이 조직했고 단원 김지섭이 도쿄 궁성에 폭탄을 던졌다는 내용에서 (가)는 의열단임을 알 수 있다. 의열단은 신채호가 작성한 조선 혁명 선언을 활동 지침으로 삼아 의열 투쟁을 벌였으므로 ④가 맞다. 105인 사건으로 와해된 단체(①)는 신민회이다.","ans":4,"pts":2},{"id":"75-37","r":"75","n":37,"era":"일제강점기","topic":"광주 학생 항일 운동","exp":"1929년 나주·광주 간 통학 열차에서 한일 학생 충돌을 계기로 일어나 전국으로 확산된 운동은 광주 학생 항일 운동이다. 이때 신간회가 진상 조사단을 파견해 지원하였으므로 ③이 맞다. 순종의 인산일에 일어난 것(①)은 6·10 만세 운동이므로 계기를 구분해야 한다.","ans":3,"pts":2},{"id":"75-38","r":"75","n":38,"era":"일제강점기","topic":"일제강점기 경성의 모습","exp":"서울이 경성으로 불리던 조선 총독부의 식민 통치 시기에 없었던 사실을 골라야 하는 문제이다. 헐버트가 육영 공원 교사로 활동한 것은 1886년 개항기의 일이므로 ③이 시기에 맞지 않는다. 나운규의 아리랑(1926), 손기정의 베를린 올림픽 우승(1936)은 모두 일제강점기의 일이다.","ans":3,"pts":3},{"id":"75-39","r":"75","n":39,"era":"일제강점기","topic":"박상진과 대한 광복회","exp":"1915년 비밀 결사인 대한 광복회를 조직하고 총사령으로 활동한 인물은 박상진이다. 대한 광복회는 친일 부호를 처단하고 독립 자금을 모으는 활동을 벌였으므로 ①이 맞다. 안창호(②)는 흥사단, 윤봉길(③)은 한인 애국단 소속으로 상하이에서 의거한 인물이다.","ans":1,"pts":2},{"id":"75-40","r":"75","n":40,"era":"일제강점기","topic":"연해주 한인 사회","exp":"1937년 소련 당국의 강제 이주 정책으로 한인들이 중앙아시아로 떠난 지역은 연해주이다. 연해주 블라디보스토크에는 한인 집단 거주지인 신한촌이 건설되어 독립운동의 근거지가 되었으므로 ①이 맞다. 봉오동 전투(②)는 만주에서 벌어진 전투이므로 지역을 혼동하지 않아야 한다.","ans":1,"pts":3},{"id":"75-41","r":"75","n":41,"era":"일제강점기","topic":"백범 김구","exp":"한인 애국단을 조직하고 대한민국 임시 정부 주석을 지낸 백범 김구의 활동을 묻는 문제이다. 김구는 광복 후 남한만의 단독 정부 수립에 반대하며 1948년 평양에 가서 남북 협상을 추진하였으므로 ②가 맞다. 흥사단 결성(①)은 안창호, 조선 의용대 창설(③)은 김원봉의 활동이다.","ans":2,"pts":1},{"id":"75-42","r":"75","n":42,"era":"일제강점기","topic":"간송 전형필","exp":"막대한 자금으로 훈민정음 해례본 등 문화유산을 수집하고 보화각을 세운 간송은 전형필이다. 그는 일제강점기에 우리 문화재가 일본으로 빠져나가는 것을 막기 위해 사재를 털어 문화유산을 지켰으므로 ③이 맞다. 주시경(④)은 한글 연구에 힘쓴 국어학자이므로 활동 분야가 다르다.","ans":3,"pts":2},{"id":"75-43","r":"75","n":43,"era":"일제강점기","topic":"조선 혁명군","exp":"양세봉이 총사령으로서 중국 의용군과 연합해 일본군을 격퇴한 부대는 남만주의 조선 혁명군이다. 조선 혁명군은 영릉가 전투 등에서 한중 연합 작전으로 승리를 거두었으므로 ②가 맞다. 영국군의 요청으로 인도·미얀마 전선에 투입된 것(③)은 한국 광복군이다.","ans":2,"pts":3},{"id":"75-44","r":"75","n":44,"era":"일제강점기","topic":"민족 말살 통치기","exp":"일제가 중일 전쟁을 일으키고 군함도 등에 한국인을 강제 동원하던 시기는 1930년대 후반 이후의 민족 말살 통치기이다. 이 시기 일제는 황국 신민 서사를 암송하게 하는 등 한국인의 민족의식을 없애려 했으므로 ②가 맞다. 태형을 집행하는 헌병 경찰(①)은 1910년대 무단 통치기의 모습이다.","ans":2,"pts":2},{"id":"75-45","r":"75","n":45,"era":"현대","topic":"제주 4·3 사건","exp":"남한만의 단독 선거에 반대하는 무장대와 토벌대의 충돌, 그 진압 과정에서 많은 제주 주민이 희생된 사건은 제주 4·3 사건이다. 2000년에 진상 규명 및 희생자 명예 회복에 관한 특별법이 제정되어 희생자들의 명예 회복이 이루어졌으므로 ④가 맞다. 신군부에 저항한 것(③)은 5·18 민주화 운동이므로 구분해야 한다.","ans":4,"pts":2},{"id":"75-46","r":"75","n":46,"era":"현대","topic":"4·19 혁명","exp":"3·15 부정 선거가 전 국민적 분노를 일으켜 그 계기가 된 민주화 운동은 4·19 혁명(1960)이다. 4·19 혁명으로 이승만 대통령이 물러나고 자유당 정권이 무너졌으므로 ②가 맞다. 6월 민주 항쟁(③)은 1987년 대통령 직선제를 요구한 운동이므로 계기가 다르다.","ans":2,"pts":1},{"id":"75-47","r":"75","n":47,"era":"현대","topic":"6·25 전쟁","exp":"유엔군이 인천 상륙 작전에 성공해 서울을 수복했다는 내용에서 이 전쟁이 6·25 전쟁임을 알 수 있다. 전쟁 중 정부가 부산으로 옮겨 가 부산이 임시 수도가 되었으므로 ①이 맞다. 미소 공동 위원회(③)와 반민족 행위 처벌법 제정(④)은 전쟁 이전인 광복 직후의 일이다.","ans":1,"pts":2},{"id":"75-48","r":"75","n":48,"era":"현대","topic":"1970년대의 모습","exp":"유신 헌법 공포, 장발 단속, 청년 문화 유행과 나란히 들어갈 1970년대의 장면을 찾는 문제이다. 1977년 수출 100억 달러를 달성해 기념식이 열렸으므로 ②가 맞다. 금융 실명제(①)는 1993년 김영삼 정부, APEC 정상 회의(④)는 2005년의 일이므로 시기가 맞지 않는다.","ans":2,"pts":3},{"id":"75-49","r":"75","n":49,"era":"현대","topic":"김대중 정부","exp":"노벨 평화상을 수상하고 북한과의 평화와 화해에 힘쓴 대통령은 김대중이다. 김대중 정부 시기인 2000년 평양에서 최초의 남북 정상 회담이 열려 6·15 남북 공동 선언이 발표되었으므로 ②가 맞다. 남북한 유엔 동시 가입(①)과 한반도 비핵화 공동 선언(③)은 노태우 정부 시기의 일이다.","ans":2,"pts":2},{"id":"75-50","r":"75","n":50,"era":"통합·기타","topic":"지하철 역명 속 역사","exp":"지하철 역명에 담긴 인물들의 활동을 시대 통합적으로 묻는 문제이다. 충정로의 충정은 을사늑약으로 외교권이 박탈되자 자결로 항의한 민영환의 시호이므로 ④가 맞다. 을지문덕(가)은 살수 대첩, 강감찬(나)은 귀주 대첩, 이순신(다)은 임진왜란의 인물이므로 나머지 선지는 짝이 틀렸다.","ans":4,"pts":2}]};
